(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-046"]={"sura":46,"name_ar":"الأحقاف","name_en":"Al-Ahqaf","verses":35,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":35,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=6\" class=\"link\">46:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:6 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=6\" class=\"link\">46:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:6 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=6\" class=\"link\">46:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:6 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=6\" class=\"link\">46:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=6\" class=\"link\">46:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் திருப்பெயரால்.<br />\r\n<br />\r\n<strong>குர்ஆன் அல்லாஹ்விடமிருந்து வந்த வஹீ (இறைச்செய்தி) மற்றும் இப்பிரபஞ்சம் அவனது உண்மையான படைப்பாகும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حم</span> <span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">﴾تَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الْحَكِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஹாமீம்) தனித்தனி எழுத்துக்களுக்கான விளக்கம் சூரத்துல் பகராவின் ஆரம்பத்தில் சென்றுவிட்டது. தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களுக்கு இந்த வேதத்தை அருளியிருப்பதாக அல்லாஹ் கூறுகிறான். பின்னர் அல்லாஹ், தன்னை கற்பனை செய்ய முடியாத கண்ணியமிக்கவனாகவும், தனது கூற்றுகளிலும் செயல்களிலும் மேலான ஞானம் கொண்டவனாகவும் விவரிக்கிறான். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ﴿</span><br />\r\n<br />\r\n(நாம் வானங்களையும், பூமியையும், அவற்றுக்கு இடையே உள்ளவற்றையும் உண்மையான காரணத்துடனேயே அன்றிப் படைக்கவில்லை,) அதாவது, வீண் விளையாட்டுக்காகவோ அல்லது வீணாகவோ (அவற்றைப் படைக்கவில்லை).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَجَلٌ</span> <span class=\"quran-arabic-font text-success\">مُّسَمًّى﴿</span><br />\r\n<br />\r\n(மேலும், ஒரு குறிப்பிட்ட தவணைக்காகவே (அவற்றைப் படைத்தோம்).) அதாவது, அது அதிகரிக்கவோ அல்லது குறையவோ முடியாத ஒரு நிலையான மற்றும் நிர்ணயிக்கப்பட்ட கால அளவாகும். அல்லாஹ் தொடர்கிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">عَمَّآ</span> <span class=\"quran-arabic-font text-success\">أُنذِرُواْ</span> <span class=\"quran-arabic-font text-success\">مُعْرِضُونَ﴿</span><br />\r\n<br />\r\n(ஆனால் நிராகரிப்பவர்கள், தங்களுக்கு எச்சரிக்கை செய்யப்பட்டவற்றை விட்டும் புறக்கணிக்கிறார்கள்.) அதாவது, நிராகரிப்பவர்கள் எதற்காகப் படைக்கப்பட்டார்களோ அதை விட்டும் திசைதிருப்பப்படுகிறார்கள். நிச்சயமாக அல்லாஹ் அவர்களுக்கு ஒரு வேதத்தை அருளி, அவர்களிடம் ஒரு தூதரை அனுப்பினான். இருப்பினும், அவர்கள் பிடிவாதமாக இவை அனைத்தையும் புறக்கணிக்கிறார்கள். எனவே, அவர்கள் விரைவில் தங்கள் செயல்களின் விளைவை உணர்ந்துகொள்வார்கள்.<br />\r\n<br />\r\n<strong>இணைவைப்பாளர்களுக்கு மறுப்பு</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ﴿</span><br />\r\n<br />\r\n(கூறுவீராக!) அதாவது, அல்லாஹ்வையன்றி மற்றவர்களை வணங்கும் இந்த இணைவைப்பாளர்களிடம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَرَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَرُونِى</span> <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">خَلَقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வையன்றி நீங்கள் அழைப்பவற்றைப் பற்றிச் சிந்தித்தீர்களா? அவர்கள் பூமியில் எதைப் படைத்தார்கள் என்பதை எனக்குக் காட்டுங்கள்) (<a href=\"qurandisp.php?sura=46&ayah=4\" class=\"link\">46:4</a>). அதாவது, 'பூமியில் அவர்கள் சுயமாகப் படைத்த ஏதேனும் ஒரு பகுதியை எனக்குக் காட்டுங்கள்' (என்று நபியே கூறவும்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">شِرْكٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ﴿</span><br />\r\n<br />\r\n(அல்லது வானங்களில் அவர்களுக்குப் பங்குண்டா?) அதாவது, அவர்கள் வானங்களிலோ அல்லது பூமியிலோ எதிலும் கூட்டாளிகள் அல்ல. அவர்கள் ஒரு பேரீச்சம்பழக் கொட்டையின் மேல் உள்ள மெல்லிய சவ்வுக்குக் கூட உரிமையாளர்கள் அல்ல. அதிகாரம் மற்றும் கட்டுப்பாடு அனைத்தும் உயர்ந்தோனாகிய அல்லாஹ்வுக்கு மட்டுமே உரியது. \"அப்படியிருக்க, நீங்கள் அல்லாஹ்வுக்கு இணையாக மற்றவர்களை எவ்வாறு வணங்குவீர்கள்? இதற்கு உங்களுக்கு வழிகாட்டியவர் யார்? அல்லது உங்களை இதற்கு அழைத்தவர் யார்? இதைச் செய்யும்படி அவன் உங்களுக்குக் கட்டளையிட்டானா? அல்லது இது நீங்களாகவே கற்பனை செய்து கொண்ட ஒன்றா?\" எனவே, அவன் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ائْتُونِى</span> <span class=\"quran-arabic-font text-success\">بِكِتَـبٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">هَـذَآ﴿</span><br />\r\n<br />\r\n(இதற்கு முந்தைய ஒரு வேதத்தை என்னிடம் கொண்டு வாருங்கள்) அதாவது, 'இந்தச் சிலைகளை வணங்கும்படி உங்களுக்குக் கட்டளையிடும் வகையில், இதற்கு முன்னர் இறைத்தூதர்களுக்கு அருளப்பட்ட அல்லாஹ்வின் வேதங்களில் ஏதேனும் ஒன்றைக் கொண்டு வாருங்கள்'.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">أَثَـرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ﴿</span><br />\r\n<br />\r\n(அல்லது அறிவின் ஏதேனும் ஒரு சான்று,) அதாவது, 'நீங்கள் தேர்ந்தெடுத்த இந்த வழியை நியாயப்படுத்தும் தெளிவான ஏதேனும் ஓர் ஆதாரம்'.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">صَـدِقِينَ﴿</span><br />\r\n<br />\r\n(நீங்கள் உண்மையாளர்களாக இருந்தால்!) அதாவது, 'அதற்கு உங்களிடம் எவ்வித ஆதாரமும் இல்லை - (வஹீயிலிருந்து வந்த) வேதப்பூர்வமான ஆதாரமோ அல்லது பகுத்தறிவுப்பூர்வமான ஆதாரமோ உங்களிடம் இல்லை'. இந்தக் காரணத்தினாலேயே, சிலர் இதனை (<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَثَرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span>) - \"அல்லது அறிவிலிருந்து பெறப்பட்ட ஒன்று\" என்று ஓதினார்கள். அதாவது, 'உங்களுக்கு முன்னிருந்தவர்களிடமிருந்து நீங்கள் பெற்றுக்கொண்ட உண்மையான அறிவு'. இது முஜாஹித் அவர்களின் கூற்றைப் போன்றதாகும். அவர் கூறினார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">أَثَـرَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ﴿</span><br />\r\n<br />\r\n(அல்லது அறிவின் ஏதேனும் ஒரு சான்று,) \"அல்லது அறிவை வாரிசாகப் பெற்ற எவரும்.\" பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">مِمَّن</span> <span class=\"quran-arabic-font text-success\">يَدْعُو</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَجِيبُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">دُعَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">غَـفِلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வையன்றி, மறுமை நாள் வரை தங்களுக்குப் பதிலளிக்காதவர்களையும், தங்களை அழைப்பதைப் பற்றி உணராதவர்களையும் அழைப்பவரை விட அதிக வழிகேட்டில் இருப்பவர் யார்?) அதாவது, அல்லாஹ்வை விடுத்துச் சிலைகளை அழைப்பவர்களை விட அதிக வழிகேட்டில் எவரும் இல்லை; மறுமை நாள் வரை அவர்களால் தர முடியாதவற்றை அவர்கள் அச் சிலைகளிடம் கேட்கிறார்கள். அந்தச் சிலைகள் அவன் கேட்பதை உணர்வதில்லை. அவைகளால் கேட்கவோ, பார்க்கவோ அல்லது செயல்படவோ முடியாது. ஏனெனில் அவை உயிரற்ற, உணர்வற்ற கற்களாகும். பின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">حُشِرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْدَآءً</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் மனிதர்கள் ஒன்று திரட்டப்படும்போது (மறுமையில்), அந்தச் சிலைகள் இவர்களுக்குப் பகைவர்களாகி, இவர்களது வணக்கத்தையே நிராகரித்து விடுவார்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاتَّخَذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ءالِهَةً</span> <span class=\"quran-arabic-font text-success\">لِّيَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عِزّاً</span> <span class=\"quran-arabic-font text-success\">﴿﴾كَلاَّ</span> <span class=\"quran-arabic-font text-success\">سَيَكْفُرُونَ</span> <span class=\"quran-arabic-font text-success\">بِعِبَـدَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَيَكُونُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">ضِدّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்களுக்குக் கண்ணியத்தைத் தேடித் தருவதற்காக அல்லாஹ்வையன்றி (வேறு) தெய்வங்களை எடுத்துக் கொண்டார்கள். அவ்வாறல்ல! அவை இவர்களின் வணக்கத்தை நிராகரித்து விட்டு, இவர்களுக்கு எதிரிகளாக மாறிவிடும்.) (<a href=\"qurandisp.php?sura=19&ayah=81\" class=\"link\">19:81</a>, 82). அதாவது, இவர்களுக்கு மிகவும் தேவைப்படும் நேரத்தில் அவை இவர்களைக் கைவிட்டு விடும். இப்ராஹீம் அல்-கலீல் (அலை) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">اتَّخَذْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَوْثَـناً</span> <span class=\"quran-arabic-font text-success\">مَّوَدَّةَ</span> <span class=\"quran-arabic-font text-success\">بَيْنِكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">يَكْفُرُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">وَيَلْعَنُ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span> <span class=\"quran-arabic-font text-success\">وَمَأْوَاكُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّـصِرِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்கள் அல்லாஹ்வையன்றிச் சிலைகளையே (தெய்வங்களாக) எடுத்துக் கொண்டீர்கள். உங்களுக்கு இடையேயான இந்த நட்பு இவ்வுலக வாழ்க்கையோடு சரி; ஆனால் மறுமை நாளில் நீங்கள் ஒருவரையொருவர் நிராகரித்து, ஒருவரையொருவர் சபித்துக் கொள்வீர்கள். உங்கள் தங்குமிடம் நரகமாகும்; மேலும் உங்களுக்கு உதவி செய்வோர் எவரும் இருக்க மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=29&ayah=25\" class=\"link\">29:25</a>)<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் திருப்பெயரால்.\n\r\n\n\r\nகுர்ஆன் அல்லாஹ்விடமிருந்து வந்த வஹீ (இறைச்செய்தி) மற்றும் இப்பிரபஞ்சம் அவனது உண்மையான படைப்பாகும்\n\r\n\n\r\n﴾حم ﴿ ﴾تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ ﴿\n\r\n\n\r\n(ஹாமீம்) தனித்தனி எழுத்துக்களுக்கான விளக்கம் சூரத்துல் பகராவின் ஆரம்பத்தில் சென்றுவிட்டது. தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களுக்கு இந்த வேதத்தை அருளியிருப்பதாக அல்லாஹ் கூறுகிறான். பின்னர் அல்லாஹ், தன்னை கற்பனை செய்ய முடியாத கண்ணியமிக்கவனாகவும், தனது கூற்றுகளிலும் செயல்களிலும் மேலான ஞானம் கொண்டவனாகவும் விவரிக்கிறான். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\n﴾مَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَآ إِلاَّ بِالْحَقِّ﴿\n\r\n\n\r\n(நாம் வானங்களையும், பூமியையும், அவற்றுக்கு இடையே உள்ளவற்றையும் உண்மையான காரணத்துடனேயே அன்றிப் படைக்கவில்லை,) அதாவது, வீண் விளையாட்டுக்காகவோ அல்லது வீணாகவோ (அவற்றைப் படைக்கவில்லை).\n\r\n\n\r\n﴾وَأَجَلٌ مُّسَمًّى﴿\n\r\n\n\r\n(மேலும், ஒரு குறிப்பிட்ட தவணைக்காகவே (அவற்றைப் படைத்தோம்).) அதாவது, அது அதிகரிக்கவோ அல்லது குறையவோ முடியாத ஒரு நிலையான மற்றும் நிர்ணயிக்கப்பட்ட கால அளவாகும். அல்லாஹ் தொடர்கிறான்,\n\r\n\n\r\n﴾وَالَّذِينَ كَفَرُواْ عَمَّآ أُنذِرُواْ مُعْرِضُونَ﴿\n\r\n\n\r\n(ஆனால் நிராகரிப்பவர்கள், தங்களுக்கு எச்சரிக்கை செய்யப்பட்டவற்றை விட்டும் புறக்கணிக்கிறார்கள்.) அதாவது, நிராகரிப்பவர்கள் எதற்காகப் படைக்கப்பட்டார்களோ அதை விட்டும் திசைதிருப்பப்படுகிறார்கள். நிச்சயமாக அல்லாஹ் அவர்களுக்கு ஒரு வேதத்தை அருளி, அவர்களிடம் ஒரு தூதரை அனுப்பினான். இருப்பினும், அவர்கள் பிடிவாதமாக இவை அனைத்தையும் புறக்கணிக்கிறார்கள். எனவே, அவர்கள் விரைவில் தங்கள் செயல்களின் விளைவை உணர்ந்துகொள்வார்கள்.\n\r\n\n\r\nஇணைவைப்பாளர்களுக்கு மறுப்பு\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\n﴾قُلْ﴿\n\r\n\n\r\n(கூறுவீராக!) அதாவது, அல்லாஹ்வையன்றி மற்றவர்களை வணங்கும் இந்த இணைவைப்பாளர்களிடம்.\n\r\n\n\r\n﴾أَرَأَيْتُمْ مَّا تَدْعُونَ مِن دُونِ اللَّهِ أَرُونِى مَاذَا خَلَقُواْ مِنَ الْأَرْضِ﴿\n\r\n\n\r\n(அல்லாஹ்வையன்றி நீங்கள் அழைப்பவற்றைப் பற்றிச் சிந்தித்தீர்களா? அவர்கள் பூமியில் எதைப் படைத்தார்கள் என்பதை எனக்குக் காட்டுங்கள்) (46:4). அதாவது, 'பூமியில் அவர்கள் சுயமாகப் படைத்த ஏதேனும் ஒரு பகுதியை எனக்குக் காட்டுங்கள்' (என்று நபியே கூறவும்).\n\r\n\n\r\n﴾أَمْ لَهُمْ شِرْكٌ فِى السَّمَاوَاتِ﴿\n\r\n\n\r\n(அல்லது வானங்களில் அவர்களுக்குப் பங்குண்டா?) அதாவது, அவர்கள் வானங்களிலோ அல்லது பூமியிலோ எதிலும் கூட்டாளிகள் அல்ல. அவர்கள் ஒரு பேரீச்சம்பழக் கொட்டையின் மேல் உள்ள மெல்லிய சவ்வுக்குக் கூட உரிமையாளர்கள் அல்ல. அதிகாரம் மற்றும் கட்டுப்பாடு அனைத்தும் உயர்ந்தோனாகிய அல்லாஹ்வுக்கு மட்டுமே உரியது. \"அப்படியிருக்க, நீங்கள் அல்லாஹ்வுக்கு இணையாக மற்றவர்களை எவ்வாறு வணங்குவீர்கள்? இதற்கு உங்களுக்கு வழிகாட்டியவர் யார்? அல்லது உங்களை இதற்கு அழைத்தவர் யார்? இதைச் செய்யும்படி அவன் உங்களுக்குக் கட்டளையிட்டானா? அல்லது இது நீங்களாகவே கற்பனை செய்து கொண்ட ஒன்றா?\" எனவே, அவன் கூறுகிறான்,\n\r\n\n\r\n﴾ائْتُونِى بِكِتَـبٍ مِّن قَبْلِ هَـذَآ﴿\n\r\n\n\r\n(இதற்கு முந்தைய ஒரு வேதத்தை என்னிடம் கொண்டு வாருங்கள்) அதாவது, 'இந்தச் சிலைகளை வணங்கும்படி உங்களுக்குக் கட்டளையிடும் வகையில், இதற்கு முன்னர் இறைத்தூதர்களுக்கு அருளப்பட்ட அல்லாஹ்வின் வேதங்களில் ஏதேனும் ஒன்றைக் கொண்டு வாருங்கள்'.\n\r\n\n\r\n﴾أَوْ أَثَـرَةٍ مِّنْ عِلْمٍ﴿\n\r\n\n\r\n(அல்லது அறிவின் ஏதேனும் ஒரு சான்று,) அதாவது, 'நீங்கள் தேர்ந்தெடுத்த இந்த வழியை நியாயப்படுத்தும் தெளிவான ஏதேனும் ஓர் ஆதாரம்'.\n\r\n\n\r\n﴾إِن كُنتُمْ صَـدِقِينَ﴿\n\r\n\n\r\n(நீங்கள் உண்மையாளர்களாக இருந்தால்!) அதாவது, 'அதற்கு உங்களிடம் எவ்வித ஆதாரமும் இல்லை - (வஹீயிலிருந்து வந்த) வேதப்பூர்வமான ஆதாரமோ அல்லது பகுத்தறிவுப்பூர்வமான ஆதாரமோ உங்களிடம் இல்லை'. இந்தக் காரணத்தினாலேயே, சிலர் இதனை (أَوْ أَثَرَةٍ مِنْ عِلْمٍ) - \"அல்லது அறிவிலிருந்து பெறப்பட்ட ஒன்று\" என்று ஓதினார்கள். அதாவது, 'உங்களுக்கு முன்னிருந்தவர்களிடமிருந்து நீங்கள் பெற்றுக்கொண்ட உண்மையான அறிவு'. இது முஜாஹித் அவர்களின் கூற்றைப் போன்றதாகும். அவர் கூறினார்:\n\r\n\n\r\n﴾أَوْ أَثَـرَةٍ مِّنْ عِلْمٍ﴿\n\r\n\n\r\n(அல்லது அறிவின் ஏதேனும் ஒரு சான்று,) \"அல்லது அறிவை வாரிசாகப் பெற்ற எவரும்.\" பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\n﴾وَمَنْ أَضَلُّ مِمَّن يَدْعُو مِن دُونِ اللَّهِ مَن لاَّ يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَـمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـفِلُونَ ﴿\n\r\n\n\r\n(அல்லாஹ்வையன்றி, மறுமை நாள் வரை தங்களுக்குப் பதிலளிக்காதவர்களையும், தங்களை அழைப்பதைப் பற்றி உணராதவர்களையும் அழைப்பவரை விட அதிக வழிகேட்டில் இருப்பவர் யார்?) அதாவது, அல்லாஹ்வை விடுத்துச் சிலைகளை அழைப்பவர்களை விட அதிக வழிகேட்டில் எவரும் இல்லை; மறுமை நாள் வரை அவர்களால் தர முடியாதவற்றை அவர்கள் அச் சிலைகளிடம் கேட்கிறார்கள். அந்தச் சிலைகள் அவன் கேட்பதை உணர்வதில்லை. அவைகளால் கேட்கவோ, பார்க்கவோ அல்லது செயல்படவோ முடியாது. ஏனெனில் அவை உயிரற்ற, உணர்வற்ற கற்களாகும். பின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\n﴾وَإِذَا حُشِرَ النَّاسُ كَانُواْ لَهُمْ أَعْدَآءً وَكَانُواْ بِعِبَادَتِهِمْ كَـفِرِينَ ﴿\n\r\n\n\r\n(மேலும் மனிதர்கள் ஒன்று திரட்டப்படும்போது (மறுமையில்), அந்தச் சிலைகள் இவர்களுக்குப் பகைவர்களாகி, இவர்களது வணக்கத்தையே நிராகரித்து விடுவார்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\n﴾وَاتَّخَذُواْ مِن دُونِ اللَّهِ ءالِهَةً لِّيَكُونُواْ لَهُمْ عِزّاً ﴿﴾كَلاَّ سَيَكْفُرُونَ بِعِبَـدَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدّاً ﴿\n\r\n\n\r\n(அவர்கள் தங்களுக்குக் கண்ணியத்தைத் தேடித் தருவதற்காக அல்லாஹ்வையன்றி (வேறு) தெய்வங்களை எடுத்துக் கொண்டார்கள். அவ்வாறல்ல! அவை இவர்களின் வணக்கத்தை நிராகரித்து விட்டு, இவர்களுக்கு எதிரிகளாக மாறிவிடும்.) (19:81, 82). அதாவது, இவர்களுக்கு மிகவும் தேவைப்படும் நேரத்தில் அவை இவர்களைக் கைவிட்டு விடும். இப்ராஹீம் அல்-கலீல் (அலை) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾إِنَّمَا اتَّخَذْتُمْ مِّن دُونِ اللَّهِ أَوْثَـناً مَّوَدَّةَ بَيْنِكُمْ فِى الْحَيَوةِ الدُّنْيَا ثُمَّ يَوْمَ الْقِيَـمَةِ يَكْفُرُ بَعْضُكُمْ بِبَعْضٍ وَيَلْعَنُ بَعْضُكُمْ بَعْضاً وَمَأْوَاكُمُ النَّارُ وَمَا لَكُمْ مِّن نَّـصِرِينَ﴿\n\r\n\n\r\n(நிச்சயமாக நீங்கள் அல்லாஹ்வையன்றிச் சிலைகளையே (தெய்வங்களாக) எடுத்துக் கொண்டீர்கள். உங்களுக்கு இடையேயான இந்த நட்பு இவ்வுலக வாழ்க்கையோடு சரி; ஆனால் மறுமை நாளில் நீங்கள் ஒருவரையொருவர் நிராகரித்து, ஒருவரையொருவர் சபித்துக் கொள்வீர்கள். உங்கள் தங்குமிடம் நரகமாகும்; மேலும் உங்களுக்கு உதவி செய்வோர் எவரும் இருக்க மாட்டார்கள்.) (29:25)"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=9\" class=\"link\">46:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:9 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=9\" class=\"link\">46:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:9 ஐ பார்க்கவும்"},"9":{"html":"<strong>குர்ஆன் மற்றும் தூதரைப் பற்றி இணைவைப்பாளர்களின் கூற்றுக்களுக்கு மறுப்பு</strong><br />\r\n<br />\r\nஇணைவைப்பாளர்களின் குஃப்ர் (நிராகரிப்பு) மற்றும் வரம்பு மீறல் குறித்து அல்லாஹ் கூறுகிறான்: அல்லாஹ்வின் தெளிவான வசனங்கள் அவர்களுக்கு ஓதிக் காட்டப்படும்போது, அவர்கள்; <span class=\"quran-arabic-font text-success\">﴾هَـذَا</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ﴿</span> (இது தெளிவான சூனியம்!) என்று கூறுகின்றனர். அதாவது, இது வெறும் சூனியம் என்பது அவர்களின் கருத்து. தங்களுடைய இக்கூற்றின் மூலம் அவர்கள் பொய் உரைத்து, ஒரு அவதூறை இட்டுக்கட்டி, வழிதவறி, நிராகரித்துவிட்டனர்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">افْتَرَاهُ﴿</span> (அல்லது, \"அவர் இதனை இட்டுக்கட்டிவிட்டார்\" என்று அவர்கள் கூறுகிறார்களா?) அவர்கள் முஹம்மது (ஸல்) அவர்களையே குறிப்பிடுகிறார்கள். இதற்குப் பதிலாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنِ</span> <span class=\"quran-arabic-font text-success\">افْتَرَيْتُهُ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً﴿</span> (கூறுவீராக: \"நான் இதனை இட்டுக்கட்டியிருந்தால், அல்லாஹ்விடமிருந்து (ஏற்படும் தண்டனையிலிருந்து) என்னைக் காப்பாற்ற உங்களுக்கு எவ்வித அதிகாரமும் இல்லை...\") இதன் பொருள்: \"நான் அல்லாஹ்வின் மீது பொய் சொல்லி, அவன் என்னை அனுப்பாத போதே அவன் என்னை அனுப்பியதாகப் பொய்யாக வாதிட்டால், அவன் என்னைக் கடுமையான முறையில் தண்டிப்பான். அப்போது பூமியில் உள்ள உங்களாலோ அல்லது வேறு எவராலோ அவனிடமிருந்து என்னைக் காப்பாற்ற முடியாது\" என்பதாகும். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">يُجِيرَنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">وَلَنْ</span> <span class=\"quran-arabic-font text-success\">أَجِدَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">مُلْتَحَداً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَلاَغاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرِسَالَاتِهِ﴿</span> (கூறுவீராக: \"நிச்சயமாக அல்லாஹ்விடமிருந்து என்னை எவரும் பாதுகாக்க முடியாது. அவனையன்றி வேறொரு புகலிடத்தையும் நான் காணமாட்டேன். (எனது கடமை) அல்லாஹ்விடமிருந்து (வரும் செய்தியை) எடுத்துரைப்பதும், அவனது தூதுச் செய்திகளை (மக்களுக்குச் சேர்ப்பிப்பதும்) மட்டுமே.\") (<a href=\"qurandisp.php?sura=72&ayah=22\" class=\"link\">72:22</a>-23)<br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَقَوَّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَ</span> <span class=\"quran-arabic-font text-success\">الْأَقَاوِيلِ</span> - <span class=\"quran-arabic-font text-success\">لأَخَذْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">بِالْيَمِينِ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَقَطَعْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">الْوَتِينَ</span> - <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">مِنكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">حَاجِزِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும், அவர் நம் மீது சில பொய்களை இட்டுக்கட்டியிருந்தால், நிச்சயமாக நாம் அவருடைய வலக்கையைப் பற்றிப் பிடித்திருப்போம். பின்னர், அவருடைய உயிர்நாடியைத் துண்டித்திருப்போம். அப்போது உங்களில் எவரும் அவரை (தண்டிப்பதிலிருந்து) நம்மைத் தடுத்து நிறுத்த முடியாது.) (<a href=\"qurandisp.php?sura=69&ayah=44\" class=\"link\">69:44</a>-47)<br />\r\n<br />\r\n<br />\r\nஎனவேதான் அல்லாஹ் இங்கு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">إِنِ</span> <span class=\"quran-arabic-font text-success\">افْتَرَيْتُهُ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تُفِيضُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">كَفَى</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">شَهِيداً</span> <span class=\"quran-arabic-font text-success\">بَيْنِى</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَكُمْ﴿</span> (கூறுவீராக: \"நான் இதனை இட்டுக்கட்டியிருந்தாலும், அல்லாஹ்விடமிருந்து (வரும் தண்டனையிலிருந்து) என்னைக் காக்க உங்களுக்கு எந்த சக்தியும் இல்லை. நீங்கள் இதனைப் பற்றி (அதாவது இந்தக் குர்ஆனைப் பற்றி) உங்களுக்குள் என்ன பேசிக் கொள்கிறீர்கள் என்பதை அவன் நன்கு அறிவான்! எனக்கும் உங்களுக்கும் இடையில் சாட்சியாக அவனே போதுமானவன்!...\") இது அவர்களுக்கு விடுக்கப்பட்ட கடுமையான அச்சுறுத்தலும் எச்சரிக்கையுமாகும்.<br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْغَفُورُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ﴿</span> (மேலும், அவன் மிகவும் மன்னிப்பவன், நிகரற்ற அன்புடையவன்.) இது அவர்கள் தௌபா (பாவமன்னிப்பு) செய்து அல்லாஹ்வின் பக்கம் திரும்புவதற்கான ஒரு ஊக்குவிப்பாகும். அதாவது, \"இவை அனைத்தையும் மீறி, நீங்கள் திருந்தி பாவமன்னிப்புக் கோரினால், அல்லாஹ் உங்கள் பாவமன்னிப்பை ஏற்றுக்கொண்டு, உங்களை மன்னித்து உங்கள் மீது கருணை காட்டுவான்\" என்று பொருள்படும். இது சூரத்துல் ஃபுர்கானில் அல்லாஹ் கூறுவதைப் போன்றது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَسَاطِيرُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">اكْتَتَبَهَا</span> <span class=\"quran-arabic-font text-success\">فَهِىَ</span> <span class=\"quran-arabic-font text-success\">تُمْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">بُكْرَةً</span> <span class=\"quran-arabic-font text-success\">وَأَصِيلاً</span> - <span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும் அவர்கள் கூறுகின்றனர்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவர் இவற்றை எழுதிக் கொண்டார். இவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக் காட்டப்படுகின்றன.\" (நபியே!) நீர் கூறுவீராக: \"வானங்களிலும் பூமியிலும் உள்ள இரகசியங்களை அறிபவனே இதனை இறக்கி வைத்தான். நிச்சயமாக அவன் மிகவும் மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்.\") (<a href=\"qurandisp.php?sura=25&ayah=5\" class=\"link\">25:5</a>-6)<br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُ</span> <span class=\"quran-arabic-font text-success\">بِدْعاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلِ﴿</span> (கூறுவீராக: \"தூதர்களில் நான் ஒரு புதியவன் அல்ல...\") இதன் பொருள்: \"உலகிற்கு வந்த முதல் தூதன் நான் அல்ல. மாறாக, எனக்கு முன்னரும் பல தூதர்கள் வந்துள்ளனர். எனவே, என்னை நீங்கள் நிராகரிப்பதற்கும், எனது தூதுத்துவத்தில் சந்தேகம் கொள்வதற்கும் நான் ஒன்றும் இதுவரை நடக்காத ஒரு புதிய நிகழ்வு அல்ல. நிச்சயமாக, அல்லாஹ் எனக்கு முன்னர் பல்வேறு சமுதாயங்களுக்கு அனைத்து நபிமார்களையும் அனுப்பியுள்ளான்.\"<br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَدْرِى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُفْعَلُ</span> <span class=\"quran-arabic-font text-success\">بِى</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بِكُمْ﴿</span> (மேலும், என்னைப் பற்றியோ அல்லது உங்களைப் பற்றியோ என்ன செய்யப்படும் என்பதை நான் அறியமாட்டேன்.) அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"இந்த வசனத்தைத் தொடர்ந்து வஹீ (இறைச்செய்தி)யாக பின்வரும் வசனம் இறங்கியது:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ﴿</span> (உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக). அதேபோல், இக்ரிமா, அல்-ஹஸன் மற்றும் கத்தாதா (ரஹ்) ஆகியோர் இந்த ஆயத் (வசனம்), பின்வரும் வசனத்தினால் மாற்றப்பட்டது (நஸக் செய்யப்பட்டது) என்று கூறுகின்றனர்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِّيَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقَدَّمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَنبِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَأَخَّرَ﴿</span> (உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக). இந்த வசனம் அருளப்பட்டபோது, முஸ்லிம்களில் ஒருவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம், \"அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்பதைத் தெளிவுபடுத்திவிட்டான். ஆனால் எங்களுக்கு என்ன செய்வான்?\" என்று கேட்டார். அப்போது அல்லாஹ் இதனை அருளினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِّيُدْخِلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الْأَنْهَارُ﴿</span> (நம்பிக்கை கொண்ட ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளில் அவன் புகுத்துவதற்காக). இதுவே அவர்கள் கூறிய கருத்தாகும். எனினும், ஸஹீஹான (ஆதாரப்பூர்வமான) செய்திகளில் உறுதிப்படுத்தப்பட்டது என்னவென்றால், நம்பிக்கையாளர்கள், \"அல்லாஹ்வின் தூதரே (ஸல்)! இது உங்களுக்கு மகிழ்ச்சியளிக்கட்டும். ஆனால் எங்களது நிலை என்ன?\" என்று கேட்டனர். அதன்பின்னரே அல்லாஹ் இந்த வசனத்தை அருளினான்.<br />\r\n<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளதாவது: காரிஜா பின் ஸைத் பின் தாபித் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் விசுவாசப் பிரமாணம் (பைஅத்) செய்த அன்சாரிப் பெண்ணான உம்முல் அலா (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"முஹாஜிர்களைத் தங்களோடு தங்க வைப்பதற்காக அன்சாரிகள் சீட்டுக் குலுக்கிப் போட்டபோது, எங்களுடைய பங்கிற்கு உஸ்மான் பின் மழ்ஊன் (ரழி) அவர்கள் வந்தார்கள். பின்னர், உஸ்மான் (ரழி) அவர்கள் எங்கள் வீட்டில் நோய்வாய்ப்பட்டார்கள். அவர் மரணிக்கும் வரை நாங்கள் அவரைப் பராமரித்தோம். (அவர் மரணித்த பின்) அவருடைய ஆடைகளிலேயே அவரை நாங்கள் கபனிட்டோம் (சுற்றினோம்). அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உள்ளே வந்தார்கள். நான், 'அபூ அஸ்-ஸாயிபே! உங்கள் மீது அல்லாஹ் கருணை காட்டுவானாக. நிச்சயமாக அல்லாஹ் உங்களைக் கண்ணியப்படுத்தினான் என்பதற்கு நான் சாட்சி கூறுகிறேன்' என்று சொன்னேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُدْرِيكِ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">أَكْرَمَه</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"அல்லாஹ் இவரைக் கண்ணியப்படுத்தினான் என்று உனக்கு எப்படித் தெரியும்?\") நான், \"அல்லாஹ்வின் தூதரே (ஸல்)! எனக்குத் தெரியாது, என் தந்தையும் தாயும் உங்களுக்கு அர்ப்பணமாகட்டும்!\" என்று கூறினேன். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுகினார்கள்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَاءَهُ</span> <span class=\"quran-arabic-font text-success\">الْيَقِينُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ،وَإِنِّي</span> <span class=\"quran-arabic-font text-success\">لَأَرْجُو</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْخَيْرَ</span>. <span class=\"quran-arabic-font text-success\">وَاللهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَدْرِي</span> <span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُفْعَلُ</span> <span class=\"quran-arabic-font text-success\">بِي</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"இவரைப் பொறுத்தவரை, இவரது இறைவனிடமிருந்து இவருக்கு உறுதியான செய்தி (மரணம்) வந்துவிட்டது. நான் இவருக்கு நன்மையையே நாடுகிறேன். அல்லாஹ்வின் மீது ஆணையாக, நான் அல்லாஹ்வின் தூதராக இருந்தபோதிலும், எனக்கு என்ன செய்யப்படும் என்று எனக்குத் தெரியாது.\") அதன் பிறகு, \"இனி ஒருபோதும் யாருக்காகவும் அவர் பரிசுத்தமானவர் என்று நான் கூறமாட்டேன்\" என்று நான் சொன்னேன். இந்தச் சம்பவம் எனக்கு மிகுந்த மனக்கவலையை ஏற்படுத்தியது. பின்னர் நான் தூங்கும்போது எனது கனவில், உஸ்மான் (ரழி) அவர்களுக்கென ஓடும் நீரூற்று ஒன்று இருப்பதைக் கண்டேன். நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் சென்று இது குறித்துக் கூறினேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">ذَاكِ</span> <span class=\"quran-arabic-font text-success\">عَمَلُه</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"அது அவருடைய (நற்)செயல்களாகும்.\") புகாரி இதனைப் பதிவு செய்துள்ளார், ஆனால் முஸ்லிம் இதனைப் பதிவு செய்யவில்லை. மற்றோர் அறிவிப்பில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَدْرِي</span> <span class=\"quran-arabic-font text-success\">وَأَنَا</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُفْعَلُ</span> <span class=\"quran-arabic-font text-success\">بِه</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"நான் அல்லாஹ்வின் தூதராக இருந்தபோதிலும், அவருக்கு என்ன செய்யப்படும் என்று எனக்குத் தெரியாது.\") இதுவும் இது போன்ற பிற செய்திகளும், அல்லாஹ்வோ அல்லது அவனது தூதரோ (ஸல்) யாரைப் பற்றித் தெளிவாகக் கூறினார்களோ அவர்களைத் தவிர, குறிப்பிட்ட ஒரு நபர் ஜன்னத்தில் (சுவனத்தில்) நுழைவார் என்று உறுதியாகக் கூறுவது அனுமதி இல்லை என்பதைக் காட்டுகின்றன. சுவனவாசிகள் என்று அறிவிக்கப்பட்டவர்களில் சிலர்: (முன்கூட்டியே சுவனத்தைக் கொண்டு நன்மாராயம் கூறப்பட்ட) பத்துத் தோழர்கள், இப்னு மஸ்வூத் (ரழி), உகாஷா (ரழி), இப்னு ஸல்லாம் (ரழி), அல்-குமைஸா (ரழி), பிலால் (ரழி), ஸுராக்கா (ரழி), அப்துல்லாஹ் பின் அம்ர் பின் ஹராம் (ரழி) (ஜாபிரின் தந்தை), மஊனா கிணற்றுக்கு அருகே படுகொலை செய்யப்பட்ட எழுபது குர்ஆன் ஓதுபவர்கள், ஸைத் பின் ஹாரிஸா (ரழி), ஜஃபர் (ரழி), இப்னு ரவாஹா (ரழி) மற்றும் இது போன்ற பிற தோழர்கள் (ரழி) ஆவர். அல்லாஹ் அவர்கள் அனைவரையும் பொருந்திக் கொள்வானாக.<br />\r\n<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">أَتَّبِعُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُوحَى</span> <span class=\"quran-arabic-font text-success\">إِلَىَّ﴿</span> (\"எனக்கு வஹீ (இறைச்செய்தி)யாக அறிவிக்கப்படுவதைத் தவிர வேறொன்றையும் நான் பின்பற்றவில்லை.\") இதன் பொருள்: \"அல்லாஹ் எனக்கு வஹீ (இறைச்செய்தி)யாக எதனை அருள்கிறானோ அதனை மட்டுமே நான் பின்பற்றுகிறேன்\" என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ﴿</span> (\"மேலும், நான் பகிரங்கமாக எச்சரிக்கை செய்பவனே தவிர வேறில்லை.\") அதாவது, \"எனது எச்சரிக்கைகள் சீரான அறிவும் பகுத்தறிவும் கொண்ட ஒவ்வொருவருக்கும் மிகத் தெளிவானவையாகும்\" என்று பொருள்படும். மேலும் அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"குர்ஆன் மற்றும் தூதரைப் பற்றி இணைவைப்பாளர்களின் கூற்றுக்களுக்கு மறுப்பு\n\r\n\n\r\nஇணைவைப்பாளர்களின் குஃப்ர் (நிராகரிப்பு) மற்றும் வரம்பு மீறல் குறித்து அல்லாஹ் கூறுகிறான்: அல்லாஹ்வின் தெளிவான வசனங்கள் அவர்களுக்கு ஓதிக் காட்டப்படும்போது, அவர்கள்; ﴾هَـذَا سِحْرٌ مُّبِينٌ﴿ (இது தெளிவான சூனியம்!) என்று கூறுகின்றனர். அதாவது, இது வெறும் சூனியம் என்பது அவர்களின் கருத்து. தங்களுடைய இக்கூற்றின் மூலம் அவர்கள் பொய் உரைத்து, ஒரு அவதூறை இட்டுக்கட்டி, வழிதவறி, நிராகரித்துவிட்டனர்.\n\r\n\n\r\n\n\r\n﴾أَمْ يَقُولُونَ افْتَرَاهُ﴿ (அல்லது, \"அவர் இதனை இட்டுக்கட்டிவிட்டார்\" என்று அவர்கள் கூறுகிறார்களா?) அவர்கள் முஹம்மது (ஸல்) அவர்களையே குறிப்பிடுகிறார்கள். இதற்குப் பதிலாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\n﴾قُلْ إِنِ افْتَرَيْتُهُ فَلاَ تَمْلِكُونَ لِى مِنَ اللَّهِ شَيْئاً﴿ (கூறுவீராக: \"நான் இதனை இட்டுக்கட்டியிருந்தால், அல்லாஹ்விடமிருந்து (ஏற்படும் தண்டனையிலிருந்து) என்னைக் காப்பாற்ற உங்களுக்கு எவ்வித அதிகாரமும் இல்லை...\") இதன் பொருள்: \"நான் அல்லாஹ்வின் மீது பொய் சொல்லி, அவன் என்னை அனுப்பாத போதே அவன் என்னை அனுப்பியதாகப் பொய்யாக வாதிட்டால், அவன் என்னைக் கடுமையான முறையில் தண்டிப்பான். அப்போது பூமியில் உள்ள உங்களாலோ அல்லது வேறு எவராலோ அவனிடமிருந்து என்னைக் காப்பாற்ற முடியாது\" என்பதாகும். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n\n\r\n﴾قُلْ إِنِّى لَن يُجِيرَنِى مِنَ اللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِ مُلْتَحَداً إِلاَّ بَلاَغاً مِّنَ اللَّهِ وَرِسَالَاتِهِ﴿ (கூறுவீராக: \"நிச்சயமாக அல்லாஹ்விடமிருந்து என்னை எவரும் பாதுகாக்க முடியாது. அவனையன்றி வேறொரு புகலிடத்தையும் நான் காணமாட்டேன். (எனது கடமை) அல்லாஹ்விடமிருந்து (வரும் செய்தியை) எடுத்துரைப்பதும், அவனது தூதுச் செய்திகளை (மக்களுக்குச் சேர்ப்பிப்பதும்) மட்டுமே.\") (72:22-23)\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ الْأَقَاوِيلِ - لأَخَذْنَا مِنْهُ بِالْيَمِينِ - ثُمَّ لَقَطَعْنَا مِنْهُ الْوَتِينَ - فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَاجِزِينَ ﴿ (மேலும், அவர் நம் மீது சில பொய்களை இட்டுக்கட்டியிருந்தால், நிச்சயமாக நாம் அவருடைய வலக்கையைப் பற்றிப் பிடித்திருப்போம். பின்னர், அவருடைய உயிர்நாடியைத் துண்டித்திருப்போம். அப்போது உங்களில் எவரும் அவரை (தண்டிப்பதிலிருந்து) நம்மைத் தடுத்து நிறுத்த முடியாது.) (69:44-47)\n\r\n\n\r\n\n\r\nஎனவேதான் அல்லாஹ் இங்கு கூறுகிறான்: ﴾قُلْ إِنِ افْتَرَيْتُهُ فَلاَ تَمْلِكُونَ لِى مِنَ اللَّهِ شَيْئاً هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ كَفَى بِهِ شَهِيداً بَيْنِى وَبَيْنَكُمْ﴿ (கூறுவீராக: \"நான் இதனை இட்டுக்கட்டியிருந்தாலும், அல்லாஹ்விடமிருந்து (வரும் தண்டனையிலிருந்து) என்னைக் காக்க உங்களுக்கு எந்த சக்தியும் இல்லை. நீங்கள் இதனைப் பற்றி (அதாவது இந்தக் குர்ஆனைப் பற்றி) உங்களுக்குள் என்ன பேசிக் கொள்கிறீர்கள் என்பதை அவன் நன்கு அறிவான்! எனக்கும் உங்களுக்கும் இடையில் சாட்சியாக அவனே போதுமானவன்!...\") இது அவர்களுக்கு விடுக்கப்பட்ட கடுமையான அச்சுறுத்தலும் எச்சரிக்கையுமாகும்.\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَهُوَ الْغَفُورُ الرَّحِيمُ﴿ (மேலும், அவன் மிகவும் மன்னிப்பவன், நிகரற்ற அன்புடையவன்.) இது அவர்கள் தௌபா (பாவமன்னிப்பு) செய்து அல்லாஹ்வின் பக்கம் திரும்புவதற்கான ஒரு ஊக்குவிப்பாகும். அதாவது, \"இவை அனைத்தையும் மீறி, நீங்கள் திருந்தி பாவமன்னிப்புக் கோரினால், அல்லாஹ் உங்கள் பாவமன்னிப்பை ஏற்றுக்கொண்டு, உங்களை மன்னித்து உங்கள் மீது கருணை காட்டுவான்\" என்று பொருள்படும். இது சூரத்துல் ஃபுர்கானில் அல்லாஹ் கூறுவதைப் போன்றது:\n\r\n\n\r\n\n\r\n﴾وَقَالُواْ أَسَاطِيرُ الْأَوَّلِينَ اكْتَتَبَهَا فَهِىَ تُمْلَى عَلَيْهِ بُكْرَةً وَأَصِيلاً - قُلْ أَنزَلَهُ الَّذِى يَعْلَمُ السِّرَّ فِى السَّمَـوَتِ وَالْأَرْضِ إِنَّهُ كَانَ غَفُوراً رَّحِيماً ﴿ (மேலும் அவர்கள் கூறுகின்றனர்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவர் இவற்றை எழுதிக் கொண்டார். இவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக் காட்டப்படுகின்றன.\" (நபியே!) நீர் கூறுவீராக: \"வானங்களிலும் பூமியிலும் உள்ள இரகசியங்களை அறிபவனே இதனை இறக்கி வைத்தான். நிச்சயமாக அவன் மிகவும் மன்னிப்பவனாகவும், நிகரற்ற அன்புடையவனாகவும் இருக்கிறான்.\") (25:5-6)\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾قُلْ مَا كُنتُ بِدْعاً مِّنَ الرُّسُلِ﴿ (கூறுவீராக: \"தூதர்களில் நான் ஒரு புதியவன் அல்ல...\") இதன் பொருள்: \"உலகிற்கு வந்த முதல் தூதன் நான் அல்ல. மாறாக, எனக்கு முன்னரும் பல தூதர்கள் வந்துள்ளனர். எனவே, என்னை நீங்கள் நிராகரிப்பதற்கும், எனது தூதுத்துவத்தில் சந்தேகம் கொள்வதற்கும் நான் ஒன்றும் இதுவரை நடக்காத ஒரு புதிய நிகழ்வு அல்ல. நிச்சயமாக, அல்லாஹ் எனக்கு முன்னர் பல்வேறு சமுதாயங்களுக்கு அனைத்து நபிமார்களையும் அனுப்பியுள்ளான்.\"\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلاَ بِكُمْ﴿ (மேலும், என்னைப் பற்றியோ அல்லது உங்களைப் பற்றியோ என்ன செய்யப்படும் என்பதை நான் அறியமாட்டேன்.) அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"இந்த வசனத்தைத் தொடர்ந்து வஹீ (இறைச்செய்தி)யாக பின்வரும் வசனம் இறங்கியது:\n\r\n\n\r\n\n\r\n﴾لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ﴿ (உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக). அதேபோல், இக்ரிமா, அல்-ஹஸன் மற்றும் கத்தாதா (ரஹ்) ஆகியோர் இந்த ஆயத் (வசனம்), பின்வரும் வசனத்தினால் மாற்றப்பட்டது (நஸக் செய்யப்பட்டது) என்று கூறுகின்றனர்:\n\r\n\n\r\n\n\r\n﴾لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ﴿ (உமது முந்தைய மற்றும் பிந்தைய பாவங்களை அல்லாஹ் மன்னிப்பதற்காக). இந்த வசனம் அருளப்பட்டபோது, முஸ்லிம்களில் ஒருவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம், \"அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்பதைத் தெளிவுபடுத்திவிட்டான். ஆனால் எங்களுக்கு என்ன செய்வான்?\" என்று கேட்டார். அப்போது அல்லாஹ் இதனை அருளினான்:\n\r\n\n\r\n\n\r\n﴾لِّيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَـتِ جَنَّـتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَارُ﴿ (நம்பிக்கை கொண்ட ஆண்களையும் பெண்களையும், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும் சுவனச் சோலைகளில் அவன் புகுத்துவதற்காக). இதுவே அவர்கள் கூறிய கருத்தாகும். எனினும், ஸஹீஹான (ஆதாரப்பூர்வமான) செய்திகளில் உறுதிப்படுத்தப்பட்டது என்னவென்றால், நம்பிக்கையாளர்கள், \"அல்லாஹ்வின் தூதரே (ஸல்)! இது உங்களுக்கு மகிழ்ச்சியளிக்கட்டும். ஆனால் எங்களது நிலை என்ன?\" என்று கேட்டனர். அதன்பின்னரே அல்லாஹ் இந்த வசனத்தை அருளினான்.\n\r\n\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளதாவது: காரிஜா பின் ஸைத் பின் தாபித் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் விசுவாசப் பிரமாணம் (பைஅத்) செய்த அன்சாரிப் பெண்ணான உம்முல் அலா (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"முஹாஜிர்களைத் தங்களோடு தங்க வைப்பதற்காக அன்சாரிகள் சீட்டுக் குலுக்கிப் போட்டபோது, எங்களுடைய பங்கிற்கு உஸ்மான் பின் மழ்ஊன் (ரழி) அவர்கள் வந்தார்கள். பின்னர், உஸ்மான் (ரழி) அவர்கள் எங்கள் வீட்டில் நோய்வாய்ப்பட்டார்கள். அவர் மரணிக்கும் வரை நாங்கள் அவரைப் பராமரித்தோம். (அவர் மரணித்த பின்) அவருடைய ஆடைகளிலேயே அவரை நாங்கள் கபனிட்டோம் (சுற்றினோம்). அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உள்ளே வந்தார்கள். நான், 'அபூ அஸ்-ஸாயிபே! உங்கள் மீது அல்லாஹ் கருணை காட்டுவானாக. நிச்சயமாக அல்லாஹ் உங்களைக் கண்ணியப்படுத்தினான் என்பதற்கு நான் சாட்சி கூறுகிறேன்' என்று சொன்னேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n\n\r\n﴾«وَمَا يُدْرِيكِ أَنَّ اللهَ تَعَالَى أَكْرَمَه»﴿ (\"அல்லாஹ் இவரைக் கண்ணியப்படுத்தினான் என்று உனக்கு எப்படித் தெரியும்?\") நான், \"அல்லாஹ்வின் தூதரே (ஸல்)! எனக்குத் தெரியாது, என் தந்தையும் தாயும் உங்களுக்கு அர்ப்பணமாகட்டும்!\" என்று கூறினேன். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுகினார்கள்:\n\r\n\n\r\n\n\r\n﴾«أَمَّا هُوَ فَقَدْ جَاءَهُ الْيَقِينُ مِنْ رَبِّهِ،وَإِنِّي لَأَرْجُو لَهُ الْخَيْرَ. وَاللهِ مَا أَدْرِي وَأَنَا رَسُولُ اللهِ مَا يُفْعَلُ بِي»﴿ (\"இவரைப் பொறுத்தவரை, இவரது இறைவனிடமிருந்து இவருக்கு உறுதியான செய்தி (மரணம்) வந்துவிட்டது. நான் இவருக்கு நன்மையையே நாடுகிறேன். அல்லாஹ்வின் மீது ஆணையாக, நான் அல்லாஹ்வின் தூதராக இருந்தபோதிலும், எனக்கு என்ன செய்யப்படும் என்று எனக்குத் தெரியாது.\") அதன் பிறகு, \"இனி ஒருபோதும் யாருக்காகவும் அவர் பரிசுத்தமானவர் என்று நான் கூறமாட்டேன்\" என்று நான் சொன்னேன். இந்தச் சம்பவம் எனக்கு மிகுந்த மனக்கவலையை ஏற்படுத்தியது. பின்னர் நான் தூங்கும்போது எனது கனவில், உஸ்மான் (ரழி) அவர்களுக்கென ஓடும் நீரூற்று ஒன்று இருப்பதைக் கண்டேன். நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் சென்று இது குறித்துக் கூறினேன். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n﴾«ذَاكِ عَمَلُه»﴿ (\"அது அவருடைய (நற்)செயல்களாகும்.\") புகாரி இதனைப் பதிவு செய்துள்ளார், ஆனால் முஸ்லிம் இதனைப் பதிவு செய்யவில்லை. மற்றோர் அறிவிப்பில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n﴾«مَا أَدْرِي وَأَنَا رَسُولُ اللهِ مَا يُفْعَلُ بِه»﴿ (\"நான் அல்லாஹ்வின் தூதராக இருந்தபோதிலும், அவருக்கு என்ன செய்யப்படும் என்று எனக்குத் தெரியாது.\") இதுவும் இது போன்ற பிற செய்திகளும், அல்லாஹ்வோ அல்லது அவனது தூதரோ (ஸல்) யாரைப் பற்றித் தெளிவாகக் கூறினார்களோ அவர்களைத் தவிர, குறிப்பிட்ட ஒரு நபர் ஜன்னத்தில் (சுவனத்தில்) நுழைவார் என்று உறுதியாகக் கூறுவது அனுமதி இல்லை என்பதைக் காட்டுகின்றன. சுவனவாசிகள் என்று அறிவிக்கப்பட்டவர்களில் சிலர்: (முன்கூட்டியே சுவனத்தைக் கொண்டு நன்மாராயம் கூறப்பட்ட) பத்துத் தோழர்கள், இப்னு மஸ்வூத் (ரழி), உகாஷா (ரழி), இப்னு ஸல்லாம் (ரழி), அல்-குமைஸா (ரழி), பிலால் (ரழி), ஸுராக்கா (ரழி), அப்துல்லாஹ் பின் அம்ர் பின் ஹராம் (ரழி) (ஜாபிரின் தந்தை), மஊனா கிணற்றுக்கு அருகே படுகொலை செய்யப்பட்ட எழுபது குர்ஆன் ஓதுபவர்கள், ஸைத் பின் ஹாரிஸா (ரழி), ஜஃபர் (ரழி), இப்னு ரவாஹா (ரழி) மற்றும் இது போன்ற பிற தோழர்கள் (ரழி) ஆவர். அல்லாஹ் அவர்கள் அனைவரையும் பொருந்திக் கொள்வானாக.\n\r\n\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِنْ أَتَّبِعُ إِلاَّ مَا يُوحَى إِلَىَّ﴿ (\"எனக்கு வஹீ (இறைச்செய்தி)யாக அறிவிக்கப்படுவதைத் தவிர வேறொன்றையும் நான் பின்பற்றவில்லை.\") இதன் பொருள்: \"அல்லாஹ் எனக்கு வஹீ (இறைச்செய்தி)யாக எதனை அருள்கிறானோ அதனை மட்டுமே நான் பின்பற்றுகிறேன்\" என்பதாகும்.\n\r\n\n\r\n\n\r\n﴾وَمَآ أَنَاْ إِلاَّ نَذِيرٌ مُّبِينٌ﴿ (\"மேலும், நான் பகிரங்கமாக எச்சரிக்கை செய்பவனே தவிர வேறில்லை.\") அதாவது, \"எனது எச்சரிக்கைகள் சீரான அறிவும் பகுத்தறிவும் கொண்ட ஒவ்வொருவருக்கும் மிகத் தெளிவானவையாகும்\" என்று பொருள்படும். மேலும் அல்லாஹ்வே மிக அறிந்தவன்."},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=14\" class=\"link\">46:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=14\" class=\"link\">46:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=14\" class=\"link\">46:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=14\" class=\"link\">46:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>குர்ஆன் அல்லாஹ்வின் உண்மையான உரை; அதைப் பற்றிய நிராகரிப்பாளர்கள் மற்றும் முஸ்லிம்களின் நிலைப்பாடு</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾قُلْ﴿</span><br />\r\n<br />\r\n(கூறுவீராக) அதாவது, 'முஹம்மதே (ஸல்)! குர்ஆனை நிராகரிக்கும் இந்த இணைவைப்பாளர்களிடம் கூறுவீராக.' <span class=\"quran-arabic-font text-success\">﴾أَرَءَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ﴿</span><br />\r\n<br />\r\n(எனக்குக் கூறுங்கள்! ஒருவேளை இது...) அதாவது, இந்த குர்ஆன். <span class=\"quran-arabic-font text-success\">﴾مِنْ</span> <span class=\"quran-arabic-font text-success\">عِندِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَكَفَرْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(அல்லாஹ்விடமிருந்து அருளப்பட்டு, நீங்கள் அதை நிராகரித்திருந்தால்) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த இந்த வேதம், உங்களுக்கு நான் எத்திவைப்பதற்காக உண்மையில் அவனிடமிருந்து எனக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்டிருந்து, நீங்கள் அதை நிராகரித்துப் பொய்ப்பித்தால், அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்று நீங்கள் கருதுகிறீர்கள்?' <span class=\"quran-arabic-font text-success\">﴾وَشَهِدَ</span> <span class=\"quran-arabic-font text-success\">شَاهِدٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مِثْلِهِ﴿</span><br />\r\n<br />\r\n((அதேநேரம்) பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த ஒரு சாட்சி இது போன்றதொரு வேதம் குறித்து சாட்சியம் அளித்துள்ளார்) அதாவது, 'எனக்கு முன் இருந்த நபிமார்களுக்கு அருளப்பட்ட முந்தைய வேதங்கள் அனைத்தும் இதன் உண்மைத்தன்மைக்கும் நம்பகத்தன்மைக்கும் சாட்சியமளிக்கின்றன. இந்த குர்ஆன் கூறும் விஷயங்களைப் போன்ற செய்திகள் குறித்து அவை முன்னரே முன்னறிவிப்புச் செய்துள்ளன.' அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை, <span class=\"quran-arabic-font text-success\">﴾فَآمَنَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர் விசுவாசம் கொண்டார்) 'அது உண்மை என்பதை உணர்ந்த காரணத்தால், பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த அந்தச் சாட்சியாளர் (குர்ஆனை) நம்பினார்.' <span class=\"quran-arabic-font text-success\">﴾وَاسْتَكْبَرْتُمْ﴿</span><br />\r\n<br />\r\n(நீங்களோ பெருமையடித்தீர்கள்!) 'ஆனால் நீங்களோ கர்வத்துடன் அதைப் பின்பற்ற மறுத்துவிட்டீர்கள்.' மஸ்ரூக் அவர்கள் கூறினார்கள்: \"அந்தச் சாட்சி தனது நபியையும் வேதத்தையும் நம்பினார், நீங்களோ உங்கள் நபியையும் வேதத்தையும் நிராகரித்தீர்கள்.\" <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் அநீதி இழைக்கும் மக்களுக்கு வழிகாட்டமாட்டான்.) இங்குள்ள சாட்சி என்பது பொதுவாக எந்தவொரு சாட்சியையும் குறிக்கும். இதில் அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களும் மற்றும் அவர்களைப் போன்றோரும் அடங்குவர். ஏனெனில், அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்பதற்கு முன்பே இந்த வசனம் மக்காவில் அருளப்பட்டது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">يُتْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّنَآ</span> <span class=\"quran-arabic-font text-success\">إنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அது அவர்களுக்கு ஓதிக் காட்டப்பட்டால், அவர்கள் கூறுகிறார்கள்: \"நாங்கள் அதை நம்புகிறோம். நிச்சயமாக, இது எங்கள் இறைவனிடமிருந்து வந்த உண்மையாகும். உண்மையில், இதற்கு முன்பே நாங்கள் முஸ்லிம்களாக இருந்தோம்.\") (<a href=\"qurandisp.php?sura=28&ayah=53\" class=\"link\">28:53</a>) இது அல்லாஹ்வின் பின்வரும் கூற்றையும் ஒத்துள்ளது: <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">ءَامِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُواْ</span> <span class=\"quran-arabic-font text-success\">الْعِلْمَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يُتْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">يَخِرُّونَ</span> <span class=\"quran-arabic-font text-success\">لِلاٌّذْقَانِ</span> <span class=\"quran-arabic-font text-success\">سُجَّدًا</span> - <span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">وَعْدُ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">لَمَفْعُولاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக! இதற்கு முன்னர் கல்வி வழங்கப்பட்டவர்கள் - அது அவர்களுக்கு ஓதிக் காட்டப்படும்போது, அவர்கள் தங்கள் முகங்குப்புற விழுந்து ஸஜ்தா செய்கிறார்கள், மேலும் அவர்கள் கூறுகிறார்கள்: \"எங்கள் இறைவன் தூய்மையானவன்! உண்மையாகவே, எங்கள் இறைவனின் வாக்குறுதி நிறைவேற்றப்பட்டுள்ளது.\") (<a href=\"qurandisp.php?sura=17&ayah=107\" class=\"link\">17:107</a>-108)<br />\r\n<br />\r\nஸஃத் பின் அபீ வக்காஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது, அவர்கள் கூறினார்கள்: \"பூமியின் மீது நடந்து கொண்டிருப்பவர்களில் எவரையும் 'சொர்க்கவாசி' என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டதில்லை - அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களைத் தவிர. அவர்களைக் குறித்துத்தான் பின்வரும் வசனம் அருளப்பட்டது: <span class=\"quran-arabic-font text-success\">﴾وَشَهِدَ</span> <span class=\"quran-arabic-font text-success\">شَاهِدٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مِثْلِهِ﴿</span> ((அதேநேரம்) பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த ஒரு சாட்சி இது போன்றதொரு வேதம் குறித்து சாட்சியம் அளித்துள்ளார்).\" இது புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் மற்றும் அன்-நஸாயீயிலும் பதிவு செய்யப்பட்டுள்ளது. இதேபோல், இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக், கதாதா, இக்ரிமா, யூசுஃப் பின் அப்துல்லாஹ் பின் ஸலாம் (ரழி), ஹிலால் பின் யஸாஃப், அஸ்-ஸுத்தி, அத்-தவ்ரி, மாலிக் பின் அனஸ் மற்றும் இப்னு ஸைத் ஆகிய அனைவரும் இது அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களைக் குறிக்கிறது என்று கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ﴿</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் விசுவாசம் கொண்டவர்களைக் குறித்துக் கூறுகிறார்கள்: \"இது நல்லதாக இருந்திருந்தால், அவர்கள் (பலவீனமானவர்களும் ஏழைகளும்) எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!\") அதாவது நிராகரிப்பாளர்கள் குர்ஆனை நம்புபவர்களைப் பற்றி கூறுகிறார்கள்: \"குர்ஆன் ஏதேனும் நன்மையாக இருந்திருந்தால், இந்த (பலவீனமான) மக்கள் எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!\" இதன் மூலம் அவர்கள் பிலால் (ரழி), அம்மார் (ரழி), ஸுஹைப் (ரழி), கப்பாப் (ரழி) மற்றும் அவர்களைப் போன்ற பலவீனமானவர்களையும், ஆண் மற்றும் பெண் அடிமைகளையும் குறிப்பிட்டார்கள். இணைவைப்பாளர்கள் இவ்வாறு கூறியதற்குக் காரணம், அல்லாஹ்விடம் தங்களுக்கு உயரிய அந்தஸ்து இருப்பதாகவும், அவன் தங்களைச் சிறப்பாகக் கவனிப்பதாகவும் அவர்கள் கருதியதேயாகும். இதன் மூலம் அவர்கள் ஒரு பெரிய தெளிவான தவறைச் செய்தார்கள்; அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾وَكَذلِكَ</span> <span class=\"quran-arabic-font text-success\">فَتَنَّا</span> <span class=\"quran-arabic-font text-success\">بَعْضَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">لِّيَقُولواْ</span> <span class=\"quran-arabic-font text-success\">أَهَـؤُلاءِ</span> <span class=\"quran-arabic-font text-success\">مَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَيْنِنَآ﴿</span><br />\r\n<br />\r\n(இவ்வாறு நாம் அவர்களில் சிலரை மற்றவர்களால் சோதித்தோம்; \"நம்மில் இவர்களுக்குத்தானா அல்லாஹ் அருள்புரிந்தான்?\" என்று அவர்கள் கேட்பதற்காக.) (<a href=\"qurandisp.php?sura=6&ayah=53\" class=\"link\">6:53</a>) அதாவது, தங்களை விட்டுவிட்டு அந்தப் பலவீனமானவர்கள் எவ்வாறு நேர்வழி பெற்றிருக்க முடியும் என்று அவர்கள் வியக்கின்றனர். எனவே, அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لَوْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">سَبَقُونَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ﴿</span><br />\r\n<br />\r\n(இது நல்லதாக இருந்திருந்தால், அவர்கள் எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!) இதற்கு நேர்மாறானது அஹ்லுஸ் ஸுன்னா வல் ஜமாஆவின் நிலைப்பாடாகும்: ஸஹாபாக்களிடமிருந்து அறிவிக்கப்படாத எந்தவொரு செயல் அல்லது கூற்றைப் பற்றியும் அவர்கள் கூறுகிறார்கள்: \"அது ஒரு பித்அத் (புத்தாக்கம்). அதில் ஏதேனும் நன்மை இருந்திருந்தால், அதைச் செய்வதில் அவர்கள் நம்மை முந்தியிருப்பார்கள். ஏனெனில் ஸஹாபாக்கள் எந்தவொரு நற்பண்பையும் செய்யத் தவறவில்லை, மாறாக அவற்றைச் செய்வதில் அவர்கள் விரைந்து செயல்பட்டார்கள்.\" அல்லாஹ் தொடர்கிறான், <span class=\"quran-arabic-font text-success\">﴾وَإِذْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَهْتَدُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் இதன் மூலம் நேர்வழி பெறாதபோது,) அதாவது, குர்ஆன். <span class=\"quran-arabic-font text-success\">﴾فَسَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">هَـذَآ</span> <span class=\"quran-arabic-font text-success\">إِفْكٌ</span> <span class=\"quran-arabic-font text-success\">قَدِيمٌ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறுகிறார்கள்: \"இது ஒரு பழங்காலப் பொய்!\") அதாவது, இது ஒரு பழைய பொய் என்கின்றனர். இதன் மூலம் குர்ஆனையும் அதைப் பின்பற்றுபவர்களையும் இழிவுபடுத்துவதற்காக, குர்ஆன் முன்னோர்களின் கதைகளிலிருந்து எடுக்கப்பட்டது என்று அவர்கள் வாதிடுகின்றனர். இது தெளிவான ஆணவமாகும்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியது போல்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">بَطَرُ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَغَمْطُ</span> <span class=\"quran-arabic-font text-success\">النَّاس</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n((ஆணவம் என்பது) உண்மையை நிராகரிப்பதும், மக்களை இழிவுபடுத்துவதும் ஆகும்.) பின்னர் அல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِ</span> <span class=\"quran-arabic-font text-success\">كِتَابُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n<br />\r\n(இதற்கு முன்னால் மூஸாவின் (அலை) வேதம் இருந்தது) அது தவ்ராத் ஆகும். <span class=\"quran-arabic-font text-success\">﴾إِمَاماً</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَةً</span> <span class=\"quran-arabic-font text-success\">وَهَـذَا</span> <span class=\"quran-arabic-font text-success\">كِتَـبٌ﴿</span><br />\r\n<br />\r\n(ஒரு வழிகாட்டியாகவும், கருணையாகவும். இந்த வேதம்...) அதாவது, குர்ஆன். <span class=\"quran-arabic-font text-success\">﴾مُّصَدِّقٌ﴿</span><br />\r\n<br />\r\n(உண்மைப்படுத்துவதாகும்) அதாவது, தனக்கு முன் வந்த முந்தைய வேதங்களை. <span class=\"quran-arabic-font text-success\">﴾لِّسَاناً</span> <span class=\"quran-arabic-font text-success\">عَرَبِيّاً﴿</span><br />\r\n<br />\r\n(அரபு மொழியில்,) அதாவது, அது மிகுந்த சொல்வளம் மிக்கதும் தெளிவானதும் ஆகும். <span class=\"quran-arabic-font text-success\">﴾لِّيُنذِرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">وَبُشْرَى</span> <span class=\"quran-arabic-font text-success\">لِلْمُحْسِنِينَ﴿</span><br />\r\n<br />\r\n(அநீதி இழைப்போரை எச்சரிக்கவும், நன்மை செய்வோருக்கு நற்செய்தியாகவும் (இது இருக்கிறது).) அதாவது, இது நிராகரிப்பாளர்களுக்கு எச்சரிக்கையையும், விசுவாசிகளுக்கு நற்செய்தியையும் கொண்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, \"எங்கள் இறைவன் அல்லாஹ் (மட்டுமே)\" என்று கூறி, பிறகு அதில் உறுதியாகவும் இருப்பவர்கள்,) இதற்கான விளக்கம் முன்னரே சூரா ஹா-மீம் அஸ்-ஸஜ்தாவில் (<a href=\"qurandisp.php?sura=41&ayah=30\" class=\"link\">41:30</a>) விவாதிக்கப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">خَوْفٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கு எந்தப் பயமும் இல்லை,) அதாவது, அவர்களின் எதிர்காலம் குறித்து. <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَحْزَنُونَ﴿</span><br />\r\n<br />\r\n(அவர்கள் கவலைப்படவும் மாட்டார்கள்.) அதாவது, அவர்கள் உலகில் விட்டுச் சென்றவை குறித்து. அல்லாஹ் தொடர்கிறான், <span class=\"quran-arabic-font text-success\">﴾أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">جَزَآءً</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இவர்களே சுவனவாசிகள், அதில் அவர்கள் (என்றென்றும்) நிலைத்திருப்பார்கள் -- அவர்கள் செய்து கொண்டிருந்தவற்றிற்குப் பிரதிபலனாக.) அதாவது, நற்செயல்கள் அவர்கள் அல்லாஹ்வின் கருணையைப் பெறுவதற்கும், அது அவர்களைச் சூழ்ந்து கொள்வதற்கும் ஒரு காரணமாகும் -- அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"குர்ஆன் அல்லாஹ்வின் உண்மையான உரை; அதைப் பற்றிய நிராகரிப்பாளர்கள் மற்றும் முஸ்லிம்களின் நிலைப்பாடு\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான், ﴾قُلْ﴿\n\r\n\n\r\n(கூறுவீராக) அதாவது, 'முஹம்மதே (ஸல்)! குர்ஆனை நிராகரிக்கும் இந்த இணைவைப்பாளர்களிடம் கூறுவீராக.' ﴾أَرَءَيْتُمْ إِن كَانَ﴿\n\r\n\n\r\n(எனக்குக் கூறுங்கள்! ஒருவேளை இது...) அதாவது, இந்த குர்ஆன். ﴾مِنْ عِندِ اللَّهِ وَكَفَرْتُمْ بِهِ﴿\n\r\n\n\r\n(அல்லாஹ்விடமிருந்து அருளப்பட்டு, நீங்கள் அதை நிராகரித்திருந்தால்) அதாவது, 'நான் உங்களிடம் கொண்டு வந்த இந்த வேதம், உங்களுக்கு நான் எத்திவைப்பதற்காக உண்மையில் அவனிடமிருந்து எனக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்டிருந்து, நீங்கள் அதை நிராகரித்துப் பொய்ப்பித்தால், அல்லாஹ் உங்களுக்கு என்ன செய்வான் என்று நீங்கள் கருதுகிறீர்கள்?' ﴾وَشَهِدَ شَاهِدٌ مِّن بَنِى إِسْرَءِيلَ عَلَى مِثْلِهِ﴿\n\r\n\n\r\n((அதேநேரம்) பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த ஒரு சாட்சி இது போன்றதொரு வேதம் குறித்து சாட்சியம் அளித்துள்ளார்) அதாவது, 'எனக்கு முன் இருந்த நபிமார்களுக்கு அருளப்பட்ட முந்தைய வேதங்கள் அனைத்தும் இதன் உண்மைத்தன்மைக்கும் நம்பகத்தன்மைக்கும் சாட்சியமளிக்கின்றன. இந்த குர்ஆன் கூறும் விஷயங்களைப் போன்ற செய்திகள் குறித்து அவை முன்னரே முன்னறிவிப்புச் செய்துள்ளன.' அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை, ﴾فَآمَنَ﴿\n\r\n\n\r\n(மேலும் அவர் விசுவாசம் கொண்டார்) 'அது உண்மை என்பதை உணர்ந்த காரணத்தால், பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த அந்தச் சாட்சியாளர் (குர்ஆனை) நம்பினார்.' ﴾وَاسْتَكْبَرْتُمْ﴿\n\r\n\n\r\n(நீங்களோ பெருமையடித்தீர்கள்!) 'ஆனால் நீங்களோ கர்வத்துடன் அதைப் பின்பற்ற மறுத்துவிட்டீர்கள்.' மஸ்ரூக் அவர்கள் கூறினார்கள்: \"அந்தச் சாட்சி தனது நபியையும் வேதத்தையும் நம்பினார், நீங்களோ உங்கள் நபியையும் வேதத்தையும் நிராகரித்தீர்கள்.\" ﴾إِنَّ اللَّهَ لاَ يَهْدِى الْقَوْمَ الظَّـلِمِينَ﴿\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் அநீதி இழைக்கும் மக்களுக்கு வழிகாட்டமாட்டான்.) இங்குள்ள சாட்சி என்பது பொதுவாக எந்தவொரு சாட்சியையும் குறிக்கும். இதில் அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களும் மற்றும் அவர்களைப் போன்றோரும் அடங்குவர். ஏனெனில், அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்பதற்கு முன்பே இந்த வசனம் மக்காவில் அருளப்பட்டது. இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்: ﴾وَإِذَا يُتْلَى عَلَيْهِمْ قَالُواْ ءَامَنَّا بِهِ إِنَّهُ الْحَقُّ مِن رَّبِّنَآ إنَّا كُنَّا مِن قَبْلِهِ مُسْلِمِينَ ﴿\n\r\n\n\r\n(மேலும் அது அவர்களுக்கு ஓதிக் காட்டப்பட்டால், அவர்கள் கூறுகிறார்கள்: \"நாங்கள் அதை நம்புகிறோம். நிச்சயமாக, இது எங்கள் இறைவனிடமிருந்து வந்த உண்மையாகும். உண்மையில், இதற்கு முன்பே நாங்கள் முஸ்லிம்களாக இருந்தோம்.\") (28:53) இது அல்லாஹ்வின் பின்வரும் கூற்றையும் ஒத்துள்ளது: ﴾قُلْ ءَامِنُواْ بِهِ أَوْ لاَ تُؤْمِنُواْ إِنَّ الَّذِينَ أُوتُواْ الْعِلْمَ مِن قَبْلِهِ إِذَا يُتْلَى عَلَيْهِمْ يَخِرُّونَ لِلاٌّذْقَانِ سُجَّدًا - وَيَقُولُونَ سُبْحَانَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولاً ﴿\n\r\n\n\r\n(நிச்சயமாக! இதற்கு முன்னர் கல்வி வழங்கப்பட்டவர்கள் - அது அவர்களுக்கு ஓதிக் காட்டப்படும்போது, அவர்கள் தங்கள் முகங்குப்புற விழுந்து ஸஜ்தா செய்கிறார்கள், மேலும் அவர்கள் கூறுகிறார்கள்: \"எங்கள் இறைவன் தூய்மையானவன்! உண்மையாகவே, எங்கள் இறைவனின் வாக்குறுதி நிறைவேற்றப்பட்டுள்ளது.\") (17:107-108)\n\r\n\n\r\nஸஃத் பின் அபீ வக்காஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது, அவர்கள் கூறினார்கள்: \"பூமியின் மீது நடந்து கொண்டிருப்பவர்களில் எவரையும் 'சொர்க்கவாசி' என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டதில்லை - அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களைத் தவிர. அவர்களைக் குறித்துத்தான் பின்வரும் வசனம் அருளப்பட்டது: ﴾وَشَهِدَ شَاهِدٌ مِّن بَنِى إِسْرَءِيلَ عَلَى مِثْلِهِ﴿ ((அதேநேரம்) பனூ இஸ்ராயீல் வம்சத்தைச் சேர்ந்த ஒரு சாட்சி இது போன்றதொரு வேதம் குறித்து சாட்சியம் அளித்துள்ளார்).\" இது புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் மற்றும் அன்-நஸாயீயிலும் பதிவு செய்யப்பட்டுள்ளது. இதேபோல், இப்னு அப்பாஸ் (ரழி), முஜாஹித், அத்-தஹ்ஹாக், கதாதா, இக்ரிமா, யூசுஃப் பின் அப்துல்லாஹ் பின் ஸலாம் (ரழி), ஹிலால் பின் யஸாஃப், அஸ்-ஸுத்தி, அத்-தவ்ரி, மாலிக் பின் அனஸ் மற்றும் இப்னு ஸைத் ஆகிய அனைவரும் இது அப்துல்லாஹ் பின் ஸலாம் (ரழி) அவர்களைக் குறிக்கிறது என்று கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَقَالَ الَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوْ كَانَ خَيْراً مَّا سَبَقُونَآ إِلَيْهِ﴿\n\r\n\n\r\n(நிராகரிப்பாளர்கள் விசுவாசம் கொண்டவர்களைக் குறித்துக் கூறுகிறார்கள்: \"இது நல்லதாக இருந்திருந்தால், அவர்கள் (பலவீனமானவர்களும் ஏழைகளும்) எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!\") அதாவது நிராகரிப்பாளர்கள் குர்ஆனை நம்புபவர்களைப் பற்றி கூறுகிறார்கள்: \"குர்ஆன் ஏதேனும் நன்மையாக இருந்திருந்தால், இந்த (பலவீனமான) மக்கள் எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!\" இதன் மூலம் அவர்கள் பிலால் (ரழி), அம்மார் (ரழி), ஸுஹைப் (ரழி), கப்பாப் (ரழி) மற்றும் அவர்களைப் போன்ற பலவீனமானவர்களையும், ஆண் மற்றும் பெண் அடிமைகளையும் குறிப்பிட்டார்கள். இணைவைப்பாளர்கள் இவ்வாறு கூறியதற்குக் காரணம், அல்லாஹ்விடம் தங்களுக்கு உயரிய அந்தஸ்து இருப்பதாகவும், அவன் தங்களைச் சிறப்பாகக் கவனிப்பதாகவும் அவர்கள் கருதியதேயாகும். இதன் மூலம் அவர்கள் ஒரு பெரிய தெளிவான தவறைச் செய்தார்கள்; அல்லாஹ் கூறுவது போல்: ﴾وَكَذلِكَ فَتَنَّا بَعْضَهُمْ بِبَعْضٍ لِّيَقُولواْ أَهَـؤُلاءِ مَنَّ اللَّهُ عَلَيْهِم مِّن بَيْنِنَآ﴿\n\r\n\n\r\n(இவ்வாறு நாம் அவர்களில் சிலரை மற்றவர்களால் சோதித்தோம்; \"நம்மில் இவர்களுக்குத்தானா அல்லாஹ் அருள்புரிந்தான்?\" என்று அவர்கள் கேட்பதற்காக.) (6:53) அதாவது, தங்களை விட்டுவிட்டு அந்தப் பலவீனமானவர்கள் எவ்வாறு நேர்வழி பெற்றிருக்க முடியும் என்று அவர்கள் வியக்கின்றனர். எனவே, அல்லாஹ் கூறுகிறான்: ﴾لَوْ كَانَ خَيْراً مَّا سَبَقُونَآ إِلَيْهِ﴿\n\r\n\n\r\n(இது நல்லதாக இருந்திருந்தால், அவர்கள் எங்களை விட இதில் முந்தியிருக்க மாட்டார்கள்!) இதற்கு நேர்மாறானது அஹ்லுஸ் ஸுன்னா வல் ஜமாஆவின் நிலைப்பாடாகும்: ஸஹாபாக்களிடமிருந்து அறிவிக்கப்படாத எந்தவொரு செயல் அல்லது கூற்றைப் பற்றியும் அவர்கள் கூறுகிறார்கள்: \"அது ஒரு பித்அத் (புத்தாக்கம்). அதில் ஏதேனும் நன்மை இருந்திருந்தால், அதைச் செய்வதில் அவர்கள் நம்மை முந்தியிருப்பார்கள். ஏனெனில் ஸஹாபாக்கள் எந்தவொரு நற்பண்பையும் செய்யத் தவறவில்லை, மாறாக அவற்றைச் செய்வதில் அவர்கள் விரைந்து செயல்பட்டார்கள்.\" அல்லாஹ் தொடர்கிறான், ﴾وَإِذْ لَمْ يَهْتَدُواْ بِهِ﴿\n\r\n\n\r\n(மேலும் அவர்கள் இதன் மூலம் நேர்வழி பெறாதபோது,) அதாவது, குர்ஆன். ﴾فَسَيَقُولُونَ هَـذَآ إِفْكٌ قَدِيمٌ﴿\n\r\n\n\r\n(அவர்கள் கூறுகிறார்கள்: \"இது ஒரு பழங்காலப் பொய்!\") அதாவது, இது ஒரு பழைய பொய் என்கின்றனர். இதன் மூலம் குர்ஆனையும் அதைப் பின்பற்றுபவர்களையும் இழிவுபடுத்துவதற்காக, குர்ஆன் முன்னோர்களின் கதைகளிலிருந்து எடுக்கப்பட்டது என்று அவர்கள் வாதிடுகின்றனர். இது தெளிவான ஆணவமாகும்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியது போல்: ﴾«بَطَرُ الْحَقِّ وَغَمْطُ النَّاس»﴿\n\r\n\n\r\n((ஆணவம் என்பது) உண்மையை நிராகரிப்பதும், மக்களை இழிவுபடுத்துவதும் ஆகும்.) பின்னர் அல்லாஹ் கூறுகிறான், ﴾وَمِن قَبْلِهِ كِتَابُ مُوسَى﴿\n\r\n\n\r\n(இதற்கு முன்னால் மூஸாவின் (அலை) வேதம் இருந்தது) அது தவ்ராத் ஆகும். ﴾إِمَاماً وَرَحْمَةً وَهَـذَا كِتَـبٌ﴿\n\r\n\n\r\n(ஒரு வழிகாட்டியாகவும், கருணையாகவும். இந்த வேதம்...) அதாவது, குர்ஆன். ﴾مُّصَدِّقٌ﴿\n\r\n\n\r\n(உண்மைப்படுத்துவதாகும்) அதாவது, தனக்கு முன் வந்த முந்தைய வேதங்களை. ﴾لِّسَاناً عَرَبِيّاً﴿\n\r\n\n\r\n(அரபு மொழியில்,) அதாவது, அது மிகுந்த சொல்வளம் மிக்கதும் தெளிவானதும் ஆகும். ﴾لِّيُنذِرَ الَّذِينَ ظَلَمُواْ وَبُشْرَى لِلْمُحْسِنِينَ﴿\n\r\n\n\r\n(அநீதி இழைப்போரை எச்சரிக்கவும், நன்மை செய்வோருக்கு நற்செய்தியாகவும் (இது இருக்கிறது).) அதாவது, இது நிராகரிப்பாளர்களுக்கு எச்சரிக்கையையும், விசுவாசிகளுக்கு நற்செய்தியையும் கொண்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِنَّ الَّذِينَ قَالُواْ رَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ﴿\n\r\n\n\r\n(நிச்சயமாக, \"எங்கள் இறைவன் அல்லாஹ் (மட்டுமே)\" என்று கூறி, பிறகு அதில் உறுதியாகவும் இருப்பவர்கள்,) இதற்கான விளக்கம் முன்னரே சூரா ஹா-மீம் அஸ்-ஸஜ்தாவில் (41:30) விவாதிக்கப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான், ﴾فَلاَ خَوْفٌ عَلَيْهِمْ﴿\n\r\n\n\r\n(அவர்களுக்கு எந்தப் பயமும் இல்லை,) அதாவது, அவர்களின் எதிர்காலம் குறித்து. ﴾وَلاَ هُمْ يَحْزَنُونَ﴿\n\r\n\n\r\n(அவர்கள் கவலைப்படவும் மாட்டார்கள்.) அதாவது, அவர்கள் உலகில் விட்டுச் சென்றவை குறித்து. அல்லாஹ் தொடர்கிறான், ﴾أُوْلَـئِكَ أَصْحَـبُ الْجَنَّةِ خَـلِدِينَ فِيهَا جَزَآءً بِمَا كَانُواْ يَعْمَلُونَ ﴿\n\r\n\n\r\n(இவர்களே சுவனவாசிகள், அதில் அவர்கள் (என்றென்றும்) நிலைத்திருப்பார்கள் -- அவர்கள் செய்து கொண்டிருந்தவற்றிற்குப் பிரதிபலனாக.) அதாவது, நற்செயல்கள் அவர்கள் அல்லாஹ்வின் கருணையைப் பெறுவதற்கும், அது அவர்களைச் சூழ்ந்து கொள்வதற்கும் ஒரு காரணமாகும் -- அல்லாஹ்வே மிக அறிந்தவன்."},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=16\" class=\"link\">46:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>பெற்றோரைப் பற்றிய அல்லாஹ்வின் அறிவுரை</strong><br />\r\n<br />\r\nஅல்லாஹ், அவனது ஒருமைத்தன்மையை உறுதிப்படுத்துவது, அவனை உளத்தூய்மையுடன் வணங்குவது மற்றும் அவனுக்குக் கீழ்ப்படிவதில் உறுதியாக இருப்பது ஆகியவற்றைக் குறிப்பிட்ட பிறகு, அதைத் தொடர்ந்து பெற்றோரைப் பற்றிய அறிவுரைகளை வழங்குகிறான். குர்ஆனின் பல இடங்களில் இவை இணைத்தே கூறப்பட்டுள்ளன. உதாரணமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَضَى</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ</span> <span class=\"quran-arabic-font text-success\">وَبِالْوَالِدَيْنِ</span> <span class=\"quran-arabic-font text-success\">إِحْسَاناً﴿</span><br />\r\n<br />\r\n(உமது இறைவன், அவனைத் தவிர வேறு எவரையும் நீங்கள் வணங்கக் கூடாது என்றும், பெற்றோருக்கு உபகாரம் செய்ய வேண்டும் என்றும் கட்டளையிட்டுள்ளான்.) (<a href=\"qurandisp.php?sura=17&ayah=23\" class=\"link\">17:23</a>) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنِ</span> <span class=\"quran-arabic-font text-success\">اشْكُرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">وَلِوَالِدَيْكَ</span> <span class=\"quran-arabic-font text-success\">إِلَىَّ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ﴿</span><br />\r\n<br />\r\n(எனக்கும் உமது பெற்றோருக்கும் நன்றி செலுத்துவீராக. என்னிடமே மீளுதல் உண்டு.) (<a href=\"qurandisp.php?sura=31&ayah=14\" class=\"link\">31:14</a>) இது போன்ற இன்னும் பல வசனங்கள் உள்ளன. இங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَوَصَّيْنَا</span> <span class=\"quran-arabic-font text-success\">الإِنسَانَ</span> <span class=\"quran-arabic-font text-success\">بِوَالِدَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِحْسَاناً﴿</span><br />\r\n<br />\r\n(மேலும், மனிதன் தன் பெற்றோருக்கு நன்மையும் கனிவும் செய்ய வேண்டும் என்று நாம் வலியுறுத்தியுள்ளோம்.) (<a href=\"qurandisp.php?sura=46&ayah=15\" class=\"link\">46:15</a>) அதாவது, அவர்களை நன்றாக நடத்தவும், அவர்களிடம் கருணை காட்டவும் நாம் அவனுக்குக் கட்டளையிட்டுள்ளோம். ஸஃத் பின் அபீ வக்காஸ் (ரழி) அவர்களின் தாயார் அவரிடம், \"உன் பெற்றோருக்குக் கீழ்ப்படிய வேண்டும் என்று அல்லாஹ் உனக்குக் கட்டளையிடவில்லையா? அப்படியானால், நீ அல்லாஹ்வை நிராகரிக்கும் வரை நான் எதையும் உண்ணவோ பருகவோ மாட்டேன்\" என்று கூறியதாக அபூ தாவூத் அத்தயாலிசி பதிவு செய்துள்ளார். அவ்வாறே அவர் பிடிவாதமாக உண்ணாமலும் பருகாமலும் இருந்தார்; இறுதியில் ஒரு குச்சியைக் கொண்டு அவருடைய வாயைத் திறக்க வேண்டிய நிலை ஏற்பட்டது. அப்போதுதான் இந்த வசனம் அருளப்பட்டது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَوَصَّيْنَا</span> <span class=\"quran-arabic-font text-success\">الإِنسَانَ</span> <span class=\"quran-arabic-font text-success\">بِوَالِدَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِحْسَاناً﴿</span><br />\r\n<br />\r\n(மேலும், மனிதன் தன் பெற்றோருக்கு நன்மையும் கனிவும் செய்ய வேண்டும் என்று நாம் வலியுறுத்தியுள்ளோம்.) இதனை இப்னு மாஜாவைத் தவிர, இமாம் முஸ்லிம் மற்றும் சுனன் நூல்களின் ஆசிரியர்கள் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حَمَلَتْهُ</span> <span class=\"quran-arabic-font text-success\">أُمُّهُ</span> <span class=\"quran-arabic-font text-success\">كُرْهاً﴿</span><br />\r\n<br />\r\n(அவனுடைய தாய் அவனைச் சிரமத்துடனேயே சுமக்கிறாள்.) அதாவது, ஒரு தாய் தன் குழந்தைக்காகக் களைப்பு, நோய், வாந்தி, உடல் பாரம், மன உளைச்சல் மற்றும் கர்ப்பிணிப் பெண்கள் அனுபவிக்கும் பிற வகையான கஷ்டங்களை அனுபவிக்கிறாள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَوَضَعَتْهُ</span> <span class=\"quran-arabic-font text-success\">كُرْهاً﴿</span><br />\r\n<br />\r\n(மேலும் அவள் அவனைச் சிரமத்துடனேயே பெற்றெடுக்கிறாள்.) அதாவது, பிரசவ வேதனைகளையும் அதன் கடுமையையும் அனுபவித்து, அவள் அவனைப் பெற்றெடுக்கிறாள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَحَمْلُهُ</span> <span class=\"quran-arabic-font text-success\">وَفِصَالُهُ</span> <span class=\"quran-arabic-font text-success\">ثَلاَثُونَ</span> <span class=\"quran-arabic-font text-success\">شَهْراً﴿</span><br />\r\n<br />\r\n(அவனைக் கருவில் சுமப்பதும், அவனுக்குப் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்.) கர்ப்பத்தின் (கருவில் சுமக்கும்) குறைந்தபட்ச காலம் ஆறு மாதங்கள் என்பதை நிரூபிக்க, அலி (ரழி) அவர்கள் இந்த வசனத்துடன் பின்வரும் இரண்டு வசனங்களையும் ஆதாரமாகக் காட்டினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَفِصَالُهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَامَيْنِ﴿</span><br />\r\n<br />\r\n(மேலும் அவனுக்குப் பால் குடியை மறக்கடிப்பது இரண்டு ஆண்டுகளில் ஆகும்.) (<a href=\"qurandisp.php?sura=31&ayah=14\" class=\"link\">31:14</a>) மற்றும்<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالْوَالِدَاتُ</span> <span class=\"quran-arabic-font text-success\">يُرْضِعْنَ</span> <span class=\"quran-arabic-font text-success\">أَوْلاَدَهُنَّ</span> <span class=\"quran-arabic-font text-success\">حَوْلَيْنِ</span> <span class=\"quran-arabic-font text-success\">كَامِلَيْنِ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُتِمَّ</span> <span class=\"quran-arabic-font text-success\">الرَّضَاعَةَ﴿</span><br />\r\n<br />\r\n(தாய்மார்கள் தங்கள் குழந்தைகளுக்கு முழுமையாக இரண்டு ஆண்டுகள் பாலூட்ட வேண்டும் - பாலூட்டும் காலத்தை முழுமைப்படுத்த விரும்புவோருக்கு.) (<a href=\"qurandisp.php?sura=2&ayah=233\" class=\"link\">2:233</a>) இது ஒரு வலுவான மற்றும் சரியான முடிவாகும்; இதனை உஸ்மான் (ரழி) அவர்களும் பல ஸஹாபாக்களும் ஏற்றுக்கொண்டனர். முஹம்மது பின் இஸ்ஹாக் பின் யஸார், பஃஜா பின் அப்துல்லாஹ் அல்-ஜுஹானி வழியாக அறிவிக்கிறார்: ஜுஹைனா கோத்திரத்தைச் சேர்ந்த ஒருவர் அதே கோத்திரத்தைச் சேர்ந்த ஒரு பெண்ணை மணந்தார். அப்பெண் திருமணமான ஆறு மாதங்களிலேயே ஒரு குழந்தையைப் பெற்றெடுத்தாள். இது குறித்து அவளுடைய கணவர் உஸ்மான் (ரழி) அவர்களிடம் முறையிட்டார். உஸ்மான் (ரழி) அப்பெண்ணை அழைத்து வரச் சொன்னார். அவள் தயாராகிக் கொண்டிருந்தபோது, அவளுடைய சகோதரி அழத் தொடங்கினாள். அதற்கு அப்பெண், \"நீ ஏன் அழுகிறாய்? அல்லாஹ்வின் மீது சத்தியமாக, அல்லாஹ்வின் படைப்புகளில் என் கணவரைத் தவிர வேறு எவரும் என்னுடன் தாம்பத்திய உறவு கொண்டதில்லை. எனவே, அல்லாஹ் நாடியதைத் தீர்ப்பளிக்கட்டும்\" என்று கூறினாள். அவள் உஸ்மான் (ரழி) முன்னிலையில் கொண்டு வரப்பட்டபோது, விபச்சாரக் குற்றத்திற்காக அவளுக்குக் கல்லெறிந்து மரணதண்டனை நிறைவேற்ற அவர் கட்டளையிட்டார். இதை அறிந்த அலி (ரழி), உஸ்மான் (ரழி) அவர்களிடம் வந்து, \"நீங்கள் என்ன செய்கிறீர்கள்?\" என்று கேட்டார். அதற்கு அவர், \"அவள் ஆறு மாதங்களிலேயே குழந்தையைப் பெற்றெடுத்துள்ளாளே! இது சாத்தியமா?\" என்று கேட்டார். அதற்கு அலி (ரழி), \"நீங்கள் குர்ஆனை ஓதுவதில்லையா?\" என்று கேட்டார். \"ஆம், நிச்சயமாக!\" என்று உஸ்மான் (ரழி) பதிலளித்தார். அப்போது அலி (ரழி) பின்வரும் வசனங்களைக் குறிப்பிட்டுக் காட்டினார்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَحَمْلُهُ</span> <span class=\"quran-arabic-font text-success\">وَفِصَالُهُ</span> <span class=\"quran-arabic-font text-success\">ثَلاَثُونَ</span> <span class=\"quran-arabic-font text-success\">شَهْراً﴿</span><br />\r\n<br />\r\n(அவனைக் கருவில் சுமப்பதும் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்) மற்றும்;<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حَوْلَيْنِ</span> <span class=\"quran-arabic-font text-success\">كَامِلَيْنِ﴿</span><br />\r\n<br />\r\n(இரண்டு முழு ஆண்டுகள்) (<a href=\"qurandisp.php?sura=2&ayah=233\" class=\"link\">2:233</a>) (முப்பது மாதங்களிலிருந்து இருபத்தி நான்கு மாதங்களைக் கழித்தால்) மீதமுள்ள ஆறு மாதங்கள் கர்ப்ப காலமாகும்.\" இதைக் கேட்ட உஸ்மான் (ரழி), \"அல்லாஹ்வின் மீது சத்தியமாக, நான் இதை கவனிக்கவில்லை! அப்பெண்ணைத் திரும்ப அழைத்து வாருங்கள்\" என்றார். ஆனால் அதற்குள் அந்தப் பெண்ணுக்குத் தண்டனை நிறைவேற்றப்பட்டிருந்தது. பஃஜா கூறுகிறார்: \"அல்லாஹ்வின் மீது சத்தியமாக, அந்தப் பிள்ளை தன் தந்தையை அப்படியே உரித்து வைத்திருந்தது; இரண்டு காகங்களோ அல்லது இரண்டு முட்டைகளோ கூட அவ்வளவு ஒற்றுமையாக இருக்காது! அதைப் பார்த்த அவனுடைய தந்தை, 'அல்லாஹ்வின் மீது சத்தியமாக! இவன் சந்தேகமில்லாமல் என் மகனே' என்று கூறினான். பின்னர் (மனைவி மீது வீணாகப் பழி சுமத்தியதால்) அல்லாஹ் அவனுடைய முகத்தில் ஒரு தோல் புண்ணை ஏற்படுத்தினான். அது அவனை அரித்துக்கொண்டே இருந்து, இறுதியில் அவர் மரணமடைந்தார்.\"<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: \"ஒரு பெண் ஒன்பது மாதங்களில் குழந்தையைப் பெற்றெடுத்தால், அக்குழந்தைக்கு இருபத்தியோரு மாதங்கள் பாலூட்டினால் போதும். ஏழு மாதங்களில் பெற்றெடுத்தால், இருபத்தி மூன்று மாதங்கள் பாலூட்ட வேண்டும். ஆறு மாதங்களில் பெற்றெடுத்தால், முழுமையாக இரண்டு ஆண்டுகள் பாலூட்ட வேண்டும். ஏனெனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَحَمْلُهُ</span> <span class=\"quran-arabic-font text-success\">وَفِصَالُهُ</span> <span class=\"quran-arabic-font text-success\">ثَلاَثُونَ</span> <span class=\"quran-arabic-font text-success\">شَهْراً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">أَشُدَّهُ﴿</span><br />\r\n<br />\r\n(அவனைக் கருவில் சுமப்பதும் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்; அவன் தன் முழு வலிமையை அடையும் வரை.)\" அதாவது, அவன் வலிமையும் இளமையும் பெற்று, முழுத் திறனை அடையும் வரை.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَبَلَغَ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعِينَ</span> <span class=\"quran-arabic-font text-success\">سَنَةً﴿</span><br />\r\n<br />\r\n(மேலும் நாற்பது வயதை அடையும் போது,) அதாவது, அவனது அறிவும், புரிதலும், நிதானமும் முதிர்ச்சியடையும் போது. பொதுவாக ஒருவர் நாற்பது வயதை எட்டிய பிறகு தனது குணங்களை மாற்றிக்கொள்வது கடினம் என்றும் கூறப்படுகிறது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">أَوْزِعْنِى﴿</span><br />\r\n<br />\r\n(அவன் கூறுகிறான்: \"என் இறைவனே! எனக்குத் தூண்டுதல் அளிப்பாயாக!) அதாவது 'எனக்கு உத்வேகம் அளிப்பாயாக'.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنْ</span> <span class=\"quran-arabic-font text-success\">أَشْكُرَ</span> <span class=\"quran-arabic-font text-success\">نِعْمَتَكَ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أَنْعَمْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">وَالِدَىَّ</span> <span class=\"quran-arabic-font text-success\">وَأَنْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحاً</span> <span class=\"quran-arabic-font text-success\">تَرْضَاهُ﴿</span><br />\r\n<br />\r\n(நீ எனக்கும் என் பெற்றோருக்கும் புரிந்த உனது அருட்கொடைகளுக்காக நான் நன்றி செலுத்தவும், நீ உவகை கொள்ளும் நற்செயல்களை நான் செய்யவும் எனக்கு அருள் புரிவாயாக!) அதாவது எதிர்காலத்தில்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَصْلِحْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتِى﴿</span><br />\r\n<br />\r\n(மேலும், எனது சந்ததியினரையும் நல்லவர்களாக ஆக்கி வைப்பாயாக.) அதாவது எனது பிள்ளைகளையும் வழித்தோன்றல்களையும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّى</span> <span class=\"quran-arabic-font text-success\">تُبْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நான் உன்னிடம் பாவமன்னிப்புக் கோரி மீண்டுவிட்டேன்; இன்னும் நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்.) நாற்பது வயதை அடையும் எவரும் தனது பாவமன்னிப்பைப் புதுப்பித்து, உறுதியான மனதுடன் அல்லாஹ்வின் பக்கம் திரும்ப வேண்டும் என்பதற்கான அறிவுறுத்தல் இதில் உள்ளது. இந்த வசனம் அபூ பக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் விஷயத்தில் அருளப்பட்டது என்று அபூ அல்-ஆலியா, அத்-ளஹ்ஹாக் மற்றும் பலர் கூறுகின்றனர். ஏனெனில் அவர் நாற்பது வயதை அடைந்தபோது இஸ்லாத்தைத் தழுவினார்; அல்லாஹ் அவருக்கும், அவரது பெற்றோருக்கும், அவரது சந்ததியினருக்கும் அருள் புரிந்தான். அவரது தந்தை அபூ குஹாஃபா, தாயார் உம்முல் கைர், பிள்ளைகளான அப்துர் ரஹ்மான், ஆயிஷா மற்றும் அஸ்மா (ரழி) ஆகியோர் அனைவரும் இஸ்லாத்தை ஏற்றனர். அல்லாஹ்வின் திருப்பொருத்தத்தைப் பெற்றுக் கொண்டனர்.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أُوْلَئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">نَتَقَبَّلُ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">وَنَتَجَاوَزُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ﴿</span><br />\r\n<br />\r\n(இத்தகையோரிடமிருந்துதான் அவர்கள் செய்த நற்செயல்களில் மிகச் சிறந்தவற்றை நாம் ஏற்றுக்கொள்வோம்; அவர்களின் தீய செயல்களை நாம் மன்னிப்போம். (இவர்கள்) சுவனவாசிகளுடன் இருப்பார்கள்.) அதாவது, மேற்கண்ட பண்புகளை உடையவர்கள் - அல்லாஹ்விடம் தவ்பா செய்து, அவனிடம் மீண்டு, மன்னிப்புக் கோருவதன் மூலம் தங்கள் குறைகளைச் சரிசெய்துகொள்பவர்கள் - இவர்களிடமிருந்துதான் அவர்கள் செய்த சிறந்த செயல்களை நாம் ஏற்றுக்கொள்வோம், அவர்களின் தவறுகளை மன்னிப்போம். அவர்களின் பல பிழைகள் மன்னிக்கப்படும், அல்லாஹ் அவர்களிடமிருந்து சிறிய அளவு நற்செயல்களையும் ஏற்றுக்கொள்வான்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ﴿</span><br />\r\n<br />\r\n(சுவனவாசிகளுடன்.) இதன் பொருள் அவர்கள் சுவனவாசிகளுடன் இருப்பார்கள் என்பதாகும். இதுவே அல்லாஹ் அவர்களுக்கு அளித்த தீர்ப்பாகும்; ஏனெனில் மன்னிப்புக் கோரி மீளுபவர்களுக்கு அவன் இவ்வாறே வாக்களித்துள்ளான். அதனால் தான் அவன் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَعْدَ</span> <span class=\"quran-arabic-font text-success\">الصِّدْقِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ﴿</span><br />\r\n<br />\r\n(இது அவர்களுக்கு அளிக்கப்பட்ட உண்மையான வாக்குறுதியாகும்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"பெற்றோரைப் பற்றிய அல்லாஹ்வின் அறிவுரை\n\r\n\n\r\nஅல்லாஹ், அவனது ஒருமைத்தன்மையை உறுதிப்படுத்துவது, அவனை உளத்தூய்மையுடன் வணங்குவது மற்றும் அவனுக்குக் கீழ்ப்படிவதில் உறுதியாக இருப்பது ஆகியவற்றைக் குறிப்பிட்ட பிறகு, அதைத் தொடர்ந்து பெற்றோரைப் பற்றிய அறிவுரைகளை வழங்குகிறான். குர்ஆனின் பல இடங்களில் இவை இணைத்தே கூறப்பட்டுள்ளன. உதாரணமாக அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَقَضَى رَبُّكَ أَلاَّ تَعْبُدُواْ إِلاَّ إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَاناً﴿\n\r\n\n\r\n(உமது இறைவன், அவனைத் தவிர வேறு எவரையும் நீங்கள் வணங்கக் கூடாது என்றும், பெற்றோருக்கு உபகாரம் செய்ய வேண்டும் என்றும் கட்டளையிட்டுள்ளான்.) (17:23) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n﴾أَنِ اشْكُرْ لِى وَلِوَالِدَيْكَ إِلَىَّ الْمَصِيرُ﴿\n\r\n\n\r\n(எனக்கும் உமது பெற்றோருக்கும் நன்றி செலுத்துவீராக. என்னிடமே மீளுதல் உண்டு.) (31:14) இது போன்ற இன்னும் பல வசனங்கள் உள்ளன. இங்கே அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَاناً﴿\n\r\n\n\r\n(மேலும், மனிதன் தன் பெற்றோருக்கு நன்மையும் கனிவும் செய்ய வேண்டும் என்று நாம் வலியுறுத்தியுள்ளோம்.) (46:15) அதாவது, அவர்களை நன்றாக நடத்தவும், அவர்களிடம் கருணை காட்டவும் நாம் அவனுக்குக் கட்டளையிட்டுள்ளோம். ஸஃத் பின் அபீ வக்காஸ் (ரழி) அவர்களின் தாயார் அவரிடம், \"உன் பெற்றோருக்குக் கீழ்ப்படிய வேண்டும் என்று அல்லாஹ் உனக்குக் கட்டளையிடவில்லையா? அப்படியானால், நீ அல்லாஹ்வை நிராகரிக்கும் வரை நான் எதையும் உண்ணவோ பருகவோ மாட்டேன்\" என்று கூறியதாக அபூ தாவூத் அத்தயாலிசி பதிவு செய்துள்ளார். அவ்வாறே அவர் பிடிவாதமாக உண்ணாமலும் பருகாமலும் இருந்தார்; இறுதியில் ஒரு குச்சியைக் கொண்டு அவருடைய வாயைத் திறக்க வேண்டிய நிலை ஏற்பட்டது. அப்போதுதான் இந்த வசனம் அருளப்பட்டது:\n\r\n﴾وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَاناً﴿\n\r\n\n\r\n(மேலும், மனிதன் தன் பெற்றோருக்கு நன்மையும் கனிவும் செய்ய வேண்டும் என்று நாம் வலியுறுத்தியுள்ளோம்.) இதனை இப்னு மாஜாவைத் தவிர, இமாம் முஸ்லிம் மற்றும் சுனன் நூல்களின் ஆசிரியர்கள் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்:\n\r\n﴾حَمَلَتْهُ أُمُّهُ كُرْهاً﴿\n\r\n\n\r\n(அவனுடைய தாய் அவனைச் சிரமத்துடனேயே சுமக்கிறாள்.) அதாவது, ஒரு தாய் தன் குழந்தைக்காகக் களைப்பு, நோய், வாந்தி, உடல் பாரம், மன உளைச்சல் மற்றும் கர்ப்பிணிப் பெண்கள் அனுபவிக்கும் பிற வகையான கஷ்டங்களை அனுபவிக்கிறாள்.\n\r\n﴾وَوَضَعَتْهُ كُرْهاً﴿\n\r\n\n\r\n(மேலும் அவள் அவனைச் சிரமத்துடனேயே பெற்றெடுக்கிறாள்.) அதாவது, பிரசவ வேதனைகளையும் அதன் கடுமையையும் அனுபவித்து, அவள் அவனைப் பெற்றெடுக்கிறாள்.\n\r\n﴾وَحَمْلُهُ وَفِصَالُهُ ثَلاَثُونَ شَهْراً﴿\n\r\n\n\r\n(அவனைக் கருவில் சுமப்பதும், அவனுக்குப் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்.) கர்ப்பத்தின் (கருவில் சுமக்கும்) குறைந்தபட்ச காலம் ஆறு மாதங்கள் என்பதை நிரூபிக்க, அலி (ரழி) அவர்கள் இந்த வசனத்துடன் பின்வரும் இரண்டு வசனங்களையும் ஆதாரமாகக் காட்டினார்கள்:\n\r\n﴾وَفِصَالُهُ فِى عَامَيْنِ﴿\n\r\n\n\r\n(மேலும் அவனுக்குப் பால் குடியை மறக்கடிப்பது இரண்டு ஆண்டுகளில் ஆகும்.) (31:14) மற்றும்\n\r\n﴾وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلاَدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ الرَّضَاعَةَ﴿\n\r\n\n\r\n(தாய்மார்கள் தங்கள் குழந்தைகளுக்கு முழுமையாக இரண்டு ஆண்டுகள் பாலூட்ட வேண்டும் - பாலூட்டும் காலத்தை முழுமைப்படுத்த விரும்புவோருக்கு.) (2:233) இது ஒரு வலுவான மற்றும் சரியான முடிவாகும்; இதனை உஸ்மான் (ரழி) அவர்களும் பல ஸஹாபாக்களும் ஏற்றுக்கொண்டனர். முஹம்மது பின் இஸ்ஹாக் பின் யஸார், பஃஜா பின் அப்துல்லாஹ் அல்-ஜுஹானி வழியாக அறிவிக்கிறார்: ஜுஹைனா கோத்திரத்தைச் சேர்ந்த ஒருவர் அதே கோத்திரத்தைச் சேர்ந்த ஒரு பெண்ணை மணந்தார். அப்பெண் திருமணமான ஆறு மாதங்களிலேயே ஒரு குழந்தையைப் பெற்றெடுத்தாள். இது குறித்து அவளுடைய கணவர் உஸ்மான் (ரழி) அவர்களிடம் முறையிட்டார். உஸ்மான் (ரழி) அப்பெண்ணை அழைத்து வரச் சொன்னார். அவள் தயாராகிக் கொண்டிருந்தபோது, அவளுடைய சகோதரி அழத் தொடங்கினாள். அதற்கு அப்பெண், \"நீ ஏன் அழுகிறாய்? அல்லாஹ்வின் மீது சத்தியமாக, அல்லாஹ்வின் படைப்புகளில் என் கணவரைத் தவிர வேறு எவரும் என்னுடன் தாம்பத்திய உறவு கொண்டதில்லை. எனவே, அல்லாஹ் நாடியதைத் தீர்ப்பளிக்கட்டும்\" என்று கூறினாள். அவள் உஸ்மான் (ரழி) முன்னிலையில் கொண்டு வரப்பட்டபோது, விபச்சாரக் குற்றத்திற்காக அவளுக்குக் கல்லெறிந்து மரணதண்டனை நிறைவேற்ற அவர் கட்டளையிட்டார். இதை அறிந்த அலி (ரழி), உஸ்மான் (ரழி) அவர்களிடம் வந்து, \"நீங்கள் என்ன செய்கிறீர்கள்?\" என்று கேட்டார். அதற்கு அவர், \"அவள் ஆறு மாதங்களிலேயே குழந்தையைப் பெற்றெடுத்துள்ளாளே! இது சாத்தியமா?\" என்று கேட்டார். அதற்கு அலி (ரழி), \"நீங்கள் குர்ஆனை ஓதுவதில்லையா?\" என்று கேட்டார். \"ஆம், நிச்சயமாக!\" என்று உஸ்மான் (ரழி) பதிலளித்தார். அப்போது அலி (ரழி) பின்வரும் வசனங்களைக் குறிப்பிட்டுக் காட்டினார்:\n\r\n﴾وَحَمْلُهُ وَفِصَالُهُ ثَلاَثُونَ شَهْراً﴿\n\r\n\n\r\n(அவனைக் கருவில் சுமப்பதும் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்) மற்றும்;\n\r\n﴾حَوْلَيْنِ كَامِلَيْنِ﴿\n\r\n\n\r\n(இரண்டு முழு ஆண்டுகள்) (2:233) (முப்பது மாதங்களிலிருந்து இருபத்தி நான்கு மாதங்களைக் கழித்தால்) மீதமுள்ள ஆறு மாதங்கள் கர்ப்ப காலமாகும்.\" இதைக் கேட்ட உஸ்மான் (ரழி), \"அல்லாஹ்வின் மீது சத்தியமாக, நான் இதை கவனிக்கவில்லை! அப்பெண்ணைத் திரும்ப அழைத்து வாருங்கள்\" என்றார். ஆனால் அதற்குள் அந்தப் பெண்ணுக்குத் தண்டனை நிறைவேற்றப்பட்டிருந்தது. பஃஜா கூறுகிறார்: \"அல்லாஹ்வின் மீது சத்தியமாக, அந்தப் பிள்ளை தன் தந்தையை அப்படியே உரித்து வைத்திருந்தது; இரண்டு காகங்களோ அல்லது இரண்டு முட்டைகளோ கூட அவ்வளவு ஒற்றுமையாக இருக்காது! அதைப் பார்த்த அவனுடைய தந்தை, 'அல்லாஹ்வின் மீது சத்தியமாக! இவன் சந்தேகமில்லாமல் என் மகனே' என்று கூறினான். பின்னர் (மனைவி மீது வீணாகப் பழி சுமத்தியதால்) அல்லாஹ் அவனுடைய முகத்தில் ஒரு தோல் புண்ணை ஏற்படுத்தினான். அது அவனை அரித்துக்கொண்டே இருந்து, இறுதியில் அவர் மரணமடைந்தார்.\"\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்: \"ஒரு பெண் ஒன்பது மாதங்களில் குழந்தையைப் பெற்றெடுத்தால், அக்குழந்தைக்கு இருபத்தியோரு மாதங்கள் பாலூட்டினால் போதும். ஏழு மாதங்களில் பெற்றெடுத்தால், இருபத்தி மூன்று மாதங்கள் பாலூட்ட வேண்டும். ஆறு மாதங்களில் பெற்றெடுத்தால், முழுமையாக இரண்டு ஆண்டுகள் பாலூட்ட வேண்டும். ஏனெனில் அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَحَمْلُهُ وَفِصَالُهُ ثَلاَثُونَ شَهْراً حَتَّى إِذَا بَلَغَ أَشُدَّهُ﴿\n\r\n\n\r\n(அவனைக் கருவில் சுமப்பதும் பால் குடியை மறக்கடிப்பதும் முப்பது மாதங்களாகும்; அவன் தன் முழு வலிமையை அடையும் வரை.)\" அதாவது, அவன் வலிமையும் இளமையும் பெற்று, முழுத் திறனை அடையும் வரை.\n\r\n﴾وَبَلَغَ أَرْبَعِينَ سَنَةً﴿\n\r\n\n\r\n(மேலும் நாற்பது வயதை அடையும் போது,) அதாவது, அவனது அறிவும், புரிதலும், நிதானமும் முதிர்ச்சியடையும் போது. பொதுவாக ஒருவர் நாற்பது வயதை எட்டிய பிறகு தனது குணங்களை மாற்றிக்கொள்வது கடினம் என்றும் கூறப்படுகிறது.\n\r\n﴾قَالَ رَبِّ أَوْزِعْنِى﴿\n\r\n\n\r\n(அவன் கூறுகிறான்: \"என் இறைவனே! எனக்குத் தூண்டுதல் அளிப்பாயாக!) அதாவது 'எனக்கு உத்வேகம் அளிப்பாயாக'.\n\r\n﴾أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِى أَنْعَمْتَ عَلَىَّ وَعَلَى وَالِدَىَّ وَأَنْ أَعْمَلَ صَالِحاً تَرْضَاهُ﴿\n\r\n\n\r\n(நீ எனக்கும் என் பெற்றோருக்கும் புரிந்த உனது அருட்கொடைகளுக்காக நான் நன்றி செலுத்தவும், நீ உவகை கொள்ளும் நற்செயல்களை நான் செய்யவும் எனக்கு அருள் புரிவாயாக!) அதாவது எதிர்காலத்தில்.\n\r\n﴾وَأَصْلِحْ لِى فِى ذُرِّيَّتِى﴿\n\r\n\n\r\n(மேலும், எனது சந்ததியினரையும் நல்லவர்களாக ஆக்கி வைப்பாயாக.) அதாவது எனது பிள்ளைகளையும் வழித்தோன்றல்களையும்.\n\r\n﴾إِنَّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ الْمُسْلِمِينَ﴿\n\r\n\n\r\n(நிச்சயமாக நான் உன்னிடம் பாவமன்னிப்புக் கோரி மீண்டுவிட்டேன்; இன்னும் நிச்சயமாக நான் முஸ்லிம்களில் ஒருவன்.) நாற்பது வயதை அடையும் எவரும் தனது பாவமன்னிப்பைப் புதுப்பித்து, உறுதியான மனதுடன் அல்லாஹ்வின் பக்கம் திரும்ப வேண்டும் என்பதற்கான அறிவுறுத்தல் இதில் உள்ளது. இந்த வசனம் அபூ பக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் விஷயத்தில் அருளப்பட்டது என்று அபூ அல்-ஆலியா, அத்-ளஹ்ஹாக் மற்றும் பலர் கூறுகின்றனர். ஏனெனில் அவர் நாற்பது வயதை அடைந்தபோது இஸ்லாத்தைத் தழுவினார்; அல்லாஹ் அவருக்கும், அவரது பெற்றோருக்கும், அவரது சந்ததியினருக்கும் அருள் புரிந்தான். அவரது தந்தை அபூ குஹாஃபா, தாயார் உம்முல் கைர், பிள்ளைகளான அப்துர் ரஹ்மான், ஆயிஷா மற்றும் அஸ்மா (ரழி) ஆகியோர் அனைவரும் இஸ்லாத்தை ஏற்றனர். அல்லாஹ்வின் திருப்பொருத்தத்தைப் பெற்றுக் கொண்டனர்.\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n﴾أُوْلَئِكَ الَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّئَاتِهِمْ فِى أَصْحَابِ الْجَنَّةِ﴿\n\r\n\n\r\n(இத்தகையோரிடமிருந்துதான் அவர்கள் செய்த நற்செயல்களில் மிகச் சிறந்தவற்றை நாம் ஏற்றுக்கொள்வோம்; அவர்களின் தீய செயல்களை நாம் மன்னிப்போம். (இவர்கள்) சுவனவாசிகளுடன் இருப்பார்கள்.) அதாவது, மேற்கண்ட பண்புகளை உடையவர்கள் - அல்லாஹ்விடம் தவ்பா செய்து, அவனிடம் மீண்டு, மன்னிப்புக் கோருவதன் மூலம் தங்கள் குறைகளைச் சரிசெய்துகொள்பவர்கள் - இவர்களிடமிருந்துதான் அவர்கள் செய்த சிறந்த செயல்களை நாம் ஏற்றுக்கொள்வோம், அவர்களின் தவறுகளை மன்னிப்போம். அவர்களின் பல பிழைகள் மன்னிக்கப்படும், அல்லாஹ் அவர்களிடமிருந்து சிறிய அளவு நற்செயல்களையும் ஏற்றுக்கொள்வான்.\n\r\n﴾فِى أَصْحَابِ الْجَنَّةِ﴿\n\r\n\n\r\n(சுவனவாசிகளுடன்.) இதன் பொருள் அவர்கள் சுவனவாசிகளுடன் இருப்பார்கள் என்பதாகும். இதுவே அல்லாஹ் அவர்களுக்கு அளித்த தீர்ப்பாகும்; ஏனெனில் மன்னிப்புக் கோரி மீளுபவர்களுக்கு அவன் இவ்வாறே வாக்களித்துள்ளான். அதனால் தான் அவன் கூறுகிறான்:\n\r\n﴾وَعْدَ الصِّدْقِ الَّذِى كَانُواْ يُوعَدُونَ﴿\n\r\n\n\r\n(இது அவர்களுக்கு அளிக்கப்பட்ட உண்மையான வாக்குறுதியாகும்.)"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=20\" class=\"link\">46:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=20\" class=\"link\">46:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=20\" class=\"link\">46:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>பெற்றோருக்கு மாறு செய்யும் பிள்ளைகள் மற்றும் அவர்களின் முடிவு</strong><br />\r\n<br />\r\nமுந்தைய வசனங்களில், அல்லாஹ் தனது பெற்றோருக்காகப் பிரார்த்தனை செய்து, அவர்களிடம் கனிவாக நடந்துகொள்ளும் நற்பண்புள்ள பிள்ளைகளைப் பற்றிக் குறிப்பிட்டுள்ளான். அவர்களுக்காக தான் தயாரித்துள்ள வெற்றியையும் பாதுகாப்பையும் அவன் விவரிக்கிறான். அதனைத் தொடர்ந்து, பெற்றோரிடம் மரியாதையின்றி நடக்கும் துர்பாக்கியசாலி பிள்ளைகளின் நிலையை இங்கே அதனுடன் இணைத்துக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِوَالِدَيْهِ</span> <span class=\"quran-arabic-font text-success\">أُفٍّ</span> <span class=\"quran-arabic-font text-success\">لَكُمَا</span><br />\r\n<br />\r\n(ஆனால், தன் பெற்றோரைப் பார்த்து, \"சீச்சீ! உங்களுக்குக் கேடு உண்டாகட்டும்...\" என்று கூறுபவன்...) இந்த வசனத்தில் இடம்பெற்றுள்ள \"சீச்சீ\" (உஃப்) என்ற சொல், தனது பெற்றோரிடம் அவ்வாறு சொல்லும் எவருக்கும் பொருந்தக்கூடிய ஒரு பொதுவான விவரிப்பாகும். இந்த வசனம் அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்களைப் பற்றி அருளப்பட்டதாகச் சிலர் கூறுகின்றனர். ஆனால், இக்கூற்று பலவீனமானதும் நிராகரிக்கப்பட வேண்டியதுமாகும். ஏனெனில், இந்த வசனம் அருளப்பட்ட பின்னரே அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்றார்கள். அவர்களின் இஸ்லாமிய வாழ்க்கை மிகச் சிறந்ததாக இருந்தது; அவர்கள் தங்களது சமகாலத்தவர்களில் மிகச் சிறந்தவர்களில் ஒருவராகத் திகழ்ந்தார்கள். இமாம் புகாரி அவர்கள் யூஸுஃப் பின் மஹக் வழியாகப் பதிவு செய்துள்ளதாவது: முஆவியா பின் அபீ ஸுஃப்யான் (ரழி) அவர்களால் ஹிஜாஸின் (மேற்கு அரேபியா) ஆளுநராக மர்வான் (பின் அல்-ஹகம்) நியமிக்கப்பட்டிருந்தார். மர்வான் ஒரு சொற்பொழிவின் போது, யஸீத் பின் முஆவியாவைப் பற்றிக் குறிப்பிட்டு, அவரது தந்தைக்குப் பிறகு அவருக்கு விசுவாசப் பிரமாணம் (பைஅத்) செய்யுமாறு மக்களை வலியுறுத்தினான். அதற்குப் பதிலாக அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள் அவரிடம் ஏதோ கூறினார்கள். உடனே மர்வான், \"அவரைக் கைது செய்யுங்கள்!\" என்று தன் ஆட்களுக்கு உத்தரவிட்டான். ஆனால், அவர்கள் பிடிக்க வருவதற்குள் அவர் ஆயிஷா (ரழி) அவர்களின் வீட்டிற்குள் நுழைந்துவிட்டதால், அவர்களால் அவரைப் பிடிக்க முடியவில்லை. அப்போது மர்வான் கூறினான்: \"இவரைப் பற்றித்தான் அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِوَالِدَيْهِ</span> <span class=\"quran-arabic-font text-success\">أُفٍّ</span> <span class=\"quran-arabic-font text-success\">لَكُمَا</span> <span class=\"quran-arabic-font text-success\">أَتَعِدَانِنِي</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أُخْرَجَ</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتِ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِي</span><br />\r\n<br />\r\n(ஆனால், தன் பெற்றோரிடம் \"சீச்சீ! உங்களுக்குக் கேடுதான்! எனக்கு முன் எத்தனையோ தலைமுறையினர் கடந்து சென்றுவிட்ட நிலையில், நான் மீண்டும் எழுப்பப்படுவேன் என்று எனக்கு நீங்கள் வாக்குறுதி அளிக்கிறீர்களா?\")\" அப்போது திரைக்குப் பின்னாலிருந்து ஆயிஷா (ரழி) அவர்கள் பதிலளித்தார்கள்: \"அல்லாஹ் எங்கள் விஷயத்தில் (அபூபக்ரின் பிள்ளைகள் தொடர்பாக) எனது கற்புத் தூய்மையை உறுதிப்படுத்திய வசனங்களைத் தவிர வேறு எந்த குர்ஆன் வசனத்தையும் அருளவில்லை.\" நஸாயீயில் பதிவாகியுள்ள மற்றொரு அறிவிப்பில், முஹம்மது பின் ஸியாத் கூறியதாவது: முஆவியா (ரழி) அவர்கள் தன் மகனுக்கு விசுவாசப் பிரமாணம் பெறுவதற்காக மக்களைத் தூண்டியபோது, மர்வான், \"இது அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரின் வழிமுறையைப் பின்பற்றுவதாகும்\" என்று அறிவித்தான். இதைக் கேட்ட அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள், \"மாறாக, இது ஹெராக்ளியஸ் மற்றும் கிஸ்ராவின் வழிமுறையாகும்\" என்று கூறினார்கள். அதற்கு மர்வான், \"இவரைப் பற்றித்தான் அல்லாஹ் இந்த வசனத்தை அருளினான்\" என்று கூற,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِوَالِدَيْهِ</span> <span class=\"quran-arabic-font text-success\">أُفٍّ</span> <span class=\"quran-arabic-font text-success\">لَكُمَا</span><br />\r\n<br />\r\n(ஆனால், தன் பெற்றோரிடம் \"சீச்சீ! உங்களுக்குக் கேடுதான்!\" என்று கூறுபவன்...) என்ற வசனத்தை ஓதினான். இது ஆயிஷா (ரழி) அவர்களிடம் தெரிவிக்கப்பட்டபோது, அவர்கள் கூறினார்கள்: \"மர்வான் பொய் சொல்கிறான்! அல்லாஹ்வின் மீது ஆணையாக, இந்த வசனம் அவரைப் பற்றி அருளப்படவில்லை. நான் விரும்பினால், இந்த வசனம் யாரைக் குறிப்பிடுகிறது என்பதை என்னால் பெயரிட்டுக் கூற முடியும். அதே சமயம், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மர்வானின் தந்தை (அல்-ஹகம் பின் அபில் ஆஸ்) மீது சாபமிட்டார்கள்; அப்போது மர்வான் தனது தந்தையின் முதுகுத் தண்டில் (கருவாக உருவாகும் நிலையில்) இருந்தான். எனவே மர்வான் (பின் அல்-ஹகம்) அல்லாஹ்வின் சாபத்தின் விளைவாக வந்தவன் ஆவான்.\" அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَعِدَانِنِى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أُخْرَجَ</span><br />\r\n<br />\r\n(நான் மீண்டும் எழுப்பப்படுவேன் என்று எனக்கு வாக்குறுதி அளிக்கிறீர்களா) அதாவது, மரணத்திற்குப் பின் மீண்டும் உயிர்ப்பிக்கப்படுவேன் என்பதா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتِ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِى</span><br />\r\n<br />\r\n(எனக்கு முன் எத்தனையோ தலைமுறையினர் கடந்து சென்றுவிட்ட நிலையில்) அதாவது, எனக்கு முன்பே பல தலைமுறையினர் இறந்து மறைந்துவிட்டனர்; அவர்களில் எவரும் தங்களுக்கு என்ன நேர்ந்தது என்று சொல்லத் திரும்பி வரவில்லையே!<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُمَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَغِيثَانِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(அவர்கள் இருவரும் உதவிக்காக அல்லாஹ்விடம் கதறுகிறார்கள்) அதாவது, அவனுக்கு நேர்வழி காட்டுமாறு அல்லாஹ்விடம் வேண்டுகிறார்கள். மேலும் அவர்கள் தங்கள் மகனிடம் கூறுகிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيْلَكَ</span> <span class=\"quran-arabic-font text-success\">آمِنْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">وَعْدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَقٌّ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَسَاطِيرُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ</span><br />\r\n<br />\r\n(\"உனக்குக் கேடுதான்! ஈமான் (நம்பிக்கை) கொள்! நிச்சயமாக அல்லாஹ்வின் வாக்குறுதி உண்மையானது.\" ஆனால் அவனோ, \"இது முன்னோர்களின் கட்டுக்கதைகளே தவிர வேறில்லை\" என்று கூறுகிறான்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُمَمٍ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">وَالْإِنْسِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">خَاسِرِينَ</span><br />\r\n<br />\r\n(இவர்களுக்கு முன்னால் கடந்து சென்ற ஜின்கள் மற்றும் மனிதர்களின் கூட்டத்தாரைப் போலவே, இவர்களுக்கும் வேதனை பற்றிய இறைவாக்கு உறுதியாகிவிட்டது. நிச்சயமாக அவர்கள் நஷ்டமடைந்தவர்களாகவே இருக்கிறார்கள்.) இத்தகையவர்கள் அனைவரும், மறுமை நாளில் தங்களையும் தங்கள் குடும்பத்தாரையும் இழக்க நேரிடும் நிராகரிப்பாளர்களான தங்களைப் போன்றவர்களுடனேயே இருப்பார்கள் என்பதை இது காட்டுகிறது. அல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span><br />\r\n<br />\r\n(இவர்கள்) என்பது, அவன் முன்னதாகக் கூறிய<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span><br />\r\n<br />\r\n(கூறுபவன்) என்ற சொல்லுடன் இணைந்து, இது ஒரு குறிப்பிட்ட நபரைக் குறிக்காமல், இத்தகைய குணங்களைக் கொண்ட அனைத்து மக்களையும் உள்ளடக்கிய பொதுவான விவரிப்பு என்பதை உறுதிப்படுத்துகிறது. அல்-ஹஸன் மற்றும் கத்தாதா ஆகிய இரு அறிஞர்களும், \"இது பெற்றோரை மதிக்காத, மறுமையை மறுக்கின்ற பாவியான நிராகரிப்பாளர்களுக்குப் பொருந்தும்\" என்று கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِكُلٍّ</span> <span class=\"quran-arabic-font text-success\">دَرَجَاتٌ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">عَمِلُوا</span><br />\r\n<br />\r\n(மேலும், அவர்கள் செய்த செயல்களுக்கு ஏற்ப அவர்கள் ஒவ்வொருவருக்கும் படித்தரங்கள் உண்டு.) அதாவது, அவர்கள் செய்த தீய செயல்களின் அளவிற்கேற்ப நரக வேதனையிலும் பல்வேறு நிலைகள் இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلِيُوَفِّيَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُظْلَمُونَ</span><br />\r\n<br />\r\n(அவர்களுடைய செயல்களுக்குரிய கூலியை அவன் முழுமையாக வழங்குவான்; மேலும் அவர்களுக்கு அநீதி இழைக்கப்பட மாட்டாது.) அதாவது அல்லாஹ் அவர்களுக்கு ஓர் அணுவளவும் அநீதி இழைக்க மாட்டான். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"நரகத்தின் நிலைகள் கீழ்நோக்கிச் செல்கின்றன, சுவனத்தின் நிலைகள் மேல்நோக்கிச் செல்கின்றன.\" பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُعْرَضُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">أَذْهَبْتُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَيَاتِكُمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَاسْتَمْتَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் நரக நெருப்பின் முன் கொண்டு வரப்படும் நாளில் (அவர்களிடம் சொல்லப்படும்): \"உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்; அவற்றைக் கொண்டு இன்பமும் துய்த்துவிட்டீர்கள்...\") அதாவது அவர்களைக் கண்டிக்கும் விதமாகவும், பழிக்கும் விதமாகவும் இது கூறப்படும். அமீருல் முஃமினீன் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், இவ்வுலகின் ஆடம்பர உணவுகளையும் பானங்களையும் பெருமளவு தவிர்த்து வந்தார்கள். \"அல்லாஹ் யாரைக் கண்டித்துப் பேசினானோ, அவர்களைப் போல நான் ஆகிவிடுவேனோ என்று அஞ்சுகிறேன்\" என்று கூறி, இந்த வசனத்தை ஓதுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَذْهَبْتُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَيَاتِكُمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَاسْتَمْتَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்; அவற்றைக் கொண்டு இன்பமும் துய்த்துவிட்டீர்கள்.) அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"சிலர் இவ்வுலகில் தாங்கள் செய்த நற்செயல்களின் பலனை இங்கேயே அனுபவித்து விடுவார்கள். அவர்களிடம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَذْهَبْتُمْ</span> <span class=\"quran-arabic-font text-success\">طَيِّبَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَيَاتِكُمُ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்) என்று கூறப்படும்.\" பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَالْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْهُونِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">تَسْتَكْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَبِمَا</span> <span class=\"quran-arabic-font text-success\">كُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">تَفْسُقُونَ</span><br />\r\n<br />\r\n(ஆகவே, நீங்கள் பூமியில் நியாயமின்றிப் பெருமை அடித்துக் கொண்டிருந்ததாலும், நீங்கள் வரம்பு மீறி நடந்துகொண்டிருந்ததாலும், இன்று இழிவுபடுத்தும் வேதனையைக் கூலியாக வழங்கப்படுவீர்கள்.) இது அவர்களின் தண்டனை, அவர்கள் செய்த செயல்களுக்கு ஏற்றவாறு அமையும் என்பதைக் காட்டுகிறது. அவர்கள் இவ்வுலகில் இன்பங்களில் மூழ்கித் திளைத்தனர், சத்தியத்தை ஏற்காமல் ஆணவம் கொண்டனர், மேலும் பாவங்களிலும் கீழ்ப்படியாமையிலும் ஈடுபட்டனர். எனவே அல்லாஹ் அவர்களைக் கடும் இழிவு, அவமானம், தீராத துன்பம் மற்றும் நரகத்தின் ஆழமான பகுதிகளில் தள்ளித் தண்டிக்கிறான். அல்லாஹ் நம் அனைவரையும் அதிலிருந்து பாதுகாப்பானாக!<br />\r\n<br />","text":"பெற்றோருக்கு மாறு செய்யும் பிள்ளைகள் மற்றும் அவர்களின் முடிவு\n\r\n\n\r\nமுந்தைய வசனங்களில், அல்லாஹ் தனது பெற்றோருக்காகப் பிரார்த்தனை செய்து, அவர்களிடம் கனிவாக நடந்துகொள்ளும் நற்பண்புள்ள பிள்ளைகளைப் பற்றிக் குறிப்பிட்டுள்ளான். அவர்களுக்காக தான் தயாரித்துள்ள வெற்றியையும் பாதுகாப்பையும் அவன் விவரிக்கிறான். அதனைத் தொடர்ந்து, பெற்றோரிடம் மரியாதையின்றி நடக்கும் துர்பாக்கியசாலி பிள்ளைகளின் நிலையை இங்கே அதனுடன் இணைத்துக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِي قَالَ لِوَالِدَيْهِ أُفٍّ لَكُمَا\n\r\n\n\r\n(ஆனால், தன் பெற்றோரைப் பார்த்து, \"சீச்சீ! உங்களுக்குக் கேடு உண்டாகட்டும்...\" என்று கூறுபவன்...) இந்த வசனத்தில் இடம்பெற்றுள்ள \"சீச்சீ\" (உஃப்) என்ற சொல், தனது பெற்றோரிடம் அவ்வாறு சொல்லும் எவருக்கும் பொருந்தக்கூடிய ஒரு பொதுவான விவரிப்பாகும். இந்த வசனம் அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்களைப் பற்றி அருளப்பட்டதாகச் சிலர் கூறுகின்றனர். ஆனால், இக்கூற்று பலவீனமானதும் நிராகரிக்கப்பட வேண்டியதுமாகும். ஏனெனில், இந்த வசனம் அருளப்பட்ட பின்னரே அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்றார்கள். அவர்களின் இஸ்லாமிய வாழ்க்கை மிகச் சிறந்ததாக இருந்தது; அவர்கள் தங்களது சமகாலத்தவர்களில் மிகச் சிறந்தவர்களில் ஒருவராகத் திகழ்ந்தார்கள். இமாம் புகாரி அவர்கள் யூஸுஃப் பின் மஹக் வழியாகப் பதிவு செய்துள்ளதாவது: முஆவியா பின் அபீ ஸுஃப்யான் (ரழி) அவர்களால் ஹிஜாஸின் (மேற்கு அரேபியா) ஆளுநராக மர்வான் (பின் அல்-ஹகம்) நியமிக்கப்பட்டிருந்தார். மர்வான் ஒரு சொற்பொழிவின் போது, யஸீத் பின் முஆவியாவைப் பற்றிக் குறிப்பிட்டு, அவரது தந்தைக்குப் பிறகு அவருக்கு விசுவாசப் பிரமாணம் (பைஅத்) செய்யுமாறு மக்களை வலியுறுத்தினான். அதற்குப் பதிலாக அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள் அவரிடம் ஏதோ கூறினார்கள். உடனே மர்வான், \"அவரைக் கைது செய்யுங்கள்!\" என்று தன் ஆட்களுக்கு உத்தரவிட்டான். ஆனால், அவர்கள் பிடிக்க வருவதற்குள் அவர் ஆயிஷா (ரழி) அவர்களின் வீட்டிற்குள் நுழைந்துவிட்டதால், அவர்களால் அவரைப் பிடிக்க முடியவில்லை. அப்போது மர்வான் கூறினான்: \"இவரைப் பற்றித்தான் அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَالَّذِي قَالَ لِوَالِدَيْهِ أُفٍّ لَكُمَا أَتَعِدَانِنِي أَنْ أُخْرَجَ وَقَدْ خَلَتِ الْقُرُونُ مِن قَبْلِي\n\r\n\n\r\n(ஆனால், தன் பெற்றோரிடம் \"சீச்சீ! உங்களுக்குக் கேடுதான்! எனக்கு முன் எத்தனையோ தலைமுறையினர் கடந்து சென்றுவிட்ட நிலையில், நான் மீண்டும் எழுப்பப்படுவேன் என்று எனக்கு நீங்கள் வாக்குறுதி அளிக்கிறீர்களா?\")\" அப்போது திரைக்குப் பின்னாலிருந்து ஆயிஷா (ரழி) அவர்கள் பதிலளித்தார்கள்: \"அல்லாஹ் எங்கள் விஷயத்தில் (அபூபக்ரின் பிள்ளைகள் தொடர்பாக) எனது கற்புத் தூய்மையை உறுதிப்படுத்திய வசனங்களைத் தவிர வேறு எந்த குர்ஆன் வசனத்தையும் அருளவில்லை.\" நஸாயீயில் பதிவாகியுள்ள மற்றொரு அறிவிப்பில், முஹம்மது பின் ஸியாத் கூறியதாவது: முஆவியா (ரழி) அவர்கள் தன் மகனுக்கு விசுவாசப் பிரமாணம் பெறுவதற்காக மக்களைத் தூண்டியபோது, மர்வான், \"இது அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரின் வழிமுறையைப் பின்பற்றுவதாகும்\" என்று அறிவித்தான். இதைக் கேட்ட அப்துர் ரஹ்மான் இப்னு அபீ பக்ர் (ரழி) அவர்கள், \"மாறாக, இது ஹெராக்ளியஸ் மற்றும் கிஸ்ராவின் வழிமுறையாகும்\" என்று கூறினார்கள். அதற்கு மர்வான், \"இவரைப் பற்றித்தான் அல்லாஹ் இந்த வசனத்தை அருளினான்\" என்று கூற,\n\r\n\n\r\nوَالَّذِي قَالَ لِوَالِدَيْهِ أُفٍّ لَكُمَا\n\r\n\n\r\n(ஆனால், தன் பெற்றோரிடம் \"சீச்சீ! உங்களுக்குக் கேடுதான்!\" என்று கூறுபவன்...) என்ற வசனத்தை ஓதினான். இது ஆயிஷா (ரழி) அவர்களிடம் தெரிவிக்கப்பட்டபோது, அவர்கள் கூறினார்கள்: \"மர்வான் பொய் சொல்கிறான்! அல்லாஹ்வின் மீது ஆணையாக, இந்த வசனம் அவரைப் பற்றி அருளப்படவில்லை. நான் விரும்பினால், இந்த வசனம் யாரைக் குறிப்பிடுகிறது என்பதை என்னால் பெயரிட்டுக் கூற முடியும். அதே சமயம், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மர்வானின் தந்தை (அல்-ஹகம் பின் அபில் ஆஸ்) மீது சாபமிட்டார்கள்; அப்போது மர்வான் தனது தந்தையின் முதுகுத் தண்டில் (கருவாக உருவாகும் நிலையில்) இருந்தான். எனவே மர்வான் (பின் அல்-ஹகம்) அல்லாஹ்வின் சாபத்தின் விளைவாக வந்தவன் ஆவான்.\" அல்லாஹ்வின் கூற்றைப் பொறுத்தவரை:\n\r\n\n\r\nأَتَعِدَانِنِى أَنْ أُخْرَجَ\n\r\n\n\r\n(நான் மீண்டும் எழுப்பப்படுவேன் என்று எனக்கு வாக்குறுதி அளிக்கிறீர்களா) அதாவது, மரணத்திற்குப் பின் மீண்டும் உயிர்ப்பிக்கப்படுவேன் என்பதா?\n\r\n\n\r\nوَقَدْ خَلَتِ الْقُرُونُ مِن قَبْلِى\n\r\n\n\r\n(எனக்கு முன் எத்தனையோ தலைமுறையினர் கடந்து சென்றுவிட்ட நிலையில்) அதாவது, எனக்கு முன்பே பல தலைமுறையினர் இறந்து மறைந்துவிட்டனர்; அவர்களில் எவரும் தங்களுக்கு என்ன நேர்ந்தது என்று சொல்லத் திரும்பி வரவில்லையே!\n\r\n\n\r\nوَهُمَا يَسْتَغِيثَانِ اللَّهَ\n\r\n\n\r\n(அவர்கள் இருவரும் உதவிக்காக அல்லாஹ்விடம் கதறுகிறார்கள்) அதாவது, அவனுக்கு நேர்வழி காட்டுமாறு அல்லாஹ்விடம் வேண்டுகிறார்கள். மேலும் அவர்கள் தங்கள் மகனிடம் கூறுகிறார்கள்:\n\r\n\n\r\nوَيْلَكَ آمِنْ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَيَقُولُ مَا هَذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ\n\r\n\n\r\n(\"உனக்குக் கேடுதான்! ஈமான் (நம்பிக்கை) கொள்! நிச்சயமாக அல்லாஹ்வின் வாக்குறுதி உண்மையானது.\" ஆனால் அவனோ, \"இது முன்னோர்களின் கட்டுக்கதைகளே தவிர வேறில்லை\" என்று கூறுகிறான்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأُولَئِكَ الَّذِينَ حَقَّ عَلَيْهِمُ الْقَوْلُ فِي أُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِهِمْ مِنَ الْجِنِّ وَالْإِنْسِ إِنَّهُمْ كَانُوا خَاسِرِينَ\n\r\n\n\r\n(இவர்களுக்கு முன்னால் கடந்து சென்ற ஜின்கள் மற்றும் மனிதர்களின் கூட்டத்தாரைப் போலவே, இவர்களுக்கும் வேதனை பற்றிய இறைவாக்கு உறுதியாகிவிட்டது. நிச்சயமாக அவர்கள் நஷ்டமடைந்தவர்களாகவே இருக்கிறார்கள்.) இத்தகையவர்கள் அனைவரும், மறுமை நாளில் தங்களையும் தங்கள் குடும்பத்தாரையும் இழக்க நேரிடும் நிராகரிப்பாளர்களான தங்களைப் போன்றவர்களுடனேயே இருப்பார்கள் என்பதை இது காட்டுகிறது. அல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nأُولَئِكَ\n\r\n\n\r\n(இவர்கள்) என்பது, அவன் முன்னதாகக் கூறிய\n\r\n\n\r\nوَالَّذِي قَالَ\n\r\n\n\r\n(கூறுபவன்) என்ற சொல்லுடன் இணைந்து, இது ஒரு குறிப்பிட்ட நபரைக் குறிக்காமல், இத்தகைய குணங்களைக் கொண்ட அனைத்து மக்களையும் உள்ளடக்கிய பொதுவான விவரிப்பு என்பதை உறுதிப்படுத்துகிறது. அல்-ஹஸன் மற்றும் கத்தாதா ஆகிய இரு அறிஞர்களும், \"இது பெற்றோரை மதிக்காத, மறுமையை மறுக்கின்ற பாவியான நிராகரிப்பாளர்களுக்குப் பொருந்தும்\" என்று கூறியுள்ளனர். பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلِكُلٍّ دَرَجَاتٌ مِمَّا عَمِلُوا\n\r\n\n\r\n(மேலும், அவர்கள் செய்த செயல்களுக்கு ஏற்ப அவர்கள் ஒவ்வொருவருக்கும் படித்தரங்கள் உண்டு.) அதாவது, அவர்கள் செய்த தீய செயல்களின் அளவிற்கேற்ப நரக வேதனையிலும் பல்வேறு நிலைகள் இருக்கும்.\n\r\n\n\r\nوَلِيُوَفِّيَهُمْ أَعْمَالَهُمْ وَهُمْ لَا يُظْلَمُونَ\n\r\n\n\r\n(அவர்களுடைய செயல்களுக்குரிய கூலியை அவன் முழுமையாக வழங்குவான்; மேலும் அவர்களுக்கு அநீதி இழைக்கப்பட மாட்டாது.) அதாவது அல்லாஹ் அவர்களுக்கு ஓர் அணுவளவும் அநீதி இழைக்க மாட்டான். அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"நரகத்தின் நிலைகள் கீழ்நோக்கிச் செல்கின்றன, சுவனத்தின் நிலைகள் மேல்நோக்கிச் செல்கின்றன.\" பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا\n\r\n\n\r\n(நிராகரிப்பாளர்கள் நரக நெருப்பின் முன் கொண்டு வரப்படும் நாளில் (அவர்களிடம் சொல்லப்படும்): \"உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்; அவற்றைக் கொண்டு இன்பமும் துய்த்துவிட்டீர்கள்...\") அதாவது அவர்களைக் கண்டிக்கும் விதமாகவும், பழிக்கும் விதமாகவும் இது கூறப்படும். அமீருல் முஃமினீன் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள், இவ்வுலகின் ஆடம்பர உணவுகளையும் பானங்களையும் பெருமளவு தவிர்த்து வந்தார்கள். \"அல்லாஹ் யாரைக் கண்டித்துப் பேசினானோ, அவர்களைப் போல நான் ஆகிவிடுவேனோ என்று அஞ்சுகிறேன்\" என்று கூறி, இந்த வசனத்தை ஓதுவார்கள்:\n\r\n\n\r\nأَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا\n\r\n\n\r\n(உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்; அவற்றைக் கொண்டு இன்பமும் துய்த்துவிட்டீர்கள்.) அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"சிலர் இவ்வுலகில் தாங்கள் செய்த நற்செயல்களின் பலனை இங்கேயே அனுபவித்து விடுவார்கள். அவர்களிடம்,\n\r\n\n\r\nأَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا\n\r\n\n\r\n(உங்கள் உலக வாழ்க்கையிலேயே உங்களுக்குரிய நல்லவற்றை நீங்கள் அனுபவித்துத் தீர்த்துவிட்டீர்கள்) என்று கூறப்படும்.\" பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَالْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنْتُمْ تَسْتَكْبِرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَفْسُقُونَ\n\r\n\n\r\n(ஆகவே, நீங்கள் பூமியில் நியாயமின்றிப் பெருமை அடித்துக் கொண்டிருந்ததாலும், நீங்கள் வரம்பு மீறி நடந்துகொண்டிருந்ததாலும், இன்று இழிவுபடுத்தும் வேதனையைக் கூலியாக வழங்கப்படுவீர்கள்.) இது அவர்களின் தண்டனை, அவர்கள் செய்த செயல்களுக்கு ஏற்றவாறு அமையும் என்பதைக் காட்டுகிறது. அவர்கள் இவ்வுலகில் இன்பங்களில் மூழ்கித் திளைத்தனர், சத்தியத்தை ஏற்காமல் ஆணவம் கொண்டனர், மேலும் பாவங்களிலும் கீழ்ப்படியாமையிலும் ஈடுபட்டனர். எனவே அல்லாஹ் அவர்களைக் கடும் இழிவு, அவமானம், தீராத துன்பம் மற்றும் நரகத்தின் ஆழமான பகுதிகளில் தள்ளித் தண்டிக்கிறான். அல்லாஹ் நம் அனைவரையும் அதிலிருந்து பாதுகாப்பானாக!"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=25\" class=\"link\">46:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:25 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=25\" class=\"link\">46:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:25 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=25\" class=\"link\">46:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:25 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=25\" class=\"link\">46:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:25 ஐ பார்க்கவும்"},"25":{"html":"<strong>ஆத் கூட்டத்தினரின் வரலாறு</strong><br />\r\n<br />\r\nதன் மக்களில் தன்னை எதிர்த்தவர்களின் நிராகரிப்பைக் குறித்து தன் தூதருக்கு ஆறுதல் கூறும் விதமாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاذْكُرْ</span> <span class=\"quran-arabic-font text-success\">أَخَا</span> <span class=\"quran-arabic-font text-success\">عَادٍ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">أَنذَرَ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">بِالأَحْقَافِ</span><br />\r\n<br />\r\n(ஆத் கூட்டத்தினரின் சகோதரரை நினைவுகூருவீராக! அவர் அஹ்காஃப் பகுதியில் தம் சமூகத்தாரை எச்சரித்தபோது...) இது ஹூத் (அலை) அவர்களைக் குறிக்கிறது. அஹ்காஃப் பகுதியில் வசித்த 'ஆதுல் ஊலா' (முந்தைய ஆத்) கூட்டத்தினரிடம் அல்லாஹ் அவர்களை அனுப்பினான். 'அஹ்காஃப்' என்பது 'ஹக்ஃப்' என்பதன் பன்மை வடிவமாகும். இப்னு ஜைத் (ரழி) அவர்களின் கருத்தின்படி, இதன் பொருள் மணல் குன்று என்பதாகும். இக்ரிமா (ரழி) அவர்களின் கூற்றுப்படி, இது ஒரு மலை அல்லது குகையைக் குறிக்கும். கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"ஆத் என்பது யமனிலுள்ள ஒரு கோத்திரம் என்று எங்களுக்கு அறிவிக்கப்பட்டது. அவர்கள் அஷ்-ஷிஹ்ர் என்றழைக்கப்பட்ட நிலப்பரப்பில் மணல் குன்றுகளுக்கு மத்தியில் வசித்தார்கள்; அங்கிருந்து கடலைப் பார்க்க முடியும்.\" \"பிரார்த்தனை செய்பவர் முதலில் தமக்காகப் பிரார்த்திக்க வேண்டும்\" என்ற அத்தியாயத்தின் கீழ், இப்னு அப்பாஸ் (ரழி) அறிவித்ததாக இப்னு மாஜா பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَرْحَمُنَا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَأَخَا</span> <span class=\"quran-arabic-font text-success\">عَاد</span>»<br />\r\n<br />\r\n(அல்லாஹ் நம்மீதும் ஆத் கூட்டத்தின் சகோதரர் மீதும் கருணை புரிவானாக!) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">خَلَتِ</span> <span class=\"quran-arabic-font text-success\">النُّذُرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவருக்கு முன்னரும் அவருக்குப் பின்னரும் எச்சரிக்கை செய்பவர்கள் கடந்து சென்றுள்ளனர்.) அதாவது, ஆத் கூட்டத்தினர் வாழ்ந்த பகுதியைச் சுற்றியுள்ள ஊர்களுக்கு அல்லாஹ் தூதர்களையும் எச்சரிக்கை செய்பவர்களையும் அனுப்பியிருந்தான். இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهَا</span> <span class=\"quran-arabic-font text-success\">نَكَـلاً</span> <span class=\"quran-arabic-font text-success\">لِّمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلْفَهَا</span><br />\r\n<br />\r\n(மேலும், அக்காலத்தில் இருந்தவர்களுக்கும், அவர்களுக்குப் பின் வந்தவர்களுக்கும் இதனை ஒரு படிப்பினையான தண்டனையாக நாம் ஆக்கினோம்.) (<a href=\"qurandisp.php?sura=2&ayah=66\" class=\"link\">2:66</a>). மேலும் இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதும் ஆகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضُواْ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">أَنذَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">صَـعِقَةً</span> <span class=\"quran-arabic-font text-success\">مِّثْلَ</span> <span class=\"quran-arabic-font text-success\">صَـعِقَةِ</span> <span class=\"quran-arabic-font text-success\">عَادٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمُودَ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَآءَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் புறக்கணித்தால், \"ஆத் மற்றும் தமூத் கூட்டத்தினரைத் தாக்கிய இடியைப் போன்ற ஒரு வேதனையைப் பற்றி நான் உங்களை எச்சரிக்கிறேன்\" என்று கூறுவீராக! தூதர்கள் அவர்களுக்கு முன்னிருந்தும் பின்னிருந்தும் வந்து, \"அல்லாஹ்வைத் தவிர வேறு எவரையும் வணங்காதீர்கள்\" என்று கூறியபோது (இவ்எச்சரிக்கை விடுக்கப்பட்டது).) (<a href=\"qurandisp.php?sura=41&ayah=13\" class=\"link\">41:13</a>-14). பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span><br />\r\n<br />\r\n(நிச்சயமாக, ஒரு மகத்தான நாளின் வேதனை உங்களுக்கு ஏற்பட்டு விடுமோ என்று நான் அஞ்சுகிறேன்.) அதாவது, ஹூத் (அலை) அவர்கள் இதைத் தன் மக்களிடம் கூறினார்கள். அதற்கு அவர்கள் இவ்வாறு பதிலளித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَجِئْتَنَا</span> <span class=\"quran-arabic-font text-success\">لِتَأْفِكَنَا</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتِنَا</span><br />\r\n<br />\r\n(எங்கள் தெய்வங்களை வணங்குவதிலிருந்து எங்களைத் திசைதிருப்புவதற்காகவா நீர் எங்களிடம் வந்திருக்கிறீர்?) அதாவது, எங்களைத் தடுப்பதற்காகவா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتِنَا</span><br />\r\n<br />\r\n(எங்கள் தெய்வங்களிடமிருந்து)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْتِنَا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعِدُنَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّـدِقِينَ</span><br />\r\n<br />\r\n(நீர் உண்மையாளர்களில் ஒருவராக இருந்தால், நீர் எங்களை அச்சுறுத்தும் அந்த வேதனையைக் கொண்டு வாரும்!) அவர்கள் அல்லாஹ்வின் தண்டனை வராது என்று நம்பி, அதை விரைவுபடுத்தக் கோரினார்கள். இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَسْتَعْجِلُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span><br />\r\n<br />\r\n(மறுமை நாளை நம்பாதவர்கள் அதை விரைவுபடுத்தக் கோருகிறார்கள்.) (<a href=\"qurandisp.php?sura=42&ayah=18\" class=\"link\">42:18</a>). ஹூத் (அலை) அவர்களின் பதில் இதுவாக இருந்தது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْعِلْمُ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَأُبَلِّغُكُم</span> <span class=\"quran-arabic-font text-success\">مَّآ</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span><br />\r\n<br />\r\n(அவர் கூறினார்கள்: \"(அத்தண்டனை எப்போது வரும் என்பது பற்றிய) அறிவு அல்லாஹ்விடமே உள்ளது.\") இதன் பொருள், 'உங்களைப் பற்றி அல்லாஹ்வே நன்கு அறிவான். நீங்கள் தண்டனையை விரைவுபடுத்தத் தகுதியானவர்களாக இருந்தால், அவன் அதை உங்களுக்கு வழங்குவான். என்னைப் பொறுத்தவரை, எனது செய்தியை உங்களிடம் சேர்ப்பதுதான் என் கடமை.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِنِّى</span> <span class=\"quran-arabic-font text-success\">أَرَاكُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمًا</span> <span class=\"quran-arabic-font text-success\">تَجْهَلُونَ</span><br />\r\n<br />\r\n(ஆனால், நீங்கள் அறிவற்ற ஒரு சமூகமாகவே இருப்பதை நான் காண்கிறேன்!) அதாவது, 'உங்களுக்கு எந்தப் புரிதலோ அறிவோ இல்லை.' பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْهُ</span> <span class=\"quran-arabic-font text-success\">عَارِضاً</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقْبِلَ</span> <span class=\"quran-arabic-font text-success\">أَوْدِيَتِهِمْ</span><br />\r\n<br />\r\n(பின்னர், அது தங்களின் பள்ளத்தாக்குகளை நோக்கி வரும் ஒரு அடர்ந்த மேகமாக அவர்கள் கண்டபோது,)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَارِضٌ</span> <span class=\"quran-arabic-font text-success\">مُّمْطِرُنَا</span><br />\r\n<br />\r\n(\"இது எங்களுக்கு மழையைத் தரும் மேகம்\" என்று அவர்கள் கூறினார்கள்.) அதாவது, தண்டனை தங்களை நோக்கி வருவதைக் கண்டபோது, அதை மழையைத் தரும் மேகம் என்று அவர்கள் எண்ணினார்கள். வறட்சியினால் மழை தேவைப்பட்ட நிலையில் இருந்த அவர்களுக்கு அது மிகுந்த மகிழ்ச்சியைத் தந்தது. அப்போது அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">اسْتَعْجَلْتُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">رِيحٌ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span><br />\r\n<br />\r\n(அப்படியல்ல! இது நீங்கள் எதை அவசரப்படுத்தக் கோரினீர்களோ அதுவேயாகும்; இது ஒரு காற்றாகும், இதில் வலிமிகுந்த வேதனை உள்ளது!) அதாவது, \"நீர் உண்மையாளராக இருந்தால் நீர் வாக்களித்த வேதனையைக் கொண்டு வாரும்\" என்று நீங்கள் கேட்ட வேதனை இதுவே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تُدَمِّرُ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(அது ஒவ்வொன்றையும் அழித்துவிடும்) அதாவது, பொதுவாக எவையெல்லாம் அழியுமோ அத்தகைய அவர்களின் நிலப்பரப்பின் ஒவ்வொரு பகுதியையும் அது அழித்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِأَمْرِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهَا</span><br />\r\n<br />\r\n(அதன் இறைவனுடைய கட்டளையால்!) அதாவது, அதைச் செய்வதற்கு அதற்கு அல்லாஹ்வின் அனுமதி இருந்தது. இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَذَرُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">أَتَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلَتْهُ</span> <span class=\"quran-arabic-font text-success\">كَالرَّمِيمِ</span><br />\r\n<br />\r\n(அது சென்றடைந்த எதையும் விட்டுவைக்கவில்லை; மாறாக அதனை உக்கிப்போன சிதைவுகளைப் போல ஆக்கிவிட்டது.) (<a href=\"qurandisp.php?sura=51&ayah=42\" class=\"link\">51:42</a>). இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْصْبَحُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُرَى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَسَـكِنُهُمْ</span><br />\r\n<br />\r\n(எனவே, அவர்களின் குடியிருப்புகளைத் தவிர வேறெதுவும் காணப்படாத நிலைக்கு அவர்கள் ஆளானார்கள்!) அதாவது, அவர்கள் அனைவரும் அழிக்கப்பட்டார்கள்; அவர்களில் எவரும் தப்பவில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذلِكَ</span> <span class=\"quran-arabic-font text-success\">نَجْزِي</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span><br />\r\n<br />\r\n(இவ்வாறே நாம் குற்றவாளி சமூகத்திற்குத் தண்டனை வழங்குகிறோம்!) அதாவது, நமது தூதர்களை நிராகரித்து, நமது கட்டளைகளுக்கு மாறுசெய்பவர்கள் குறித்து நமது தீர்ப்பு இதுவேயாகும். இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் உள்நாக்குத் தெரியும்படி வாய்விட்டுச் சிரிப்பதை நான் ஒருபோதும் பார்த்ததில்லை; அவர்கள் புன்னகைப்பவர்களாகவே இருந்தார்கள்.\" மேகங்களையோ காற்றையோ காணும்போது நபியவர்களின் முகத்தில் ஒருவிதக் கலக்கம் தெரியும் என்று ஆயிஷா (ரழி) கூறினார்கள். இது குறித்து அவர்கள் நபியவர்களிடம், \"அல்லாஹ்வின் தூதரே! மக்கள் மேகங்களைக் காணும்போது அது மழையைக் கொண்டுவரும் என்று மகிழ்ச்சியடைகிறார்கள். ஆனால் நீங்கள் அவற்றைக் காணும்போது உங்கள் முகத்தில் அதிருப்தி தோன்றுவதை நான் கவனிக்கிறேனே?\" என்று கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عَائِشَةُ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُنِي</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَكُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ،</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">عُذِّبَ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">بِالرِّيحِ،</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">رَأَى</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">وَقَالُوا</span>: <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">عَارِضٌ</span> <span class=\"quran-arabic-font text-success\">مُمْطِرُنَا</span>»<br />\r\n<br />\r\n(ஆயிஷாவே! அந்த மேகத்தில் வேதனை இருக்காது என்பதற்கு எனக்கு என்ன நிச்சயம்? சில சமூகங்கள் காற்றினால் தண்டிக்கப்பட்டுள்ளன. தண்டனை தங்களை நோக்கி வருவதைக் கண்ட ஒரு சமூகம், 'இது எங்களுக்கு மழையைத் தரும் மேகம்' என்றுதான் கூறியது.) இது புகாரி மற்றும் முஸ்லிமிலும் பதிவு செய்யப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் அறிவிக்கிறார்கள், ஆயிஷா (ரழி) கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அடிவானத்தில் மேகங்களைக் கண்டால், தாம் எதில் ஈடுபட்டிருந்தாலும் - தொழுகையில் இருந்தாலும் கூட - அதை விட்டுவிட்டு இவ்வாறு பிரார்த்திப்பார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِيه</span>»<br />\r\n<br />\r\n(அல்லாஹ்வே! இதில் உள்ள தீங்கிலிருந்து உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.) அல்லாஹ் அந்த மேகங்களை அகற்றிவிட்டால் நபியவர்கள் அல்லாஹ்வைப் புகழ்வார்கள்; மழை பொழிந்தால்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">صَيِّبًا</span> <span class=\"quran-arabic-font text-success\">نَافِعًا</span>»<br />\r\n<br />\r\n(அல்லாஹ்வே! இதனைப் பயனுள்ள மழையாக ஆக்குவாயாக) என்று கூறுவார்கள்.<br />\r\n<br />\r\nமுஸ்லிம் அவர்களும் தமது ஸஹீஹில் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: காற்று வீசும்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرَهَا</span> <span class=\"quran-arabic-font text-success\">وَخَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَخَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ،وَأَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّهَا،</span> <span class=\"quran-arabic-font text-success\">وَشَرِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا،</span> <span class=\"quran-arabic-font text-success\">وَشَرِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span>»<br />\r\n<br />\r\n(அல்லாஹ்வே! நான் உன்னிடம் இதன் நன்மையையும், இதில் உள்ள நன்மையையும், இது எதனுடன் அனுப்பப்பட்டதோ அந்த நன்மையையும் வேண்டுகிறேன். மேலும் இதன் தீங்கிலிருந்தும், இதில் உள்ள தீங்கிலிருந்தும், இது எதனுடன் அனுப்பப்பட்டதோ அந்தத் தீங்கிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.) வானம் மேகமூட்டமாக மாறினால் நபியவர்களின் முகம் மாறிவிடும்; அவர்கள் பதற்றத்துடன் உள்ளேயும் வெளியேயும் சென்று வருவார்கள். மழை பெய்துவிட்டால் அவர்களின் கவலை தணிந்துவிடும். ஆயிஷா (ரழி) அவர்கள் இதைக் கவனித்து நபியவர்களிடம் கேட்டபோது அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَعَلَّهُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عَائِشَةُ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">قَوْمُ</span> <span class=\"quran-arabic-font text-success\">عَادٍ</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْهُ</span> <span class=\"quran-arabic-font text-success\">عَارِضاً</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقْبِلَ</span> <span class=\"quran-arabic-font text-success\">أَوْدِيَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَارِضٌ</span> <span class=\"quran-arabic-font text-success\">مُّمْطِرُنَا</span>»<br />\r\n<br />\r\n(ஆயிஷாவே! இது ஆத் கூட்டத்தினர் கூறியது போலவும் இருக்கலாம்: \"பின்னர், அது தங்களின் பள்ளத்தாக்குகளை நோக்கி வரும் ஒரு அடர்ந்த மேகமாக அவர்கள் கண்டபோது: 'இது எங்களுக்கு மழை பொழியும் மேகம்' என்று கூறினார்கள்.\") ஆத் கூட்டத்தினரின் அழிவு பற்றிய வரலாற்றை நாம் ஏற்கனவே சூரா அல்-அஃராஃப் மற்றும் சூரா ஹூத் ஆகிய அத்தியாயங்களில் விளக்கியுள்ளோம். எனவே, அதனை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"ஆத் கூட்டத்தினரின் வரலாறு\n\r\n\n\r\nதன் மக்களில் தன்னை எதிர்த்தவர்களின் நிராகரிப்பைக் குறித்து தன் தூதருக்கு ஆறுதல் கூறும் விதமாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَاذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُ بِالأَحْقَافِ\n\r\n\n\r\n(ஆத் கூட்டத்தினரின் சகோதரரை நினைவுகூருவீராக! அவர் அஹ்காஃப் பகுதியில் தம் சமூகத்தாரை எச்சரித்தபோது...) இது ஹூத் (அலை) அவர்களைக் குறிக்கிறது. அஹ்காஃப் பகுதியில் வசித்த 'ஆதுல் ஊலா' (முந்தைய ஆத்) கூட்டத்தினரிடம் அல்லாஹ் அவர்களை அனுப்பினான். 'அஹ்காஃப்' என்பது 'ஹக்ஃப்' என்பதன் பன்மை வடிவமாகும். இப்னு ஜைத் (ரழி) அவர்களின் கருத்தின்படி, இதன் பொருள் மணல் குன்று என்பதாகும். இக்ரிமா (ரழி) அவர்களின் கூற்றுப்படி, இது ஒரு மலை அல்லது குகையைக் குறிக்கும். கதாதா (ரழி) அவர்கள் கூறினார்கள்: \"ஆத் என்பது யமனிலுள்ள ஒரு கோத்திரம் என்று எங்களுக்கு அறிவிக்கப்பட்டது. அவர்கள் அஷ்-ஷிஹ்ர் என்றழைக்கப்பட்ட நிலப்பரப்பில் மணல் குன்றுகளுக்கு மத்தியில் வசித்தார்கள்; அங்கிருந்து கடலைப் பார்க்க முடியும்.\" \"பிரார்த்தனை செய்பவர் முதலில் தமக்காகப் பிரார்த்திக்க வேண்டும்\" என்ற அத்தியாயத்தின் கீழ், இப்னு அப்பாஸ் (ரழி) அறிவித்ததாக இப்னு மாஜா பதிவு செய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَرْحَمُنَا اللهُ وَأَخَا عَاد»\n\r\n\n\r\n(அல்லாஹ் நம்மீதும் ஆத் கூட்டத்தின் சகோதரர் மீதும் கருணை புரிவானாக!) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقَدْ خَلَتِ النُّذُرُ مِن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ\n\r\n\n\r\n(நிச்சயமாக, அவருக்கு முன்னரும் அவருக்குப் பின்னரும் எச்சரிக்கை செய்பவர்கள் கடந்து சென்றுள்ளனர்.) அதாவது, ஆத் கூட்டத்தினர் வாழ்ந்த பகுதியைச் சுற்றியுள்ள ஊர்களுக்கு அல்லாஹ் தூதர்களையும் எச்சரிக்கை செய்பவர்களையும் அனுப்பியிருந்தான். இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nفَجَعَلْنَـهَا نَكَـلاً لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا\n\r\n\n\r\n(மேலும், அக்காலத்தில் இருந்தவர்களுக்கும், அவர்களுக்குப் பின் வந்தவர்களுக்கும் இதனை ஒரு படிப்பினையான தண்டனையாக நாம் ஆக்கினோம்.) (2:66). மேலும் இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதும் ஆகும்:\n\r\n\n\r\nفَإِنْ أَعْرَضُواْ فَقُلْ أَنذَرْتُكُمْ صَـعِقَةً مِّثْلَ صَـعِقَةِ عَادٍ وَثَمُودَ إِذْ جَآءَتْهُمُ الرُّسُلُ مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلاَّ تَعْبُدُواْ إِلاَّ اللَّهَ\n\r\n\n\r\n(ஆனால் அவர்கள் புறக்கணித்தால், \"ஆத் மற்றும் தமூத் கூட்டத்தினரைத் தாக்கிய இடியைப் போன்ற ஒரு வேதனையைப் பற்றி நான் உங்களை எச்சரிக்கிறேன்\" என்று கூறுவீராக! தூதர்கள் அவர்களுக்கு முன்னிருந்தும் பின்னிருந்தும் வந்து, \"அல்லாஹ்வைத் தவிர வேறு எவரையும் வணங்காதீர்கள்\" என்று கூறியபோது (இவ்எச்சரிக்கை விடுக்கப்பட்டது).) (41:13-14). பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنِّى أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ\n\r\n\n\r\n(நிச்சயமாக, ஒரு மகத்தான நாளின் வேதனை உங்களுக்கு ஏற்பட்டு விடுமோ என்று நான் அஞ்சுகிறேன்.) அதாவது, ஹூத் (அலை) அவர்கள் இதைத் தன் மக்களிடம் கூறினார்கள். அதற்கு அவர்கள் இவ்வாறு பதிலளித்தார்கள்:\n\r\n\n\r\nأَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا\n\r\n\n\r\n(எங்கள் தெய்வங்களை வணங்குவதிலிருந்து எங்களைத் திசைதிருப்புவதற்காகவா நீர் எங்களிடம் வந்திருக்கிறீர்?) அதாவது, எங்களைத் தடுப்பதற்காகவா?\n\r\n\n\r\nعَنْ ءَالِهَتِنَا\n\r\n\n\r\n(எங்கள் தெய்வங்களிடமிருந்து)\n\r\n\n\r\nفَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ الصَّـدِقِينَ\n\r\n\n\r\n(நீர் உண்மையாளர்களில் ஒருவராக இருந்தால், நீர் எங்களை அச்சுறுத்தும் அந்த வேதனையைக் கொண்டு வாரும்!) அவர்கள் அல்லாஹ்வின் தண்டனை வராது என்று நம்பி, அதை விரைவுபடுத்தக் கோரினார்கள். இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nيَسْتَعْجِلُ بِهَا الَّذِينَ لاَ يُؤْمِنُونَ بِهَا\n\r\n\n\r\n(மறுமை நாளை நம்பாதவர்கள் அதை விரைவுபடுத்தக் கோருகிறார்கள்.) (42:18). ஹூத் (அலை) அவர்களின் பதில் இதுவாக இருந்தது:\n\r\n\n\r\nقَالَ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِ\n\r\n\n\r\n(அவர் கூறினார்கள்: \"(அத்தண்டனை எப்போது வரும் என்பது பற்றிய) அறிவு அல்லாஹ்விடமே உள்ளது.\") இதன் பொருள், 'உங்களைப் பற்றி அல்லாஹ்வே நன்கு அறிவான். நீங்கள் தண்டனையை விரைவுபடுத்தத் தகுதியானவர்களாக இருந்தால், அவன் அதை உங்களுக்கு வழங்குவான். என்னைப் பொறுத்தவரை, எனது செய்தியை உங்களிடம் சேர்ப்பதுதான் என் கடமை.'\n\r\n\n\r\nوَلَـكِنِّى أَرَاكُمْ قَوْمًا تَجْهَلُونَ\n\r\n\n\r\n(ஆனால், நீங்கள் அறிவற்ற ஒரு சமூகமாகவே இருப்பதை நான் காண்கிறேன்!) அதாவது, 'உங்களுக்கு எந்தப் புரிதலோ அறிவோ இல்லை.' பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلَمَّا رَأَوْهُ عَارِضاً مُّسْتَقْبِلَ أَوْدِيَتِهِمْ\n\r\n\n\r\n(பின்னர், அது தங்களின் பள்ளத்தாக்குகளை நோக்கி வரும் ஒரு அடர்ந்த மேகமாக அவர்கள் கண்டபோது,)\n\r\n\n\r\nقَالُواْ هَـذَا عَارِضٌ مُّمْطِرُنَا\n\r\n\n\r\n(\"இது எங்களுக்கு மழையைத் தரும் மேகம்\" என்று அவர்கள் கூறினார்கள்.) அதாவது, தண்டனை தங்களை நோக்கி வருவதைக் கண்டபோது, அதை மழையைத் தரும் மேகம் என்று அவர்கள் எண்ணினார்கள். வறட்சியினால் மழை தேவைப்பட்ட நிலையில் இருந்த அவர்களுக்கு அது மிகுந்த மகிழ்ச்சியைத் தந்தது. அப்போது அல்லாஹ் கூறினான்:\n\r\n\n\r\nبَلْ هُوَ مَا اسْتَعْجَلْتُم بِهِ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ\n\r\n\n\r\n(அப்படியல்ல! இது நீங்கள் எதை அவசரப்படுத்தக் கோரினீர்களோ அதுவேயாகும்; இது ஒரு காற்றாகும், இதில் வலிமிகுந்த வேதனை உள்ளது!) அதாவது, \"நீர் உண்மையாளராக இருந்தால் நீர் வாக்களித்த வேதனையைக் கொண்டு வாரும்\" என்று நீங்கள் கேட்ட வேதனை இதுவே.\n\r\n\n\r\nتُدَمِّرُ كُلَّ شَىْءٍ\n\r\n\n\r\n(அது ஒவ்வொன்றையும் அழித்துவிடும்) அதாவது, பொதுவாக எவையெல்லாம் அழியுமோ அத்தகைய அவர்களின் நிலப்பரப்பின் ஒவ்வொரு பகுதியையும் அது அழித்தது.\n\r\n\n\r\nبِأَمْرِ رَبِّهَا\n\r\n\n\r\n(அதன் இறைவனுடைய கட்டளையால்!) அதாவது, அதைச் செய்வதற்கு அதற்கு அல்லாஹ்வின் அனுமதி இருந்தது. இது அல்லாஹ்வின் இந்தக் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nمَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلاَّ جَعَلَتْهُ كَالرَّمِيمِ\n\r\n\n\r\n(அது சென்றடைந்த எதையும் விட்டுவைக்கவில்லை; மாறாக அதனை உக்கிப்போன சிதைவுகளைப் போல ஆக்கிவிட்டது.) (51:42). இதன் காரணமாகவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَأْصْبَحُواْ لاَ يُرَى إِلاَّ مَسَـكِنُهُمْ\n\r\n\n\r\n(எனவே, அவர்களின் குடியிருப்புகளைத் தவிர வேறெதுவும் காணப்படாத நிலைக்கு அவர்கள் ஆளானார்கள்!) அதாவது, அவர்கள் அனைவரும் அழிக்கப்பட்டார்கள்; அவர்களில் எவரும் தப்பவில்லை. பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَذلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ\n\r\n\n\r\n(இவ்வாறே நாம் குற்றவாளி சமூகத்திற்குத் தண்டனை வழங்குகிறோம்!) அதாவது, நமது தூதர்களை நிராகரித்து, நமது கட்டளைகளுக்கு மாறுசெய்பவர்கள் குறித்து நமது தீர்ப்பு இதுவேயாகும். இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் உள்நாக்குத் தெரியும்படி வாய்விட்டுச் சிரிப்பதை நான் ஒருபோதும் பார்த்ததில்லை; அவர்கள் புன்னகைப்பவர்களாகவே இருந்தார்கள்.\" மேகங்களையோ காற்றையோ காணும்போது நபியவர்களின் முகத்தில் ஒருவிதக் கலக்கம் தெரியும் என்று ஆயிஷா (ரழி) கூறினார்கள். இது குறித்து அவர்கள் நபியவர்களிடம், \"அல்லாஹ்வின் தூதரே! மக்கள் மேகங்களைக் காணும்போது அது மழையைக் கொண்டுவரும் என்று மகிழ்ச்சியடைகிறார்கள். ஆனால் நீங்கள் அவற்றைக் காணும்போது உங்கள் முகத்தில் அதிருப்தி தோன்றுவதை நான் கவனிக்கிறேனே?\" என்று கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n«يَا عَائِشَةُ، مَا يُؤْمِنُنِي أَنْ يَكُونَ فِيهِ عَذَابٌ، قَدْ عُذِّبَ قَوْمٌ بِالرِّيحِ، وَقَدْ رَأَى قَوْمٌ الْعَذَابَ وَقَالُوا: هذَا عَارِضٌ مُمْطِرُنَا»\n\r\n\n\r\n(ஆயிஷாவே! அந்த மேகத்தில் வேதனை இருக்காது என்பதற்கு எனக்கு என்ன நிச்சயம்? சில சமூகங்கள் காற்றினால் தண்டிக்கப்பட்டுள்ளன. தண்டனை தங்களை நோக்கி வருவதைக் கண்ட ஒரு சமூகம், 'இது எங்களுக்கு மழையைத் தரும் மேகம்' என்றுதான் கூறியது.) இது புகாரி மற்றும் முஸ்லிமிலும் பதிவு செய்யப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் அறிவிக்கிறார்கள், ஆயிஷா (ரழி) கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அடிவானத்தில் மேகங்களைக் கண்டால், தாம் எதில் ஈடுபட்டிருந்தாலும் - தொழுகையில் இருந்தாலும் கூட - அதை விட்டுவிட்டு இவ்வாறு பிரார்த்திப்பார்கள்:\n\r\n\n\r\n«اللْهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا فِيه»\n\r\n\n\r\n(அல்லாஹ்வே! இதில் உள்ள தீங்கிலிருந்து உன்னிடம் நான் பாதுகாப்புத் தேடுகிறேன்.) அல்லாஹ் அந்த மேகங்களை அகற்றிவிட்டால் நபியவர்கள் அல்லாஹ்வைப் புகழ்வார்கள்; மழை பொழிந்தால்,\n\r\n\n\r\n«اللْهُمَّ صَيِّبًا نَافِعًا»\n\r\n\n\r\n(அல்லாஹ்வே! இதனைப் பயனுள்ள மழையாக ஆக்குவாயாக) என்று கூறுவார்கள்.\n\r\n\n\r\nமுஸ்லிம் அவர்களும் தமது ஸஹீஹில் ஆயிஷா (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: காற்று வீசும்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவார்கள்:\n\r\n\n\r\n«اللْهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ،وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ»\n\r\n\n\r\n(அல்லாஹ்வே! நான் உன்னிடம் இதன் நன்மையையும், இதில் உள்ள நன்மையையும், இது எதனுடன் அனுப்பப்பட்டதோ அந்த நன்மையையும் வேண்டுகிறேன். மேலும் இதன் தீங்கிலிருந்தும், இதில் உள்ள தீங்கிலிருந்தும், இது எதனுடன் அனுப்பப்பட்டதோ அந்தத் தீங்கிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.) வானம் மேகமூட்டமாக மாறினால் நபியவர்களின் முகம் மாறிவிடும்; அவர்கள் பதற்றத்துடன் உள்ளேயும் வெளியேயும் சென்று வருவார்கள். மழை பெய்துவிட்டால் அவர்களின் கவலை தணிந்துவிடும். ஆயிஷா (ரழி) அவர்கள் இதைக் கவனித்து நபியவர்களிடம் கேட்டபோது அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَعَلَّهُ يَا عَائِشَةُ كَمَا قَالَ قَوْمُ عَادٍ:\n\r\n\n\r\nفَلَمَّا رَأَوْهُ عَارِضاً مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُواْ هَـذَا عَارِضٌ مُّمْطِرُنَا»\n\r\n\n\r\n(ஆயிஷாவே! இது ஆத் கூட்டத்தினர் கூறியது போலவும் இருக்கலாம்: \"பின்னர், அது தங்களின் பள்ளத்தாக்குகளை நோக்கி வரும் ஒரு அடர்ந்த மேகமாக அவர்கள் கண்டபோது: 'இது எங்களுக்கு மழை பொழியும் மேகம்' என்று கூறினார்கள்.\") ஆத் கூட்டத்தினரின் அழிவு பற்றிய வரலாற்றை நாம் ஏற்கனவே சூரா அல்-அஃராஃப் மற்றும் சூரா ஹூத் ஆகிய அத்தியாயங்களில் விளக்கியுள்ளோம். எனவே, அதனை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=28\" class=\"link\">46:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=28\" class=\"link\">46:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:28 ஐ பார்க்கவும்"},"28":{"html":"<span class=\"quran-arabic-font text-success\">﴾وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعاً</span> <span class=\"quran-arabic-font text-success\">وَأَبْصَاراً</span> <span class=\"quran-arabic-font text-success\">وَأَفْئِدَةً</span> <span class=\"quran-arabic-font text-success\">فَمَآ</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">سَمْعُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَفْئِدَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُونَ</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحَاقَ</span> <span class=\"quran-arabic-font text-success\">بِهِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِئُونَ﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அவர்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இதயங்களையும் வழங்கியிருந்தோம். ஆனால் அவர்கள் அல்லாஹ்வின் அத்தாட்சிகளை மறுத்துக்கொண்டிருந்தபோது, அவர்களுடைய செவியோ, பார்வைகளோ அல்லது இதயங்களோ அவர்களுக்கு எவ்விதப் பலனும் அளிக்கவில்லை. மேலும், அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ, அதுவே அவர்களைச் சூழ்ந்துகொண்டது!) அதாவது, அவர்கள் எதனை மறுத்தார்களோ மற்றும் எதன் வருகையைச் சந்தேகித்தார்களோ, அந்த வேதனையாலும் படிப்பினை மிக்க தண்டனையாலும் அவர்கள் சூழப்பட்டார்கள். இதன் பொருள்: இதைக் கேட்பவர்களே, அவர்களைப் போன்ற ஒரு தண்டனை இம்மையிலும் மறுமையிலும் உங்களைத் தாக்கிவிடாதவாறு நீங்கள் அவர்களைப் போல் ஆவதிலிருந்து எச்சரிக்கையாக இருக்க வேண்டும்.<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حَوْلَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى﴿</span><br />\r\n<br />\r\n(நிச்சயமாக உங்களைச் சுற்றியுள்ள ஊர்களை நாம் அழித்துவிட்டோம்.) இது மக்காவாசிகளுக்குக் கூறப்படும் உரையாகும். மக்காவைச் சுற்றியிருந்த பகுதிகளில் வாழ்ந்து, தூதர்களை நிராகரித்த சமுதாயங்களை அல்லாஹ் அழித்தான். உதாரணமாக: யமன் நாட்டிற்கு அருகிலுள்ள ஹள்ரமவ்தில் ‘அல்-அஹ்காஃப்’ பகுதியில் வாழ்ந்த ‘ஆது’ கூட்டத்தினர்; மக்காவிற்கும் அஷ்-ஷாம் (பெரிய சிரியா) பகுதிக்கும் இடையே குடியிருப்புகளைக் கொண்டிருந்த ‘ஸமூது’ கூட்டத்தினர்; யமன் தேசத்து ‘ஸபா’ மக்கள்; காஸா (மேற்கு பாலஸ்தீனம்) செல்லும் பாதையில் வாழ்ந்த ‘மத்யன்’ மக்கள்; மற்றும் அவர்கள் (ஜோர்டான் செல்லும் வழியில்) கடந்து செல்லக்கூடிய ஏரிக்கரையில் (சவக்கடல்) வாழ்ந்த லூத் (அலை) அவர்களின் சமூகத்தினர்.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَصَرَّفْنَا</span> <span class=\"quran-arabic-font text-success\">الْآيَاتِ﴿</span><br />\r\n<br />\r\n(மேலும் நாம் அத்தாட்சிகளைப் பல்வேறு கோணங்களில் விவரித்தோம்.) அதாவது, \"நாம் அவற்றை விளக்கித் தெளிவுபடுத்தினோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ</span> <span class=\"quran-arabic-font text-success\">فَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نَصَرَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">قُرْبَاناً</span> <span class=\"quran-arabic-font text-success\">آلِهَةً﴿</span><br />\r\n<br />\r\n(அவர்கள் நேர்வழிக்கு மீளும் பொருட்டு. அல்லாஹ்வையன்றி, அவனை நெருங்குவதற்கான ஒரு வழியாக அவர்கள் எவற்றைத் தெய்வங்களாக எடுத்துக்கொண்டார்களோ, அவை அவர்களுக்கு உதவியிருக்க வேண்டாமா?) அதாவது, இவர்களுக்கு உதவி மிகவும் தேவைப்பட்ட நேரத்தில் அவை இவர்களுக்கு ஏன் உதவவில்லை?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">ضَلُّواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ﴿</span><br />\r\n<br />\r\n(மாறாக, அவை இவர்களை விட்டு மறைந்துவிட்டன.) இன்னும் சொல்லப்போனால், இவர்களுக்கு உதவி மிக அவசியமாகத் தேவைப்பட்ட போது, அவை இவர்களைக் கைவிட்டுவிட்டன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">إِفْكُهُمْ﴿</span><br />\r\n<br />\r\n(அதுவே அவர்களின் பொய்யாகும்.) அதாவது, அவர்களின் அப்பட்டமான பொய்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَفْتَرُونَ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் இட்டுக்கட்டிக்கொண்டிருந்தவை ஆகும்.) இதன் பொருள், அவர்கள் இவற்றைத் தெய்வங்களாகக் கருதி பொய்களை இட்டுக்கட்டினார்கள். அவற்றை வணங்கியதாலும், அவற்றின் மீது நம்பிக்கை வைத்ததாலும் அவர்கள் நஷ்டமடைந்து தோல்வியுற்றார்கள் - அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"﴾وَجَعَلْنَا لَهُمْ سَمْعاً وَأَبْصَاراً وَأَفْئِدَةً فَمَآ أَغْنَى عَنْهُمْ سَمْعُهُمْ وَلاَ أَبْصَارُهُمْ وَلاَ أَفْئِدَتُهُمْ مِّن شَيْءٍ إِذْ كَانُواْ يَجْحَدُونَ بِآيَاتِ اللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِ يَسْتَهْزِئُونَ﴿\n\r\n\n\r\n(மேலும் நாம் அவர்களுக்குச் செவிப்புலனையும், பார்வைகளையும், இதயங்களையும் வழங்கியிருந்தோம். ஆனால் அவர்கள் அல்லாஹ்வின் அத்தாட்சிகளை மறுத்துக்கொண்டிருந்தபோது, அவர்களுடைய செவியோ, பார்வைகளோ அல்லது இதயங்களோ அவர்களுக்கு எவ்விதப் பலனும் அளிக்கவில்லை. மேலும், அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ, அதுவே அவர்களைச் சூழ்ந்துகொண்டது!) அதாவது, அவர்கள் எதனை மறுத்தார்களோ மற்றும் எதன் வருகையைச் சந்தேகித்தார்களோ, அந்த வேதனையாலும் படிப்பினை மிக்க தண்டனையாலும் அவர்கள் சூழப்பட்டார்கள். இதன் பொருள்: இதைக் கேட்பவர்களே, அவர்களைப் போன்ற ஒரு தண்டனை இம்மையிலும் மறுமையிலும் உங்களைத் தாக்கிவிடாதவாறு நீங்கள் அவர்களைப் போல் ஆவதிலிருந்து எச்சரிக்கையாக இருக்க வேண்டும்.\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்,\n\r\n﴾وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُمْ مِّنَ الْقُرَى﴿\n\r\n\n\r\n(நிச்சயமாக உங்களைச் சுற்றியுள்ள ஊர்களை நாம் அழித்துவிட்டோம்.) இது மக்காவாசிகளுக்குக் கூறப்படும் உரையாகும். மக்காவைச் சுற்றியிருந்த பகுதிகளில் வாழ்ந்து, தூதர்களை நிராகரித்த சமுதாயங்களை அல்லாஹ் அழித்தான். உதாரணமாக: யமன் நாட்டிற்கு அருகிலுள்ள ஹள்ரமவ்தில் ‘அல்-அஹ்காஃப்’ பகுதியில் வாழ்ந்த ‘ஆது’ கூட்டத்தினர்; மக்காவிற்கும் அஷ்-ஷாம் (பெரிய சிரியா) பகுதிக்கும் இடையே குடியிருப்புகளைக் கொண்டிருந்த ‘ஸமூது’ கூட்டத்தினர்; யமன் தேசத்து ‘ஸபா’ மக்கள்; காஸா (மேற்கு பாலஸ்தீனம்) செல்லும் பாதையில் வாழ்ந்த ‘மத்யன்’ மக்கள்; மற்றும் அவர்கள் (ஜோர்டான் செல்லும் வழியில்) கடந்து செல்லக்கூடிய ஏரிக்கரையில் (சவக்கடல்) வாழ்ந்த லூத் (அலை) அவர்களின் சமூகத்தினர்.\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்,\n\r\n﴾وَصَرَّفْنَا الْآيَاتِ﴿\n\r\n\n\r\n(மேலும் நாம் அத்தாட்சிகளைப் பல்வேறு கோணங்களில் விவரித்தோம்.) அதாவது, \"நாம் அவற்றை விளக்கித் தெளிவுபடுத்தினோம்.\"\n\r\n\n\r\n﴾لَعَلَّهُمْ يَرْجِعُونَ فَلَوْلاَ نَصَرَهُمُ الَّذِينَ اتَّخَذُواْ مِن دُونِ اللَّهِ قُرْبَاناً آلِهَةً﴿\n\r\n\n\r\n(அவர்கள் நேர்வழிக்கு மீளும் பொருட்டு. அல்லாஹ்வையன்றி, அவனை நெருங்குவதற்கான ஒரு வழியாக அவர்கள் எவற்றைத் தெய்வங்களாக எடுத்துக்கொண்டார்களோ, அவை அவர்களுக்கு உதவியிருக்க வேண்டாமா?) அதாவது, இவர்களுக்கு உதவி மிகவும் தேவைப்பட்ட நேரத்தில் அவை இவர்களுக்கு ஏன் உதவவில்லை?\n\r\n\n\r\n﴾بَلْ ضَلُّواْ عَنْهُمْ﴿\n\r\n\n\r\n(மாறாக, அவை இவர்களை விட்டு மறைந்துவிட்டன.) இன்னும் சொல்லப்போனால், இவர்களுக்கு உதவி மிக அவசியமாகத் தேவைப்பட்ட போது, அவை இவர்களைக் கைவிட்டுவிட்டன.\n\r\n\n\r\n﴾وَذَلِكَ إِفْكُهُمْ﴿\n\r\n\n\r\n(அதுவே அவர்களின் பொய்யாகும்.) அதாவது, அவர்களின் அப்பட்டமான பொய்.\n\r\n\n\r\n﴾وَمَا كَانُواْ يَفْتَرُونَ﴿\n\r\n\n\r\n(மேலும் அவர்கள் இட்டுக்கட்டிக்கொண்டிருந்தவை ஆகும்.) இதன் பொருள், அவர்கள் இவற்றைத் தெய்வங்களாகக் கருதி பொய்களை இட்டுக்கட்டினார்கள். அவற்றை வணங்கியதாலும், அவற்றின் மீது நம்பிக்கை வைத்ததாலும் அவர்கள் நஷ்டமடைந்து தோல்வியுற்றார்கள் - அல்லாஹ்வே மிக அறிந்தவன்."},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=32\" class=\"link\">46:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:32 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=32\" class=\"link\">46:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:32 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=32\" class=\"link\">46:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:32 ஐ பார்க்கவும்"},"32":{"html":"<strong>ஜின்ன்கள் திருக்குர்ஆனைச் செவியுற்ற வரலாறு</strong><br />\r\nஜின்ன்கள் திருக்குர்ஆனைச் செவியுற்ற வரலாறு<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அஸ்-ஸுபைர் (ரழி) அவர்கள் இந்த வசனத்திற்கு அளித்த விளக்கத்தைப் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">صَرَفْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">نَفَراً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَمِعُونَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span><br />\r\n<br />\r\n((நபியே! நினைவு கூர்வீராக!) ஜின்களில் ஒரு குழுவினர் குர்ஆனைச் செவியுறுவதற்காக உம்மிடம் நாம் திருப்பி விட்டோம்.) \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இஷா தொழுகையை நிறைவேற்றிக் கொண்டிருந்தபோது அவர்கள் 'நக்லா' எனும் இடத்தில் இருந்தனர். மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَادُواْ</span> <span class=\"quran-arabic-font text-success\">يَكُونُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">لِبَداً</span><br />\r\n<br />\r\n(அவர்கள் அவரைச் செவியுறுவதற்காக ஒருவர் மீது ஒருவர் நெருக்கமாகக் கூடிவிட்டனர்.) (<a href=\"qurandisp.php?sura=72&ayah=19\" class=\"link\">72:19</a>)\" சுஃப்யான் அவர்கள் கூறினார்கள், \"அடுக்கப்பட்ட கம்பளிப் போர்வையைப் போல அவர்கள் ஒருவர் மீது ஒருவராக நின்றார்கள்.\" இதனை இமாம் அஹ்மத் மட்டுமே தனியாகப் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் மற்றும் புகழ்பெற்ற இமாம் அல்-ஹாஃபிழ் அபூபக்ர் அல்-பைஹகீ ஆகிய இருவரும் தனது 'தலாஇலுன் நுபுவ்வா' எனும் நூலில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஜின்களுக்கு குர்ஆனை ஓதிக்காட்டவுமில்லை, அவர்களைப் பார்க்கவுமில்லை. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது தோழர்கள் சிலருடன் 'உக்காழ்' சந்தையை நோக்கிச் சென்றுகொண்டிருந்தார்கள். அக்காலத்தில் வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து ஷைத்தான்கள் தடுக்கப்பட்டிருந்தன. (அவர்கள் செய்தி கேட்க முயற்சிக்கும்போது) எரிகற்களால் தாக்கப்பட்டனர். ஷைத்தான்கள் தங்கள் சமூகத்தாரிடம் திரும்பியபோது, 'உங்களுக்கு என்ன நேர்ந்தது?' என்று வினவப்பட்டனர். அதற்கு அவர்கள், 'வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து நாங்கள் தடுக்கப்பட்டுவிட்டோம்; எரிகற்கள் எங்களைத் தாக்குகின்றன' என்று பதிலளித்தனர். அதற்கு அவர்களின் சமூகத்தார், 'வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து நீங்கள் தடுக்கப்பட்டிருப்பதற்கு ஏதோ ஒரு முக்கிய நிகழ்வுதான் காரணமாக இருக்க வேண்டும். எனவே, பூமியின் கிழக்கு மற்றும் மேற்கு திசைகள் எங்கும் சென்று, உங்களை வானுலகச் செய்திகளிலிருந்து தடுத்தது எது என்று பாருங்கள்' என்று கூறினர். அவ்வாறே அவர்கள் வானுலகச் செய்திகளைத் தடுத்த அந்த நிகழ்வைத் தேடிப் பூமியின் கிழக்கு மற்றும் மேற்கு திசைகளில் அலைந்தனர். அவர்களில் ஒரு குழுவினர் 'திஹாமா' பகுதியை நோக்கிச் சென்றபோது, உக்காழ் சந்தைக்குச் செல்லும் வழியில் 'நக்லா' எனும் இடத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருப்பதைக் கண்டனர். அப்போது அவர்கள் தமது தோழர்களுக்கு ஃபஜ்ர் தொழுகையைத் தலைமை தாங்கி நடத்திக் கொண்டிருந்தார்கள். அந்த ஜின்ன்கள் குர்ஆன் ஓதப்படுவதைச் செவியுற்றபோது, அதைக் கேட்பதற்காக அப்படியே நின்றனர். பின்னர், 'அல்லாஹ்வின் மீது சத்தியமாக! இதுதான் உங்களை வானுலகச் செய்திகளிலிருந்து தடுத்திருக்கிறது' என்று கூறினர். பிறகு தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்று, 'எங்கள் சமூகத்தாரே! நிச்சயமாக நாங்கள் ஓர் ஆச்சரியமான ஓதுதலை (குர்ஆனை) செவியுற்றோம். அது நேர்வழியைக் காட்டுகிறது. எனவே நாங்கள் அதனை ஈமான் கொண்டோம் (நம்பினோம்). இனி எங்கள் இறைவனுக்கு யாரையும் நாங்கள் இணையாகக் கருதமாட்டோம்' என்று கூறினர். எனவே அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்கு பின்வரும் வசனத்தை வஹீ (இறைச்செய்தி)யாக அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أُوحِىَ</span> <span class=\"quran-arabic-font text-success\">إِلَىَّ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">اسْتَمَعَ</span> <span class=\"quran-arabic-font text-success\">نَفَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span><br />\r\n<br />\r\n((நபியே!) நீர் கூறுவீராக: நிச்சயமாக ஜின்களில் ஒரு குழுவினர் (குர்ஆனைச்) செவியுற்றனர் என்று எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது.) (<a href=\"qurandisp.php?sura=72&ayah=1\" class=\"link\">72:1</a>) இவ்வாறு, ஜின்களின் கூற்று மட்டுமே அவருக்கு வஹீயாக அறிவிக்கப்பட்டது.\"<br />\r\n<br />\r\nஇமாம் புகாரி அவர்கள் இது போன்றதொரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள். இமாம் முஸ்லிம் அவர்களும் (இங்குள்ளவாறே) அதனைப் பதிவு செய்துள்ளார்கள். அத்-திர்மிதி மற்றும் அந்-நஸாஈ ஆகியோரும் தங்களது தஃப்ஸீர் நூல்களில் இதனைப் பதிவு செய்துள்ளார்கள். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"நபி (ஸல்) அவர்கள் நக்லா எனும் இடத்தில் குர்ஆன் ஓதிக் கொண்டிருந்தபோது ஜின்ன்கள் அங்கு வந்தனர். அவர்கள் நபி (ஸல்) அவர்கள் ஓதுவதைக் கேட்டபோது,\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَنصِتُواْ</span><br />\r\n<br />\r\n(அவர்கள்: \"அமைதியாகக் கேளுங்கள்\" என்று கூறினார்கள்.) அதாவது மெளனமாக இருங்கள்! அவர்கள் எண்ணிக்கையில் ஏழு அல்லது ஒன்பது பேர் இருந்தனர்; அவர்களில் ஒருவரது பெயர் 'ஸவ்பஆ'. எனவே அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">صَرَفْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">نَفَراً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَمِعُونَ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">حَضَرُوهُ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَنصِتُواْ</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">قُضِىَ</span> <span class=\"quran-arabic-font text-success\">وَلَّوْاْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِم</span> <span class=\"quran-arabic-font text-success\">مُّنذِرِينَ</span><br />\r\n<br />\r\n(மேலும், ஜின்களில் ஒரு குழுவினரை குர்ஆனைச் செவியுறுவதற்காக உம்மிடம் நாம் திருப்பிவிட்டபோது, அவர்கள் அங்கு வந்ததும் \"அமைதியாக இருங்கள்!\" என்று கூறினார்கள். (ஓதி) முடிக்கப்பட்டதும், அவர்கள் தங்கள் சமூகத்தாரிடம் அச்சமூட்டி எச்சரிக்கை செய்பவர்களாகத் திரும்பிச் சென்றார்கள்.) அவன் (அல்லாஹ்) கூறுவது வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ضَلَـلٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(தெளிவான வழிகேடு.)<br />\r\n<br />\r\nஎனவே, இந்த அறிவிப்பும் மேலே கூறப்பட்ட இப்னு அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பும், அந்த நேரத்தில் ஜின்ன்கள் வந்திருந்ததை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அறிந்திருக்கவில்லை என்பதைக் காட்டுகின்றன. அவர்கள் ஓதுதலைச் செவியுற்றுவிட்டுத் தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்றனர். அதற்குப் பிறகு, அவர்கள் அடுத்தடுத்துக் குழுக்களாக நபியவர்களிடம் வந்தனர்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَّوْاْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِم</span> <span class=\"quran-arabic-font text-success\">مُّنذِرِينَ</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் சமூகத்தாரிடம் அச்சமூட்டி எச்சரிக்கை செய்பவர்களாகத் திரும்பிச் சென்றார்கள்) என்பதன் பொருள்: அவர்கள் தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்று, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து எதைச் செவியுற்றார்களோ அதைக் கொண்டு அவர்களை எச்சரித்தனர் என்பதாகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّيَتَفَقَّهُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الدِّينِ</span> <span class=\"quran-arabic-font text-success\">وَلِيُنذِرُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">رَجَعُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَحْذَرُونَ</span><br />\r\n<br />\r\n(...அவர்கள் மார்க்கத்தில் ஆழ்ந்த ஞானத்தைப் பெற்று, தங்கள் சமூகத்தாரிடம் திரும்பிச் செல்லும்போது அவர்களை எச்சரிக்கை செய்வதற்காகவும், அதன் மூலம் அவர்கள் (தீமையிலிருந்து) தங்களை எச்சரிக்கையாகக் காத்துக்கொள்வதற்காகவும் (ஒரு பிரிவினர் புறப்பட வேண்டாமா?)) (<a href=\"qurandisp.php?sura=9&ayah=122\" class=\"link\">9:122</a>)<br />\r\n<br />\r\nஜின்களுக்கு அவர்களிலிருந்தே எச்சரிக்கை செய்பவர்கள் உண்டு, ஆனால் தூதர்கள் இல்லை என்பதற்கு இந்த வசனம் ஆதாரமாகப் பயன்படுத்தப்படுகிறது. நிச்சயமாக அல்லாஹ் ஜின்களிலிருந்து தூதர்களை அனுப்பவில்லை என்பதில் ஐயமில்லை. ஏனெனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رِجَالاً</span> <span class=\"quran-arabic-font text-success\">نُّوحِى</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span><br />\r\n<br />\r\n((நபியே!) உமக்கு முன்னரும் ஊர்வாசிகளில் ஆண்களையே தவிர (வேறெவரையும்) நாம் தூதர்களாக அனுப்பவில்லை; அவர்களுக்கு நாம் வஹீ (இறைச்செய்தி) அறிவித்தோம்.) (<a href=\"qurandisp.php?sura=12&ayah=109\" class=\"link\">12:109</a>)<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ</span> <span class=\"quran-arabic-font text-success\">وَيَمْشُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّسْوَاقِ</span><br />\r\n<br />\r\n((நபியே!) உமக்கு முன்னர் நாம் அனுப்பிய தூதர்கள் அனைவரும் நிச்சயமாக உணவு உண்பவர்களாகவும், கடைவீதிகளில் நடமாடுபவர்களாகவுமே இருந்தனர்.) (<a href=\"qurandisp.php?sura=25&ayah=20\" class=\"link\">25:20</a>)<br />\r\n<br />\r\nமேலும் இப்ராஹீம் அல்-கலீல் (அலை) அவர்களைப் பற்றிக் கூறும்போது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتِهِ</span> <span class=\"quran-arabic-font text-success\">النُّبُوَّةَ</span> <span class=\"quran-arabic-font text-success\">وَالْكِتَـبَ</span><br />\r\n<br />\r\n(...மேலும் நாம் அவரது சந்ததியினரில் நபித்துவத்தையும் வேதத்தையும் ஏற்படுத்தினோம்.) (<a href=\"qurandisp.php?sura=29&ayah=27\" class=\"link\">29:27</a>) எனவே, இப்ராஹீம் (அலை) அவர்களுக்குப் பிறகு அல்லாஹ் அனுப்பிய அனைத்து நபிமார்களும் அவரது சந்ததியினராகவே இருந்தனர்.<br />\r\n<br />\r\nஸூரத்துல் அன்ஆமில் வரும் அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـمَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الْجِنِّ</span> <span class=\"quran-arabic-font text-success\">وَالإِنْسِ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتِكُمْ</span> <span class=\"quran-arabic-font text-success\">رُسُلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span><br />\r\n<br />\r\n(ஜின் மற்றும் மனித சமூகத்தாரே! உங்களிலிருந்து தூதர்கள் உங்களிடம் வரவில்லையா?) (<a href=\"qurandisp.php?sura=6&ayah=130\" class=\"link\">6:130</a>) – இது ஜின் மற்றும் மனிதர் ஆகிய இரு பிரிவினரையும் சேர்த்துக் குறித்தாலும், குறிப்பாக இது மனிதர்களையே குறிக்கிறது. இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمَا</span> <span class=\"quran-arabic-font text-success\">الُّلؤْلُؤُ</span> <span class=\"quran-arabic-font text-success\">وَالمَرْجَانُ</span><br />\r\n<br />\r\n(அவ்விரண்டிலிருந்தும் (உப்பு மற்றும் நன்னீர்) முத்தும் பவளமும் வெளிவருகின்றன.) (<a href=\"qurandisp.php?sura=55&ayah=22\" class=\"link\">55:22</a>). அவன் \"அவ்விரண்டிலிருந்தும்\" என்று கூறினாலும், இது ஒரு வகை நீரிலிருந்து (உப்பு நீர்) மட்டுமே வெளிவருகிறது.<br />\r\n<br />\r\nஜின்ன்கள் தங்கள் சமூகத்தாரை எவ்வாறு எச்சரித்தார்கள் என்பதை அல்லாஹ் விளக்குகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">يقَوْمَنَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">سَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">كِتَـباً</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span><br />\r\n<br />\r\n(அவர்கள் கூறினர்: \"எங்கள் சமூகத்தாரே! நிச்சயமாக நாங்கள் மூஸாவுக்குப் பிறகு அருளப்பட்ட ஒரு வேதத்தைச் செவியுற்றோம்...\") அவர்கள் ஈஸா (அலை) அவர்களைக் குறிப்பிடவில்லை. ஏனெனில் ஈஸா (அலை) அவர்களுக்கு அருளப்பட்ட இன்ஜீல் வேதம் போதனைகளையும் அறிவுரைகளையும் மட்டுமே அதிகம் கொண்டிருந்தது; அதில் சட்டங்கள் மிகக் குறைவாகவே இருந்தன. எனவே, அது உண்மையில் தவ்ராத்தின் சட்டங்களுக்கு ஒரு நிறைவாகவே இருந்தது; தவ்ராத்தே அடிப்படையாக விளங்கியது. அதனால்தான் அவர்கள் \"மூஸாவுக்குப் பிறகு அருளப்பட்டது\" என்று கூறினர். நபி (ஸல்) அவர்கள் ஜிப்ரீல் - எனும் 'அந்-நாமூஸ்' (அலை) - உடனான முதல் சந்திப்பைப் பற்றி வரக்கா பின் நவ்ஃபலிடம் கூறியபோது அவரும் இவ்வாறே கூறினார்: \"மிக்க நன்று, மிக்க நன்று! இவர் தான் மூஸாவிடம் வந்து கொண்டிருந்தவர். (உமக்கு ஆதரவளிக்க) நான் ஒரு வாலிபனாக இருக்கக்கூடாதா என விரும்புகிறேன்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُصَدِّقاً</span> <span class=\"quran-arabic-font text-success\">لِّمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span><br />\r\n<br />\r\n(அது தனக்கு முன்னிருந்த வேதங்களை உண்மைப்படுத்துகிறது.) அதாவது தமக்கு முன்னால் முந்தைய நபிமார்களுக்கு அருளப்பட்ட வேதங்களை. பின்னர் அவர்கள் கூறினர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span><br />\r\n<br />\r\n(அது சத்தியத்திற்கு வழிகாட்டுகிறது.) அதாவது நம்பிக்கையிலும் செய்திகளிலும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِلَى</span> <span class=\"quran-arabic-font text-success\">طَرِيقٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span><br />\r\n<br />\r\n(மேலும் நேரான பாதைக்கும் (வழிகாட்டுகிறது).) அதாவது செயல்களில். ஏனெனில் குர்ஆன் செய்திகள் மற்றும் கட்டளைகள் என இரண்டு விஷயங்களைக் கொண்டுள்ளது. அதன் செய்திகள் உண்மையானவை; அதன் கட்டளைகள் அனைத்தும் நீதியானவை. அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَمَّتْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">صِدْقاً</span> <span class=\"quran-arabic-font text-success\">وَعَدْلاً</span><br />\r\n<br />\r\n(உமது இறைவனின் வார்த்தை உண்மையாலும் நீதியாலும் முழுமையடைந்துள்ளது.) (<a href=\"qurandisp.php?sura=6&ayah=115\" class=\"link\">6:115</a>).<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَرْسَلَ</span> <span class=\"quran-arabic-font text-success\">رَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">بِالْهُدَى</span> <span class=\"quran-arabic-font text-success\">وَدِينِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span><br />\r\n<br />\r\n(அவனே தனது தூதரை நேர்வழியுடனும் சத்திய மார்க்கத்துடனும் அனுப்பினான்.) (<a href=\"qurandisp.php?sura=9&ayah=33\" class=\"link\">9:33</a>). 'நேர்வழி' என்பது பயனுள்ள அறிவாகும்; 'சத்திய மார்க்கம்' என்பது நற்செயல்களாகும். எனவே ஜின்ன்கள் கூறினர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span><br />\r\n<br />\r\n(அது சத்தியத்திற்கு வழிகாட்டுகிறது.) அதாவது நம்பிக்கையில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِلَى</span> <span class=\"quran-arabic-font text-success\">طَرِيقٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span><br />\r\n<br />\r\n(மேலும் நேரான பாதைக்கும் (வழிகாட்டுகிறது).) அதாவது செயல்களில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يقَوْمَنَآ</span> <span class=\"quran-arabic-font text-success\">أَجِيبُواْ</span> <span class=\"quran-arabic-font text-success\">دَاعِىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(எங்கள் சமூகத்தாரே! அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளியுங்கள்.) இது முஹம்மது (ஸல்) அவர்கள் மனிதர்கள் மற்றும் ஜின்ன்கள் ஆகிய இரு பிரிவினருக்கும் தூதராக அனுப்பப்பட்டுள்ளார்கள் என்பதற்கு ஆதாரமாகும். எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَجِيبُواْ</span> <span class=\"quran-arabic-font text-success\">دَاعِىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَءَامِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளித்து அவரை ஈமான் கொள்ளுங்கள்.) பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذُنُوبِكُمْ</span><br />\r\n<br />\r\n(அவன் உங்கள் பாவங்களில் சிலவற்றை உங்களுக்கு மன்னிப்பான்.) சில அறிஞர்கள் இங்கு 'மின் துனூபிக்கும்' என்பதில் உள்ள 'மின்' என்பது மேலதிகமான (ஜாயிதா) சொல் எனக் கருதுகின்றனர். ஆனால் இது கேள்விக்குரியது; ஏனெனில் ஒரு நேர்மறையான கருத்தை உறுதிப்படுத்த இது அரிதாகவே பயன்படுத்தப்படுகிறது. மற்றவர்கள் இது பாவங்களின் ஒரு பகுதியை மன்னிப்பதைக் குறிக்கிறது எனக் கூறுகின்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُجِرْكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٍ</span><br />\r\n<br />\r\n(மேலும் நோவினை செய்யும் வேதனையிலிருந்து உங்களைப் பாதுகாப்பான்.) அதாவது அவனது துன்புறுத்தும் தண்டனையிலிருந்து உங்களைக் காப்பாற்றுவான். பிறகு அவர்கள் கூறியதாக அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُجِبْ</span> <span class=\"quran-arabic-font text-success\">دَاعِىَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">بِمُعْجِزٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضَ</span><br />\r\n<br />\r\n(எவர் அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளிக்கவில்லையோ, அவர் பூமியில் (அல்லாஹ்விடமிருந்து) தப்பித்துக் கொள்ள முடியாது.) அதாவது அல்லாஹ்வின் ஆற்றல் அவரைச் சூழ்ந்திருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآءُ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வையன்றி அவருக்குப் பாதுகாவலர்கள் எவரும் இருக்கமாட்டார்கள்.) அதாவது அல்லாஹ்விடமிருந்து எவரும் அவரைப் பாதுகாக்க முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ضَلَـلٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(அத்தகையோர் தெளிவான வழிகேட்டில் உள்ளனர்.) இது ஓர் அச்சுறுத்தலும் எச்சரிக்கையும் ஆகும். இவ்வாறாக அந்த ஜின்ன்கள் தங்கள் சமூகத்தாரை ஆர்வமூட்டியும் எச்சரித்தும் அழைப்பு விடுத்தனர். இதன் காரணமாகப் பல ஜின்ன்கள் செவிசாய்த்து அடுத்தடுத்துக் குழுக்களாக அல்லாஹ்வின் தூதரிடம் வந்தனர். அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"ஜின்ன்கள் திருக்குர்ஆனைச் செவியுற்ற வரலாறு\n\r\nஜின்ன்கள் திருக்குர்ஆனைச் செவியுற்ற வரலாறு\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அஸ்-ஸுபைர் (ரழி) அவர்கள் இந்த வசனத்திற்கு அளித்த விளக்கத்தைப் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\nوَإِذْ صَرَفْنَآ إِلَيْكَ نَفَراً مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْءَانَ\n\r\n\n\r\n((நபியே! நினைவு கூர்வீராக!) ஜின்களில் ஒரு குழுவினர் குர்ஆனைச் செவியுறுவதற்காக உம்மிடம் நாம் திருப்பி விட்டோம்.) \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இஷா தொழுகையை நிறைவேற்றிக் கொண்டிருந்தபோது அவர்கள் 'நக்லா' எனும் இடத்தில் இருந்தனர். மேலும்,\n\r\n\n\r\nكَادُواْ يَكُونُونَ عَلَيْهِ لِبَداً\n\r\n\n\r\n(அவர்கள் அவரைச் செவியுறுவதற்காக ஒருவர் மீது ஒருவர் நெருக்கமாகக் கூடிவிட்டனர்.) (72:19)\" சுஃப்யான் அவர்கள் கூறினார்கள், \"அடுக்கப்பட்ட கம்பளிப் போர்வையைப் போல அவர்கள் ஒருவர் மீது ஒருவராக நின்றார்கள்.\" இதனை இமாம் அஹ்மத் மட்டுமே தனியாகப் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் மற்றும் புகழ்பெற்ற இமாம் அல்-ஹாஃபிழ் அபூபக்ர் அல்-பைஹகீ ஆகிய இருவரும் தனது 'தலாஇலுன் நுபுவ்வா' எனும் நூலில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஜின்களுக்கு குர்ஆனை ஓதிக்காட்டவுமில்லை, அவர்களைப் பார்க்கவுமில்லை. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது தோழர்கள் சிலருடன் 'உக்காழ்' சந்தையை நோக்கிச் சென்றுகொண்டிருந்தார்கள். அக்காலத்தில் வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து ஷைத்தான்கள் தடுக்கப்பட்டிருந்தன. (அவர்கள் செய்தி கேட்க முயற்சிக்கும்போது) எரிகற்களால் தாக்கப்பட்டனர். ஷைத்தான்கள் தங்கள் சமூகத்தாரிடம் திரும்பியபோது, 'உங்களுக்கு என்ன நேர்ந்தது?' என்று வினவப்பட்டனர். அதற்கு அவர்கள், 'வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து நாங்கள் தடுக்கப்பட்டுவிட்டோம்; எரிகற்கள் எங்களைத் தாக்குகின்றன' என்று பதிலளித்தனர். அதற்கு அவர்களின் சமூகத்தார், 'வானுலகச் செய்திகளை ஒட்டுக் கேட்பதிலிருந்து நீங்கள் தடுக்கப்பட்டிருப்பதற்கு ஏதோ ஒரு முக்கிய நிகழ்வுதான் காரணமாக இருக்க வேண்டும். எனவே, பூமியின் கிழக்கு மற்றும் மேற்கு திசைகள் எங்கும் சென்று, உங்களை வானுலகச் செய்திகளிலிருந்து தடுத்தது எது என்று பாருங்கள்' என்று கூறினர். அவ்வாறே அவர்கள் வானுலகச் செய்திகளைத் தடுத்த அந்த நிகழ்வைத் தேடிப் பூமியின் கிழக்கு மற்றும் மேற்கு திசைகளில் அலைந்தனர். அவர்களில் ஒரு குழுவினர் 'திஹாமா' பகுதியை நோக்கிச் சென்றபோது, உக்காழ் சந்தைக்குச் செல்லும் வழியில் 'நக்லா' எனும் இடத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருப்பதைக் கண்டனர். அப்போது அவர்கள் தமது தோழர்களுக்கு ஃபஜ்ர் தொழுகையைத் தலைமை தாங்கி நடத்திக் கொண்டிருந்தார்கள். அந்த ஜின்ன்கள் குர்ஆன் ஓதப்படுவதைச் செவியுற்றபோது, அதைக் கேட்பதற்காக அப்படியே நின்றனர். பின்னர், 'அல்லாஹ்வின் மீது சத்தியமாக! இதுதான் உங்களை வானுலகச் செய்திகளிலிருந்து தடுத்திருக்கிறது' என்று கூறினர். பிறகு தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்று, 'எங்கள் சமூகத்தாரே! நிச்சயமாக நாங்கள் ஓர் ஆச்சரியமான ஓதுதலை (குர்ஆனை) செவியுற்றோம். அது நேர்வழியைக் காட்டுகிறது. எனவே நாங்கள் அதனை ஈமான் கொண்டோம் (நம்பினோம்). இனி எங்கள் இறைவனுக்கு யாரையும் நாங்கள் இணையாகக் கருதமாட்டோம்' என்று கூறினர். எனவே அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்கு பின்வரும் வசனத்தை வஹீ (இறைச்செய்தி)யாக அருளினான்:\n\r\n\n\r\nقُلْ أُوحِىَ إِلَىَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ\n\r\n\n\r\n((நபியே!) நீர் கூறுவீராக: நிச்சயமாக ஜின்களில் ஒரு குழுவினர் (குர்ஆனைச்) செவியுற்றனர் என்று எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது.) (72:1) இவ்வாறு, ஜின்களின் கூற்று மட்டுமே அவருக்கு வஹீயாக அறிவிக்கப்பட்டது.\"\n\r\n\n\r\nஇமாம் புகாரி அவர்கள் இது போன்றதொரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள். இமாம் முஸ்லிம் அவர்களும் (இங்குள்ளவாறே) அதனைப் பதிவு செய்துள்ளார்கள். அத்-திர்மிதி மற்றும் அந்-நஸாஈ ஆகியோரும் தங்களது தஃப்ஸீர் நூல்களில் இதனைப் பதிவு செய்துள்ளார்கள். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"நபி (ஸல்) அவர்கள் நக்லா எனும் இடத்தில் குர்ஆன் ஓதிக் கொண்டிருந்தபோது ஜின்ன்கள் அங்கு வந்தனர். அவர்கள் நபி (ஸல்) அவர்கள் ஓதுவதைக் கேட்டபோது,\"\n\r\n\n\r\nقَالُواْ أَنصِتُواْ\n\r\n\n\r\n(அவர்கள்: \"அமைதியாகக் கேளுங்கள்\" என்று கூறினார்கள்.) அதாவது மெளனமாக இருங்கள்! அவர்கள் எண்ணிக்கையில் ஏழு அல்லது ஒன்பது பேர் இருந்தனர்; அவர்களில் ஒருவரது பெயர் 'ஸவ்பஆ'. எனவே அல்லாஹ் அருளினான்:\n\r\n\n\r\nوَإِذْ صَرَفْنَآ إِلَيْكَ نَفَراً مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُواْ أَنصِتُواْ فَلَمَّا قُضِىَ وَلَّوْاْ إِلَى قَوْمِهِم مُّنذِرِينَ\n\r\n\n\r\n(மேலும், ஜின்களில் ஒரு குழுவினரை குர்ஆனைச் செவியுறுவதற்காக உம்மிடம் நாம் திருப்பிவிட்டபோது, அவர்கள் அங்கு வந்ததும் \"அமைதியாக இருங்கள்!\" என்று கூறினார்கள். (ஓதி) முடிக்கப்பட்டதும், அவர்கள் தங்கள் சமூகத்தாரிடம் அச்சமூட்டி எச்சரிக்கை செய்பவர்களாகத் திரும்பிச் சென்றார்கள்.) அவன் (அல்லாஹ்) கூறுவது வரை:\n\r\n\n\r\nضَلَـلٍ مُّبِينٍ\n\r\n\n\r\n(தெளிவான வழிகேடு.)\n\r\n\n\r\nஎனவே, இந்த அறிவிப்பும் மேலே கூறப்பட்ட இப்னு அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பும், அந்த நேரத்தில் ஜின்ன்கள் வந்திருந்ததை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அறிந்திருக்கவில்லை என்பதைக் காட்டுகின்றன. அவர்கள் ஓதுதலைச் செவியுற்றுவிட்டுத் தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்றனர். அதற்குப் பிறகு, அவர்கள் அடுத்தடுத்துக் குழுக்களாக நபியவர்களிடம் வந்தனர்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nوَلَّوْاْ إِلَى قَوْمِهِم مُّنذِرِينَ\n\r\n\n\r\n(அவர்கள் தங்கள் சமூகத்தாரிடம் அச்சமூட்டி எச்சரிக்கை செய்பவர்களாகத் திரும்பிச் சென்றார்கள்) என்பதன் பொருள்: அவர்கள் தங்கள் சமூகத்தாரிடம் திரும்பிச் சென்று, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து எதைச் செவியுற்றார்களோ அதைக் கொண்டு அவர்களை எச்சரித்தனர் என்பதாகும். இது அல்லாஹ்வின் இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nلِّيَتَفَقَّهُواْ فِى الدِّينِ وَلِيُنذِرُواْ قَوْمَهُمْ إِذَا رَجَعُواْ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ\n\r\n\n\r\n(...அவர்கள் மார்க்கத்தில் ஆழ்ந்த ஞானத்தைப் பெற்று, தங்கள் சமூகத்தாரிடம் திரும்பிச் செல்லும்போது அவர்களை எச்சரிக்கை செய்வதற்காகவும், அதன் மூலம் அவர்கள் (தீமையிலிருந்து) தங்களை எச்சரிக்கையாகக் காத்துக்கொள்வதற்காகவும் (ஒரு பிரிவினர் புறப்பட வேண்டாமா?)) (9:122)\n\r\n\n\r\nஜின்களுக்கு அவர்களிலிருந்தே எச்சரிக்கை செய்பவர்கள் உண்டு, ஆனால் தூதர்கள் இல்லை என்பதற்கு இந்த வசனம் ஆதாரமாகப் பயன்படுத்தப்படுகிறது. நிச்சயமாக அல்லாஹ் ஜின்களிலிருந்து தூதர்களை அனுப்பவில்லை என்பதில் ஐயமில்லை. ஏனெனில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلاَّ رِجَالاً نُّوحِى إِلَيْهِمْ مِّنْ أَهْلِ الْقُرَى\n\r\n\n\r\n((நபியே!) உமக்கு முன்னரும் ஊர்வாசிகளில் ஆண்களையே தவிர (வேறெவரையும்) நாம் தூதர்களாக அனுப்பவில்லை; அவர்களுக்கு நாம் வஹீ (இறைச்செய்தி) அறிவித்தோம்.) (12:109)\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ الْمُرْسَلِينَ إِلاَّ إِنَّهُمْ لَيَأْكُلُونَ الطَّعَامَ وَيَمْشُونَ فِى الاٌّسْوَاقِ\n\r\n\n\r\n((நபியே!) உமக்கு முன்னர் நாம் அனுப்பிய தூதர்கள் அனைவரும் நிச்சயமாக உணவு உண்பவர்களாகவும், கடைவீதிகளில் நடமாடுபவர்களாகவுமே இருந்தனர்.) (25:20)\n\r\n\n\r\nமேலும் இப்ராஹீம் அல்-கலீல் (அலை) அவர்களைப் பற்றிக் கூறும்போது:\n\r\n\n\r\nوَجَعَلْنَا فِى ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَـبَ\n\r\n\n\r\n(...மேலும் நாம் அவரது சந்ததியினரில் நபித்துவத்தையும் வேதத்தையும் ஏற்படுத்தினோம்.) (29:27) எனவே, இப்ராஹீம் (அலை) அவர்களுக்குப் பிறகு அல்லாஹ் அனுப்பிய அனைத்து நபிமார்களும் அவரது சந்ததியினராகவே இருந்தனர்.\n\r\n\n\r\nஸூரத்துல் அன்ஆமில் வரும் அல்லாஹ்வின் வசனத்தைப் பொறுத்தவரை:\n\r\n\n\r\nيَـمَعْشَرَ الْجِنِّ وَالإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنْكُمْ\n\r\n\n\r\n(ஜின் மற்றும் மனித சமூகத்தாரே! உங்களிலிருந்து தூதர்கள் உங்களிடம் வரவில்லையா?) (6:130) – இது ஜின் மற்றும் மனிதர் ஆகிய இரு பிரிவினரையும் சேர்த்துக் குறித்தாலும், குறிப்பாக இது மனிதர்களையே குறிக்கிறது. இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَخْرُجُ مِنْهُمَا الُّلؤْلُؤُ وَالمَرْجَانُ\n\r\n\n\r\n(அவ்விரண்டிலிருந்தும் (உப்பு மற்றும் நன்னீர்) முத்தும் பவளமும் வெளிவருகின்றன.) (55:22). அவன் \"அவ்விரண்டிலிருந்தும்\" என்று கூறினாலும், இது ஒரு வகை நீரிலிருந்து (உப்பு நீர்) மட்டுமே வெளிவருகிறது.\n\r\n\n\r\nஜின்ன்கள் தங்கள் சமூகத்தாரை எவ்வாறு எச்சரித்தார்கள் என்பதை அல்லாஹ் விளக்குகிறான்:\n\r\n\n\r\nقَالُواْ يقَوْمَنَآ إِنَّا سَمِعْنَا كِتَـباً أُنزِلَ مِن بَعْدِ مُوسَى\n\r\n\n\r\n(அவர்கள் கூறினர்: \"எங்கள் சமூகத்தாரே! நிச்சயமாக நாங்கள் மூஸாவுக்குப் பிறகு அருளப்பட்ட ஒரு வேதத்தைச் செவியுற்றோம்...\") அவர்கள் ஈஸா (அலை) அவர்களைக் குறிப்பிடவில்லை. ஏனெனில் ஈஸா (அலை) அவர்களுக்கு அருளப்பட்ட இன்ஜீல் வேதம் போதனைகளையும் அறிவுரைகளையும் மட்டுமே அதிகம் கொண்டிருந்தது; அதில் சட்டங்கள் மிகக் குறைவாகவே இருந்தன. எனவே, அது உண்மையில் தவ்ராத்தின் சட்டங்களுக்கு ஒரு நிறைவாகவே இருந்தது; தவ்ராத்தே அடிப்படையாக விளங்கியது. அதனால்தான் அவர்கள் \"மூஸாவுக்குப் பிறகு அருளப்பட்டது\" என்று கூறினர். நபி (ஸல்) அவர்கள் ஜிப்ரீல் - எனும் 'அந்-நாமூஸ்' (அலை) - உடனான முதல் சந்திப்பைப் பற்றி வரக்கா பின் நவ்ஃபலிடம் கூறியபோது அவரும் இவ்வாறே கூறினார்: \"மிக்க நன்று, மிக்க நன்று! இவர் தான் மூஸாவிடம் வந்து கொண்டிருந்தவர். (உமக்கு ஆதரவளிக்க) நான் ஒரு வாலிபனாக இருக்கக்கூடாதா என விரும்புகிறேன்.\"\n\r\n\n\r\nمُصَدِّقاً لِّمَا بَيْنَ يَدَيْهِ\n\r\n\n\r\n(அது தனக்கு முன்னிருந்த வேதங்களை உண்மைப்படுத்துகிறது.) அதாவது தமக்கு முன்னால் முந்தைய நபிமார்களுக்கு அருளப்பட்ட வேதங்களை. பின்னர் அவர்கள் கூறினர்:\n\r\n\n\r\nيَهْدِى إِلَى الْحَقِّ\n\r\n\n\r\n(அது சத்தியத்திற்கு வழிகாட்டுகிறது.) அதாவது நம்பிக்கையிலும் செய்திகளிலும்.\n\r\n\n\r\nوَإِلَى طَرِيقٍ مُّسْتَقِيمٍ\n\r\n\n\r\n(மேலும் நேரான பாதைக்கும் (வழிகாட்டுகிறது).) அதாவது செயல்களில். ஏனெனில் குர்ஆன் செய்திகள் மற்றும் கட்டளைகள் என இரண்டு விஷயங்களைக் கொண்டுள்ளது. அதன் செய்திகள் உண்மையானவை; அதன் கட்டளைகள் அனைத்தும் நீதியானவை. அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَتَمَّتْ كَلِمَةُ رَبِّكَ صِدْقاً وَعَدْلاً\n\r\n\n\r\n(உமது இறைவனின் வார்த்தை உண்மையாலும் நீதியாலும் முழுமையடைந்துள்ளது.) (6:115).\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nهُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ\n\r\n\n\r\n(அவனே தனது தூதரை நேர்வழியுடனும் சத்திய மார்க்கத்துடனும் அனுப்பினான்.) (9:33). 'நேர்வழி' என்பது பயனுள்ள அறிவாகும்; 'சத்திய மார்க்கம்' என்பது நற்செயல்களாகும். எனவே ஜின்ன்கள் கூறினர்:\n\r\n\n\r\nيَهْدِى إِلَى الْحَقِّ\n\r\n\n\r\n(அது சத்தியத்திற்கு வழிகாட்டுகிறது.) அதாவது நம்பிக்கையில்.\n\r\n\n\r\nوَإِلَى طَرِيقٍ مُّسْتَقِيمٍ\n\r\n\n\r\n(மேலும் நேரான பாதைக்கும் (வழிகாட்டுகிறது).) அதாவது செயல்களில்.\n\r\n\n\r\nيقَوْمَنَآ أَجِيبُواْ دَاعِىَ اللَّهِ\n\r\n\n\r\n(எங்கள் சமூகத்தாரே! அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளியுங்கள்.) இது முஹம்மது (ஸல்) அவர்கள் மனிதர்கள் மற்றும் ஜின்ன்கள் ஆகிய இரு பிரிவினருக்கும் தூதராக அனுப்பப்பட்டுள்ளார்கள் என்பதற்கு ஆதாரமாகும். எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَجِيبُواْ دَاعِىَ اللَّهِ وَءَامِنُواْ بِهِ\n\r\n\n\r\n(அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளித்து அவரை ஈமான் கொள்ளுங்கள்.) பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَغْفِرْ لَكُمْ مِّن ذُنُوبِكُمْ\n\r\n\n\r\n(அவன் உங்கள் பாவங்களில் சிலவற்றை உங்களுக்கு மன்னிப்பான்.) சில அறிஞர்கள் இங்கு 'மின் துனூபிக்கும்' என்பதில் உள்ள 'மின்' என்பது மேலதிகமான (ஜாயிதா) சொல் எனக் கருதுகின்றனர். ஆனால் இது கேள்விக்குரியது; ஏனெனில் ஒரு நேர்மறையான கருத்தை உறுதிப்படுத்த இது அரிதாகவே பயன்படுத்தப்படுகிறது. மற்றவர்கள் இது பாவங்களின் ஒரு பகுதியை மன்னிப்பதைக் குறிக்கிறது எனக் கூறுகின்றனர்.\n\r\n\n\r\nوَيُجِرْكُمْ مِّنْ عَذَابٍ أَلِيمٍ\n\r\n\n\r\n(மேலும் நோவினை செய்யும் வேதனையிலிருந்து உங்களைப் பாதுகாப்பான்.) அதாவது அவனது துன்புறுத்தும் தண்டனையிலிருந்து உங்களைக் காப்பாற்றுவான். பிறகு அவர்கள் கூறியதாக அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَن لاَّ يُجِبْ دَاعِىَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى الاٌّرْضَ\n\r\n\n\r\n(எவர் அல்லாஹ்வின் அழைப்பாளருக்குப் பதிலளிக்கவில்லையோ, அவர் பூமியில் (அல்லாஹ்விடமிருந்து) தப்பித்துக் கொள்ள முடியாது.) அதாவது அல்லாஹ்வின் ஆற்றல் அவரைச் சூழ்ந்திருக்கும்.\n\r\n\n\r\nوَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَآءُ\n\r\n\n\r\n(மேலும் அல்லாஹ்வையன்றி அவருக்குப் பாதுகாவலர்கள் எவரும் இருக்கமாட்டார்கள்.) அதாவது அல்லாஹ்விடமிருந்து எவரும் அவரைப் பாதுகாக்க முடியாது.\n\r\n\n\r\nأُوْلَـئِكَ فِى ضَلَـلٍ مُّبِينٍ\n\r\n\n\r\n(அத்தகையோர் தெளிவான வழிகேட்டில் உள்ளனர்.) இது ஓர் அச்சுறுத்தலும் எச்சரிக்கையும் ஆகும். இவ்வாறாக அந்த ஜின்ன்கள் தங்கள் சமூகத்தாரை ஆர்வமூட்டியும் எச்சரித்தும் அழைப்பு விடுத்தனர். இதன் காரணமாகப் பல ஜின்ன்கள் செவிசாய்த்து அடுத்தடுத்துக் குழுக்களாக அல்லாஹ்வின் தூதரிடம் வந்தனர். அனைத்துப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அல்லாஹ்வே மிக அறிந்தவன்."},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=35\" class=\"link\">46:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:35 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=46&ayah=35\" class=\"link\">46:35</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 46:35 ஐ பார்க்கவும்"},"35":{"html":"<strong>நபியவர்களைப் பொறுமையுடன் இருக்குமாறு ஏவுதல்</strong><br />\r\n<br />\r\nபின்னர், அல்லாஹ் தனது தூதரை (ஸல்), அவரது மக்களில் அவரை நிராகரித்தவர்களிடம் பொறுமையைக் கடைப்பிடிக்குமாறு ஏவுகிறான். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرَ</span> <span class=\"quran-arabic-font text-success\">أُوْلُواْ</span> <span class=\"quran-arabic-font text-success\">الْعَزْمِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلِ</span><br />\r\n<br />\r\n(ஆகவே, தூதர்களில் உறுதிமிக்கவர்கள் பொறுமையாக இருந்ததுபோல நீரும் பொறுமையாக இருப்பீராக.) அதாவது, அவர்கள் தம் மக்கள் தங்களை நிராகரித்தபோது எவ்வாறு பொறுமையாக இருந்தார்களோ, அதுபோல. தூதர்களில் \"உறுதிமிக்கவர்கள்\" (உலுல் அஸ்ம்) என்போர் நூஹ் (அலை), இப்ராஹீம் (அலை), மூஸா (அலை), ஈஸா (அலை) மற்றும் அனைத்து நபிமார்களுக்கும் இறுதியானவரான முஹம்மது (ஸல்) ஆகியோராவார்கள். அல்லாஹ் இவர்களுடைய பெயர்களை சூரா அல்-அஹ்ஸாப் (<a href=\"qurandisp.php?sura=33&ayah=7\" class=\"link\">33:7</a>) மற்றும் சூரா அஷ்-ஷூரா (<a href=\"qurandisp.php?sura=42&ayah=13\" class=\"link\">42:13</a>) ஆகிய இரு வசனங்களில் குறிப்பாகக் குறிப்பிட்டுள்ளான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَعْجِل</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span><br />\r\n<br />\r\n(மேலும், அவர்களுக்காக நீர் அவசரப்படாதீர்.) அதாவது, 'அவர்களுக்கான தண்டனையை வரவழைப்பதில் அவசரப்படாதீர்.' இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَذَرْنِى</span> <span class=\"quran-arabic-font text-success\">وَالْمُكَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">النَّعْمَةِ</span> <span class=\"quran-arabic-font text-success\">وَمَهِّلْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span><br />\r\n<br />\r\n(மேலும், நிராகரிப்பவர்களையும், சுகபோகங்களை உடையவர்களையும் என்னிடம் விட்டுவிடுவீராக; அவர்களுக்குச் சிறிது அவகாசம் அளிப்பீராக.) (<a href=\"qurandisp.php?sura=73&ayah=11\" class=\"link\">73:11</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَهِّلِ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">أَمْهِلْهُمْ</span> <span class=\"quran-arabic-font text-success\">رُوَيْداً</span><br />\r\n<br />\r\n(எனவே, நிராகரிப்பவர்களுக்கு அவகாசம் அளிப்பீராக; அவர்களுக்குச் சிறிது கால அவகாசம் கொடுப்பீராக.) (<a href=\"qurandisp.php?sura=86&ayah=17\" class=\"link\">86:17</a>) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">سَاعَةً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّهَارٍ</span><br />\r\n<br />\r\n(தங்களுக்கு வாக்களிக்கப்பட்டதை அவர்கள் காணும் நாளில், பகலில் ஒரு மணி நேரமே தவிர தாங்கள் (இவ்வுலகில்) தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَهَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَشِيَّةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضُحَاهَا</span><br />\r\n<br />\r\n(அவர்கள் அதனைக் (மறுமை நேரத்தைக்) காணும் நாளில், ஒரு மாலையோ அல்லது ஒரு காலையோ தவிர தாங்கள் தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்.) (<a href=\"qurandisp.php?sura=79&ayah=46\" class=\"link\">79:46</a>) மேலும் அவன் கூறுவது போல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَحْشُرُهُمْ</span> <span class=\"quran-arabic-font text-success\">كَأَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">سَاعَةً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">يَتَعَارَفُونَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span><br />\r\n<br />\r\n(அவன் அவர்களை ஒன்றுதிரட்டும் நாளில், பகலில் ஒரு மணி நேரமே தவிர தாங்கள் தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்; அவர்கள் ஒருவரையொருவர் அடையாளம் கண்டுகொள்வார்கள்.) (<a href=\"qurandisp.php?sura=10&ayah=45\" class=\"link\">10:45</a>) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلاَغٌ</span><br />\r\n<br />\r\n(இது ஒரு தெளிவான செய்தி.) அதாவது, இந்த குர்ஆன் ஒரு தெளிவான கருத்தை வழங்குகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">يُهْلَكُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمُ</span> <span class=\"quran-arabic-font text-success\">الْفَاسِقُونَ</span><br />\r\n<br />\r\n(ஆனால், பாவம் செய்யும் (வரம்பு மீறிய) மக்களைத் தவிர வேறு எவரும் அழிக்கப்படுவார்களா?) அதாவது, அழிவுக்கான வழியைத் தேர்ந்தெடுப்பவர்களைத் தவிர வேறு எவரையும் அல்லாஹ் அழிப்பதில்லை. தண்டிப்பதற்குத் தகுதியானவர்களைத் தவிர வேறு எவரையும் அவன் தண்டிப்பதில்லை என்பது அல்லாஹ்வின் நீதியின் ஒரு பகுதியாகும் - அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் சூரா அல்-அஹ்காஃபின் விளக்கம் நிறைவடைகிறது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது. வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனது உதவியாலேயே ஏற்படுகின்றன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நபியவர்களைப் பொறுமையுடன் இருக்குமாறு ஏவுதல்\n\r\n\n\r\nபின்னர், அல்லாஹ் தனது தூதரை (ஸல்), அவரது மக்களில் அவரை நிராகரித்தவர்களிடம் பொறுமையைக் கடைப்பிடிக்குமாறு ஏவுகிறான். அவன் கூறுகிறான்:\n\r\n\n\r\nفَاصْبِرْ كَمَا صَبَرَ أُوْلُواْ الْعَزْمِ مِنَ الرُّسُلِ\n\r\n\n\r\n(ஆகவே, தூதர்களில் உறுதிமிக்கவர்கள் பொறுமையாக இருந்ததுபோல நீரும் பொறுமையாக இருப்பீராக.) அதாவது, அவர்கள் தம் மக்கள் தங்களை நிராகரித்தபோது எவ்வாறு பொறுமையாக இருந்தார்களோ, அதுபோல. தூதர்களில் \"உறுதிமிக்கவர்கள்\" (உலுல் அஸ்ம்) என்போர் நூஹ் (அலை), இப்ராஹீம் (அலை), மூஸா (அலை), ஈஸா (அலை) மற்றும் அனைத்து நபிமார்களுக்கும் இறுதியானவரான முஹம்மது (ஸல்) ஆகியோராவார்கள். அல்லாஹ் இவர்களுடைய பெயர்களை சூரா அல்-அஹ்ஸாப் (33:7) மற்றும் சூரா அஷ்-ஷூரா (42:13) ஆகிய இரு வசனங்களில் குறிப்பாகக் குறிப்பிட்டுள்ளான்.\n\r\n\n\r\nوَلاَ تَسْتَعْجِل لَّهُمْ\n\r\n\n\r\n(மேலும், அவர்களுக்காக நீர் அவசரப்படாதீர்.) அதாவது, 'அவர்களுக்கான தண்டனையை வரவழைப்பதில் அவசரப்படாதீர்.' இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றதாகும்:\n\r\n\n\r\nوَذَرْنِى وَالْمُكَذِّبِينَ أُوْلِى النَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاً\n\r\n\n\r\n(மேலும், நிராகரிப்பவர்களையும், சுகபோகங்களை உடையவர்களையும் என்னிடம் விட்டுவிடுவீராக; அவர்களுக்குச் சிறிது அவகாசம் அளிப்பீராக.) (73:11)\n\r\n\n\r\nفَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْداً\n\r\n\n\r\n(எனவே, நிராகரிப்பவர்களுக்கு அவகாசம் அளிப்பீராக; அவர்களுக்குச் சிறிது கால அவகாசம் கொடுப்பீராக.) (86:17) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُواْ إِلاَّ سَاعَةً مِّن نَّهَارٍ\n\r\n\n\r\n(தங்களுக்கு வாக்களிக்கப்பட்டதை அவர்கள் காணும் நாளில், பகலில் ஒரு மணி நேரமே தவிர தாங்கள் (இவ்வுலகில்) தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்.) இது அல்லாஹ்வின் பின்வரும் கூற்றைப் போன்றது:\n\r\n\n\r\nكَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُواْ إِلاَّ عَشِيَّةً أَوْ ضُحَاهَا\n\r\n\n\r\n(அவர்கள் அதனைக் (மறுமை நேரத்தைக்) காணும் நாளில், ஒரு மாலையோ அல்லது ஒரு காலையோ தவிர தாங்கள் தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்.) (79:46) மேலும் அவன் கூறுவது போல்,\n\r\n\n\r\nوَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُواْ إِلاَّ سَاعَةً مِّنَ النَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ\n\r\n\n\r\n(அவன் அவர்களை ஒன்றுதிரட்டும் நாளில், பகலில் ஒரு மணி நேரமே தவிர தாங்கள் தங்கியிருக்கவில்லை என்று அவர்கள் கருதுவார்கள்; அவர்கள் ஒருவரையொருவர் அடையாளம் கண்டுகொள்வார்கள்.) (10:45) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nبَلاَغٌ\n\r\n\n\r\n(இது ஒரு தெளிவான செய்தி.) அதாவது, இந்த குர்ஆன் ஒரு தெளிவான கருத்தை வழங்குகிறது.\n\r\n\n\r\nفَهَلْ يُهْلَكُ إِلاَّ الْقَوْمُ الْفَاسِقُونَ\n\r\n\n\r\n(ஆனால், பாவம் செய்யும் (வரம்பு மீறிய) மக்களைத் தவிர வேறு எவரும் அழிக்கப்படுவார்களா?) அதாவது, அழிவுக்கான வழியைத் தேர்ந்தெடுப்பவர்களைத் தவிர வேறு எவரையும் அல்லாஹ் அழிப்பதில்லை. தண்டிப்பதற்குத் தகுதியானவர்களைத் தவிர வேறு எவரையும் அவன் தண்டிப்பதில்லை என்பது அல்லாஹ்வின் நீதியின் ஒரு பகுதியாகும் - அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் சூரா அல்-அஹ்காஃபின் விளக்கம் நிறைவடைகிறது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது. வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனது உதவியாலேயே ஏற்படுகின்றன."}}};})(self);
